# Exit codes (documented in README; modes must use these).
KIT_EXIT_OK=0
KIT_EXIT_FAIL=1        # a check failed / operation failed
KIT_EXIT_USAGE=2       # bad input, missing env var in non-interactive mode
KIT_EXIT_PRECOND=3     # not root, no systemd, unsupported OS, container
KIT_EXIT_ABORTED=4     # operator declined a confirmation

# ---------------------------------------------------------------- colors
# Muted "Slate Dark" accents, low glare for screen shares. Truecolor when the
# terminal says so, basic ANSI otherwise, none when NO_COLOR or not a TTY.
kit_init_colors() {
  C_OK=""; C_WARN=""; C_FAIL=""; C_INFO=""; C_DIM=""; C_HEAD=""; C_ACC=""; C_RST=""
  if [ -n "${NO_COLOR:-}" ] || [ ! -t 1 ]; then return 0; fi
  if [ "${COLORTERM:-}" = "truecolor" ] || [ "${COLORTERM:-}" = "24bit" ]; then
    C_OK=$'\e[38;2;124;201;142m'; C_WARN=$'\e[38;2;229;145;118m'; C_FAIL=$'\e[38;2;224;128;143m'
    C_INFO=$'\e[38;2;124;172;239m'; C_DIM=$'\e[38;2;167;176;188m'; C_HEAD=$'\e[38;2;227;231;236m\e[1m'
    C_ACC=$'\e[38;2;91;200;180m'
  else
    C_OK=$'\e[32m'; C_WARN=$'\e[33m'; C_FAIL=$'\e[31m'; C_INFO=$'\e[36m'; C_DIM=$'\e[2m'; C_HEAD=$'\e[1m'; C_ACC=$'\e[36m'
  fi
  C_RST=$'\e[0m'
}
kit_init_colors

# ---------------------------------------------------------------- output
KIT_PASS=0; KIT_WARN=0; KIT_FAIL=0
ok()   { KIT_PASS=$((KIT_PASS+1)); printf '  %s[ OK ]%s %s\n' "$C_OK" "$C_RST" "$*"; }
warn() { KIT_WARN=$((KIT_WARN+1)); printf '  %s[WARN]%s %s\n' "$C_WARN" "$C_RST" "$*"; }
fail() { KIT_FAIL=$((KIT_FAIL+1)); printf '  %s[FAIL]%s %s\n' "$C_FAIL" "$C_RST" "$*"; }
info() { printf '  %s[INFO]%s %s\n' "$C_INFO" "$C_RST" "$*"; }
note() { printf '         %s%s%s\n' "$C_DIM" "$*" "$C_RST"; }   # indented detail under the line above
kit_have() { command -v "$1" >/dev/null 2>&1; }

kit_banner() { # kit_banner "Mode title"
  printf '\n%s+----------------------------------------------------------------------+%s\n' "$C_ACC" "$C_RST"
  printf '%s|%s %s%-68s%s %s|%s\n' "$C_ACC" "$C_RST" "$C_HEAD" "StrongDM Proxy Cluster Kit v$KIT_VERSION" "$C_RST" "$C_ACC" "$C_RST"
  printf '%s|%s %-68s %s|%s\n' "$C_ACC" "$C_RST" "${1:-}" "$C_ACC" "$C_RST"
  printf '%s|%s %-68s %s|%s\n' "$C_ACC" "$C_RST" "host $(kit_hostname)  $(date '+%F %T %Z')" "$C_ACC" "$C_RST"
  printf '%s+----------------------------------------------------------------------+%s\n' "$C_ACC" "$C_RST"
}
kit_step() { # kit_step N TOTAL "title"   -> big, numbered, easy to follow on a screen share
  printf '\n%s== STEP %s/%s  %s%s\n' "$C_HEAD" "$1" "$2" "$3" "$C_RST"
}
kit_section() { printf '\n%s== %s%s\n' "$C_HEAD" "$*" "$C_RST"; }

# kit_die CODE "WHAT failed" "WHY it matters / what we saw" "FIX: exact command(s), one per line"
# Prints a boxed, screen-share-readable error and exits. Never put secrets in it.
kit_die() {
  local code=$1 what=$2 why=${3:-} fix=${4:-}
  printf '\n%s+---- ERROR -----------------------------------------------------------+%s\n' "$C_FAIL" "$C_RST"
  printf '%s|%s WHAT: %s\n' "$C_FAIL" "$C_RST" "$what"
  if [ -n "$why" ]; then while IFS= read -r l; do printf '%s|%s WHY:  %s\n' "$C_FAIL" "$C_RST" "$l"; done <<<"$why"; fi
  if [ -n "$fix" ]; then while IFS= read -r l; do printf '%s|%s FIX:  %s\n' "$C_FAIL" "$C_RST" "$l"; done <<<"$fix"; fi
  printf '%s|%s LOG:  %s\n' "$C_FAIL" "$C_RST" "${KIT_LOG_FILE:-(not logging)}"
  printf '%s+----------------------------------------------------------------------+%s\n' "$C_FAIL" "$C_RST"
  exit "$code"
}

kit_summary() { # prints PASS/WARN/FAIL totals; returns 1 when any FAIL
  printf '\n%s== Summary%s\n  %s%d ok%s   %s%d warning(s)%s   %s%d failure(s)%s\n' \
    "$C_HEAD" "$C_RST" "$C_OK" "$KIT_PASS" "$C_RST" "$C_WARN" "$KIT_WARN" "$C_RST" "$C_FAIL" "$KIT_FAIL" "$C_RST"
  [ -n "${KIT_LOG_FILE:-}" ] && printf '  full transcript: %s\n' "$KIT_LOG_FILE"
  [ "$KIT_FAIL" -eq 0 ]
}

# ---------------------------------------------------------------- logging
# kit_log_init MODE : tee everything to $KIT_LOG_DIR/<mode>-<ts>.log (0600).
# Review operational transcripts locally before sharing.
kit_log_init() {
  [ "$(id -u)" = 0 ] || return 0
  if ! kit_private_dir "$KIT_LOG_DIR"; then
    kit_private_dir "$KIT_DIR" || kit_die 3 "Unsafe administrative directory." "" "Review $KIT_DIR."
    KIT_LOG_DIR="$KIT_DIR/logs"
    kit_private_dir "$KIT_LOG_DIR" || kit_die 3 "Unsafe transcript directory." "" "Review $KIT_LOG_DIR."
  fi
  KIT_LOG_FILE=$(mktemp "$KIT_LOG_DIR/$1-$(date +%Y%m%d-%H%M%S).XXXXXX.log") ||
    kit_die 3 "Cannot open a private transcript." "" "Check permissions and free space in $KIT_LOG_DIR."
  # tee -i + ignored INT: Ctrl-C must not kill the logger, or the next write
  # SIGPIPEs the script before its EXIT handlers (reverts, scrub) can run.
  exec > >(trap '' INT HUP; exec tee -i -a "$KIT_LOG_FILE") 2>&1
}

# ---------------------------------------------------------------- exit traps
# Stack of cleanup commands run on EXIT (LIFO). Secrets are always scrubbed.
KIT_ON_EXIT=()
kit_on_exit() { KIT_ON_EXIT+=("$1"); }
KIT_SECRET_VARS=()
kit_secret_register() { KIT_SECRET_VARS+=("$@"); }      # names of vars holding secrets
kit_scrub() {
  local v
  for v in "${KIT_SECRET_VARS[@]:-}"; do
    [ -n "$v" ] || continue
    printf -v "$v" '%s' ''; unset "$v"
  done
  return 0
}
kit_run_exit_handlers() {
  local rc=$? i
  for ((i=${#KIT_ON_EXIT[@]}-1; i>=0; i--)); do eval "${KIT_ON_EXIT[i]}" || true; done
  kit_scrub
  return $rc
}
trap kit_run_exit_handlers EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 129' HUP   # SSH / SSM disconnect: still run the EXIT handlers

# ---------------------------------------------------------------- prompts
# Interactive = a usable /dev/tty. Every prompt reads from /dev/tty so the
# script works when its own source arrived on stdin (curl | bash, bash -s).
kit_tty_ok() { { : </dev/tty; } 2>/dev/null; }
kit_noninteractive() { ! kit_tty_ok || [ "${KIT_NONINTERACTIVE:-}" = 1 ]; }

# kit_ask VAR "Prompt" [default]  - visible input. If $VAR already set (env), uses it.
kit_ask() {
  local __v=$1 __p=$2 __d=${3:-} __in
  if [ -n "${!__v:-}" ]; then info "$__p: using \$$__v from the environment"; return 0; fi
  if kit_noninteractive; then
    [ -n "$__d" ] && { printf -v "$__v" '%s' "$__d"; return 0; }
    kit_die $KIT_EXIT_USAGE "Missing required value: $__v" "Running non-interactively, so nothing can be prompted for." "export $__v='...' and re-run"
  fi
  printf '  %s?%s %s%s: ' "$C_ACC" "$C_RST" "$__p" "${__d:+ [$__d]}" >/dev/tty
  IFS= read -r __in </dev/tty || __in=""
  [ -z "$__in" ] && __in=$__d
  printf -v "$__v" '%s' "$__in"
}

# kit_ask_secret VAR "Prompt"  - hidden, entered twice, never echoed, registered for scrub.
kit_ask_secret() {
  local __v=$1 __p=$2 __a __b __try
  kit_secret_register "$__v"
  if [ -n "${!__v:-}" ]; then info "$__p: using \$$__v from the environment (value not shown)"; return 0; fi
  kit_noninteractive && kit_die $KIT_EXIT_USAGE "Missing required secret: $__v" "Running non-interactively, so nothing can be prompted for." "export $__v='...' (e.g. from your secrets manager) and re-run"
  for __try in 1 2 3; do
    printf '  %s?%s %s (hidden): ' "$C_ACC" "$C_RST" "$__p" >/dev/tty; IFS= read -rs __a </dev/tty; printf '\n' >/dev/tty
    printf '  %s?%s confirm %s: ' "$C_ACC" "$C_RST" "$__p" >/dev/tty;      IFS= read -rs __b </dev/tty; printf '\n' >/dev/tty
    if [ -z "$__a" ]; then warn "empty value, try again"; continue; fi
    if [ "$__a" != "$__b" ]; then warn "the two entries did not match, try again"; continue; fi
    printf -v "$__v" '%s' "$__a"; __a=""; __b=""; return 0
  done
  __a=""; __b=""
  kit_die $KIT_EXIT_USAGE "Could not read $__v" "Three attempts were empty or did not match." "Re-run the kit and type the value carefully (paste works)."
}

# kit_confirm "Question" [default y|n] -> 0 yes / 1 no. Non-interactive: honours KIT_ASSUME_YES=1.
kit_confirm() {
  local q=$1 d=${2:-n} a
  if kit_noninteractive; then [ "${KIT_ASSUME_YES:-}" = 1 ]; return; fi
  printf '  %s?%s %s %s: ' "$C_ACC" "$C_RST" "$q" "$([ "$d" = y ] && echo '[Y/n]' || echo '[y/N]')" >/dev/tty
  IFS= read -r a </dev/tty || a=""; a=${a:-$d}
  case $a in y|Y|yes|YES|Yes) return 0;; *) return 1;; esac
}

# kit_confirm_typed WORD "Explanation"  -> operator must type WORD exactly. Non-interactive: KIT_REPLACE=yes.
kit_confirm_typed() {
  local w=$1 msg=$2 a
  if kit_noninteractive; then [ "${KIT_REPLACE:-}" = yes ]; return; fi
  printf '  %s?%s %s\n    Type %s%s%s to continue, anything else aborts: ' "$C_ACC" "$C_RST" "$msg" "$C_HEAD" "$w" "$C_RST" >/dev/tty
  IFS= read -r a </dev/tty || a=""
  [ "$a" = "$w" ]
}

# kit_pick VAR "Title" "opt1" "opt2" ... -> VAR = chosen option text (1-based numbered menu).
kit_pick() {
  local __v=$1 __t=$2; shift 2
  local __i __a
  if [ -n "${!__v:-}" ]; then return 0; fi
  kit_noninteractive && kit_die $KIT_EXIT_USAGE "Missing choice: $__v" "Non-interactive run." "export $__v=<one of: $*>"
  while :; do
    printf '\n  %s%s%s\n' "$C_HEAD" "$__t" "$C_RST" >/dev/tty
    __i=1; for __a in "$@"; do printf '    %s%d)%s %s\n' "$C_ACC" "$__i" "$C_RST" "$__a" >/dev/tty; __i=$((__i+1)); done
    printf '  %s?%s choose 1-%d: ' "$C_ACC" "$C_RST" "$#" >/dev/tty; IFS= read -r __a </dev/tty || __a=""
    if [[ $__a =~ ^[0-9]+$ ]] && [ "$__a" -ge 1 ] && [ "$__a" -le $# ]; then printf -v "$__v" '%s' "${!__a}"; return 0; fi
    warn "'$__a' is not a choice"
  done
}

# ---------------------------------------------------------------- platform
kit_hostname() { hostname 2>/dev/null || cat /proc/sys/kernel/hostname 2>/dev/null || echo unknown; }
kit_is_root() { [ "$(id -u)" = 0 ]; }
kit_require_root() {
  kit_is_root || kit_die $KIT_EXIT_PRECOND "This needs root." "It manages users, services and /etc/sysconfig." \
    "sudo -i            # become root, then re-run
bash $KIT_DIR/$KIT_NAME.sh"
}
kit_in_container() {
  [ -f /.dockerenv ] || [ -f /run/.containerenv ] || grep -qaE '(docker|kubepods|containerd|libpod)' /proc/1/cgroup 2>/dev/null \
    || [ "${container:-}" != "" ] || { kit_have systemd-detect-virt && systemd-detect-virt --container >/dev/null 2>&1; }
}
kit_has_systemd() { [ -d /run/systemd/system ] && kit_have systemctl; }
# Sets OS_ID OS_VERSION_ID OS_PRETTY OS_FAMILY(rhel|debian|unknown) PKG_MGR(dnf|yum|apt|"")
kit_detect_os() {
  OS_ID=unknown; OS_VERSION_ID=""; OS_PRETTY="unknown"; OS_FAMILY=unknown; PKG_MGR=""
  if [ -r /etc/os-release ]; then
    OS_ID=$(. /etc/os-release; echo "${ID:-unknown}")
    OS_VERSION_ID=$(. /etc/os-release; echo "${VERSION_ID:-}")
    OS_PRETTY=$(. /etc/os-release; echo "${PRETTY_NAME:-$ID}")
    case " $(. /etc/os-release; echo "${ID:-} ${ID_LIKE:-}") " in
      *" rhel "*|*" fedora "*|*" centos "*|*" amzn "*) OS_FAMILY=rhel;;
      *" debian "*|*" ubuntu "*) OS_FAMILY=debian;;
    esac
  fi
  if kit_have dnf; then PKG_MGR=dnf; elif kit_have yum; then PKG_MGR=yum; elif kit_have apt-get; then PKG_MGR=apt; fi
}
# kit_arch -> amd64 | arm64 (exits on anything else)
kit_arch() {
  case "$(uname -m)" in
    x86_64|amd64) echo amd64;; aarch64|arm64) echo arm64;;
    *) kit_die $KIT_EXIT_PRECOND "Unsupported CPU architecture: $(uname -m)" "StrongDM publishes Linux builds for amd64 and arm64 only." "";;
  esac
}
kit_selinux_mode() { if kit_have getenforce; then getenforce 2>/dev/null; else echo Disabled; fi; }

# kit_ensure_cmds cmd... : installs missing tools via the package manager (says what and why).
kit_ensure_cmds() {
  local missing=() c pkgs=()
  for c in "$@"; do kit_have "$c" || missing+=("$c"); done
  [ ${#missing[@]} -eq 0 ] && return 0
  for c in "${missing[@]}"; do
    case $c in sha256sum|base64|stat|timeout) pkgs+=(coreutils);; getent) pkgs+=(glibc-common);; ss) pkgs+=(iproute2);; *) pkgs+=("$c");; esac
  done
  [ -n "${PKG_MGR:-}" ] || kit_detect_os
  info "installing missing tool(s): ${missing[*]} (package: ${pkgs[*]})"
  case $PKG_MGR in
    dnf) dnf install -y -q "${pkgs[@]}" >/dev/null 2>&1 ;;
    yum) yum install -y -q "${pkgs[@]}" >/dev/null 2>&1 ;;
    apt) { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "${pkgs[@]}"; } >/dev/null 2>&1 ;;
    *) false ;;
  esac || true
  for c in "${missing[@]}"; do
    kit_have "$c" || kit_die $KIT_EXIT_PRECOND "Required tool '$c' is missing and could not be installed." \
      "Package manager: ${PKG_MGR:-none found}. The host may have no repo access." \
      "Install it yourself, then re-run:
dnf install -y ${pkgs[*]}      # RHEL / Rocky / Alma / Amazon Linux
apt-get install -y ${pkgs[*]}  # Ubuntu / Debian"
  done
  ok "installed: ${missing[*]}"
}

# ---------------------------------------------------------------- node inspection
# kit_find_node_procs -> lines "pid|user|role|exe|cwd|start_epoch" for running sdm worker/relay/gateway/proxy.
kit_find_node_procs() {
  local d exe cwd cmd role pid uid user clk now upt st
  clk=$(getconf CLK_TCK 2>/dev/null || echo 100); now=$(date +%s); upt=$(awk '{print int($1)}' /proc/uptime 2>/dev/null || echo 0)
  for d in /proc/[0-9]*; do
    cmd=$(tr '\0' ' ' < "$d/cmdline" 2>/dev/null) || continue
    # /proc/PID/exe is unreadable for other users' processes in containers without
    # CAP_SYS_PTRACE; fall back to argv[0] so the worker is still found.
    exe=$(readlink "$d/exe" 2>/dev/null) || exe=${cmd%% *}
    case ${exe##*/} in sdm*) ;; *) continue;; esac
    role=$(printf '%s' "$cmd" | grep -oE ' (worker|relay|gateway|proxy)( |$)' | head -1 | tr -d ' ')
    [ -n "$role" ] || continue
    pid=${d#/proc/}
    uid=$(awk '/^Uid:/{print $2}' "$d/status" 2>/dev/null)
    user=$(awk -F: -v u="$uid" '$3==u{print $1; exit}' /etc/passwd); user=${user:-$uid}
    st=$(awk -v clk="$clk" -v up="$upt" -v now="$now" '{sub(/.*\) /,""); print int(now-up+$20/clk)}' "$d/stat" 2>/dev/null)
    cwd=$(readlink "$d/cwd" 2>/dev/null)
    [[ $exe$cwd != *'|'* && $exe$cwd != *[[:cntrl:]]* ]] || continue
    printf '%s|%s|%s|%s|%s|%s\n' "$pid" "$user" "$role" "$exe" "$cwd" "$st"
  done
}
# kit_proc_env PID KEY -> prints value, returns 1 if unset/unreadable. Never echo secret keys' values to the screen.
kit_proc_env() {
  tr '\0' '\n' < "/proc/$1/environ" 2>/dev/null | awk -v k="$2" 'index($0,k"=")==1{print substr($0,length(k)+2); f=1; exit} END{exit !f}'
}
# Detach worker programs from the operator's controlling terminal. Keep the
# wrapper waiting even with older setsid versions that lack --wait.
kit_run_unprivileged() (
  local user=$1 uid
  shift
  uid=$(id -u "$user") && [ "$uid" -gt 0 ] || exit 1
  local switch=()
  if kit_is_root; then switch=(runuser -u "$user" --)
  elif [ "$(id -u)" != "$uid" ]; then exit 1; fi
  set +m
  cd / || exit 1
  env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin setsid ${switch[@]+"${switch[@]}"} "$@" 9>&-
  exit "$?"
)
kit_as_worker() {
  local d=$1
  shift
  kit_run_unprivileged "$SDM_USER" env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin HOME="$SDM_USER_HOME" SDM_HOME="$d" SDM_LOG_OUTPUT=stderr "$@"
}

kit_trusted_dir() {
  local d=$1 mode
  [[ $d == /* ]] || return 1
  while :; do
    [ -d "$d" ] && [ ! -L "$d" ] && [ "$(stat -c %u "$d")" = 0 ] || return 1
    mode=$(stat -c %a "$d") || return 1
    (( (8#$mode & 022) == 0 )) || return 1
    [ "$d" = / ] && return 0
    d=$(dirname -- "$d") || return 1
  done
}
kit_private_dir() {
  local dir=$1
  kit_trusted_dir "$(dirname -- "$dir")" && [ ! -L "$dir" ] || return 1
  if [ ! -d "$dir" ]; then (umask 077; mkdir "$dir") || return 1; fi
  [ "$(stat -c '%u:%a' "$dir")" = 0:700 ]
}

kit_trusted_file() {
  local f=$1 mode
  [ ! -L "$f" ] && [ -f "$f" ] && kit_trusted_dir "$(dirname -- "$f")" && [ "$(stat -c %u -- "$f")" = 0 ] || return 1
  mode=$(stat -c %a -- "$f") && (( (8#$mode & 022) == 0 ))
}

kit_lock_changes() {
  kit_have flock || kit_die 3 "Install and debug require flock." "" "Install util-linux."
  kit_private_dir "$KIT_DIR" || kit_die 3 "Unsafe administrative directory." "" "Review $KIT_DIR."
  exec 9>"$KIT_DIR/install.lock" && flock -n 9 || kit_die 1 "Another install or debug session holds the kit lock." "" "Retry after that session finishes."
}

kit_https_url() {
  local pattern='^https://[a-zA-Z0-9.-]+(:[0-9]+)?(/[a-zA-Z0-9._~/%+=-]*)?$'
  [[ $1 =~ $pattern ]]
}

kit_unit_exists() { kit_has_systemd && systemctl cat "$1" >/dev/null 2>&1 </dev/null; }
# systemd 219 (RHEL 7 / Amazon Linux 2) has no `systemctl show --value`; strip "Name=" ourselves.
kit_unit_prop() { systemctl show -p "$2" "$1" 2>/dev/null </dev/null | sed 's/^[^=]*=//'; }   # kit_unit_prop UNIT User|MainPID|ActiveState|WorkingDirectory|ExecStart|EnvironmentFiles
kit_unit_main_pid() { local p; p=$(kit_unit_prop "$1" MainPID); [ -n "$p" ] && [ "$p" != 0 ] && echo "$p"; }

# Read and edit whole systemd EnvironmentFile assignments. A quoted or
# backslash-continued value can contain physical lines that look like new keys.
kit_envfile_records() { # get|has|omit|names, optional space-separated keys; reads stdin
  local op=$1 keys=" ${2:-} " line key record rest state slashes last=""
  local assignment='^[[:blank:]]*(export[[:blank:]]+)?([a-zA-Z_][a-zA-Z0-9_]*)[[:blank:]]*=(.*)$'
  while IFS= read -r line || [ -n "$line" ]; do
    record=$line; key=""
    if [[ $line =~ $assignment ]]; then
      key=${BASH_REMATCH[2]}; rest=${BASH_REMATCH[3]}; state=start
    elif [[ $line =~ ^[[:blank:]]*[\#\;] ]]; then
      rest=$line; state=bare
    else
      rest=""; state=bare
    fi
    while :; do
      case $state in
        start)
          rest=${rest#"${rest%%[!$' \t\r']*}"}
          case $rest in
            \'*) state=single; rest=${rest:1}; continue;;
            \"*) state=double; rest=${rest:1}; continue;;
            *) state=bare; continue;;
          esac;;
        single)
          if [[ $rest == *\'* ]]; then rest=${rest#*\'}; state=start; continue; fi;;
        double)
          rest=${rest#"${rest%%[\\\"]*}"}
          case $rest in
            \"*) rest=${rest:1}; state=start; continue;;
            \\?*) rest=${rest:2}; continue;;
          esac;;
        bare)
          slashes=${rest##*[!\\]}
          (( ${#slashes} % 2 )) || break;;
      esac
      # Fail safely on an unfinished record rather than append settings to it.
      rest=""; IFS= read -r rest || [ -n "$rest" ] || return 2
      record+=$'\n'"$rest"
    done
    if [ "$op" = names ]; then
      [ -z "$key" ] || printf '%s ' "$key"
    elif [ -n "$key" ] && [[ $keys == *" $key "* ]]; then
      case $op in has) return 0;; get) last=${record#*=};; esac
    elif [ "$op" = omit ]; then printf '%s\n' "$record" || return 2; fi
  done
  case $op in get) [ -n "$last" ] && printf '%s\n' "$last";; has) return 1;; omit|names) return 0;; esac
}
kit_envfile_get() { [ -r "$1" ] && kit_envfile_records get "$2" < "$1"; }
kit_envfile_has() { [ -r "$1" ] && kit_envfile_records has "$2" < "$1"; }

# Replace a set of keys as one root-private file. New assignment lines arrive
# on stdin, so values never become external command arguments.
kit_envfile_update() { # FILE "keys to remove" < replacement lines
  local f=$1 keys=$2 tmp
  tmp=$(mktemp "${f}.XXXXXX") || return 1
  if { [ ! -e "$f" ] || kit_envfile_records omit "$keys" < "$f"; } > "$tmp" &&
     cat >> "$tmp" && chmod 0600 "$tmp" && mv -fT "$tmp" "$f"; then return 0; fi
  rm -f -- "$tmp"; return 1
}
kit_envfile_set() {
  [[ $3 != *$'\n'* && $3 != *$'\r'* ]] || return 1
  kit_envfile_update "$1" "$2" <<<"$2=$3"
}
kit_envfile_unset() {
  local rc=0
  kit_envfile_has "$1" "$2" || rc=$?
  [ "$rc" = 1 ] && return 0
  [ "$rc" = 0 ] || return "$rc"
  kit_envfile_update "$1" "$2" </dev/null
}

# ---------------------------------------------------------------- network
kit_tcp_ok() { # host port
  if kit_have timeout; then timeout 6 bash -c 'exec 3<>"/dev/tcp/$0/$1"' "$1" "$2" 2>/dev/null
  else (exec 3<>"/dev/tcp/$1/$2") 2>/dev/null; fi
}
# kit_http METHOD URL [form-body] [bearer] -> sets HB (body) HC (http code) HE (curl exit).
# Sensitive bodies and headers use stdin. Never follow redirects with credentials.
kit_http() {
  local method=$1 url=$2 body=${3:-} token=${4:-} cfg="" out
  local args=(-q --silent --show-error --globoff --max-time 60 --proto '=https' --request "$method" --write-out $'\n__HTTP__%{http_code}')
  HB=""; HC=000; HE=1
  [[ $url == https://* && $url != *[[:cntrl:]]* ]] || return 0
  if [ -n "$body" ]; then
    local form_pattern='^[a-zA-Z0-9%_=&.+~-]+$'
    [[ $body =~ $form_pattern ]] || return 0
    cfg+="data = \"$body\""$'\n'
  fi
  if [ -n "$token" ]; then
    [[ $token =~ ^[A-Za-z0-9._~+/=-]+$ ]] || return 0
    cfg+="header = \"Authorization: Bearer $token\""$'\n'
  fi
  out=$(printf '%s' "$cfg" | curl "${args[@]}" -K - --url "$url" 2>/dev/null); HE=$?
  HC=${out##*__HTTP__}; HB=${out%$'\n'__HTTP__*}; [[ $HC =~ ^[0-9]{3}$ ]] || HC=000
  return 0
}

# ---------------------------------------------------------------- JSON (no jq)
# json_flat < json  -> "path<TAB>type<TAB>escaped-value" (type s|l). Decode a value with printf '%b'.
json_flat() { LC_ALL=C awk '
function ws(){ while (i<=n && index(" \t\r\n", substr(s,i,1))) i++ }
function hex(h,  k,v){ v=0; h=tolower(h); for(k=1;k<=4;k++) v=v*16+index("0123456789abcdef",substr(h,k,1))-1; return v }
function utf8(c){ if(c<128) return sprintf("%c",c)
  if(c<2048) return sprintf("%c%c",192+int(c/64),128+c%64)
  if(c<65536) return sprintf("%c%c%c",224+int(c/4096),128+int(c/64)%64,128+c%64)
  return sprintf("%c%c%c%c",240+int(c/262144),128+int(c/4096)%64,128+int(c/64)%64,128+c%64) }
function str(  o,c,e,u,u2){ o=""; i++
  while(i<=n){ c=substr(s,i,1)
    if(c=="\"") { i++; return o }
    if(c=="\\"){ e=substr(s,i+1,1); i+=2
      if(e=="n") o=o "\n"; else if(e=="t") o=o "\t"; else if(e=="r") o=o "\r"
      else if(e=="b") o=o "\b"; else if(e=="f") o=o "\f"
      else if(e=="u"){ u=hex(substr(s,i,4)); i+=4
        if(u>=55296 && u<56320 && substr(s,i,2)=="\\u"){ u2=hex(substr(s,i+2,4)); i+=6; u=65536+(u-55296)*1024+(u2-56320) }
        o=o utf8(u) }
      else o=o e
      continue }
    o=o c; i++ }
  return o }
function esc(v,  o,k,c){ o=""; for(k=1;k<=length(v);k++){ c=substr(v,k,1)
    if(c=="\\") o=o "\\\\"; else if(c=="\t") o=o "\\t"; else if(c=="\n") o=o "\\n"; else if(c=="\r") o=o "\\r"
    else if(c<" ") o=o sprintf("\\x%02x", index(ctl,c)); else o=o c }
  return o }
function val(p,  k,c,lit){ ws(); c=substr(s,i,1)
  if(c=="{"){ i++; ws(); if(substr(s,i,1)=="}"){i++;return}
    while(1){ ws(); k=str(); ws(); i++; val(p (p==""?"":".") k); ws(); c=substr(s,i,1); i++; if(c!=",") return } }
  if(c=="["){ i++; ws(); if(substr(s,i,1)=="]"){i++;return}; k=0
    while(1){ val(p "." k); k++; ws(); c=substr(s,i,1); i++; if(c!=",") return } }
  if(c=="\""){ print p "\ts\t" esc(str()); return }
  lit=""; while(i<=n && !index(",]} \t\r\n", substr(s,i,1))){ lit=lit substr(s,i,1); i++ }
  print p "\tl\t" lit }
BEGIN{ for(k=1;k<32;k++) ctl=ctl sprintf("%c",k) }
{ s=s $0 "\n" }
END{ n=length(s); i=1; val("") }'; }
# jget "<flat>" path -> decoded value (path match is case-insensitive, like Go's encoding/json).
jget() { local line; line=$(printf '%s\n' "$1" | awk -F'\t' -v p="$2" 'tolower($1)==tolower(p){print $3; exit}'); printf '%b' "$line"; }

# ---------------------------------------------------------------- value helpers (never reveal secrets)
kit_shape() { local v=$1 c=""
  [[ $v == *[a-z]* ]] && c+="lower+"; [[ $v == *[A-Z]* ]] && c+="upper+"
  [[ $v == *[0-9]* ]] && c+="digit+"; [[ $v == *[^A-Za-z0-9]* ]] && c+="symbol+"
  printf 'len=%d bytes, classes=%s' "${#v}" "${c%+}"; }
kit_anomalies() { local v=$1 out=() t LC_ALL=C
  [[ $v =~ ^[[:space:]] || $v =~ [[:space:]]$ ]] && out+=("leading/trailing whitespace")
  [[ $v == *$'\r'* || $v == *$'\n'* ]] && out+=("contains CR/LF")
  [[ $v == *$'\t'* ]] && out+=("contains TAB")
  [[ $v =~ \&(amp|lt|gt|quot|apos|#[0-9]+|#x[0-9a-fA-F]+)\; ]] && out+=("contains an HTML entity such as &amp;")
  [[ $v =~ %[0-9A-Fa-f]{2} ]] && out+=("contains %XX (maybe URL-encoded)")
  [[ $v =~ [$'\x80'-$'\xff'] ]] && out+=("contains non-ASCII bytes (accents, NBSP, zero-width, smart quotes)")
  t=${v//[$'\r\n\t']/}; [[ $t =~ [[:cntrl:]] ]] && out+=("contains control characters")
  local IFS=';'; printf '%s' "${out[*]:-}"; }
kit_trim() { local v=$1; v=${v#"${v%%[![:space:]]*}"}; printf '%s' "${v%"${v##*[![:space:]]}"}"; }
kit_html_unescape() { local v=$1; v=${v//&lt;/<}; v=${v//&gt;/>}; v=${v//&quot;/\"}; v=${v//&#39;/\'}; v=${v//&apos;/\'}; v=${v//&amp;/&}; printf '%s' "$v"; }
kit_urlencode() { local LC_ALL=C s=$1 i c o=""; for ((i=0;i<${#s};i++)); do c=${s:i:1}
  case $c in [a-zA-Z0-9.~_-]) o+=$c;; *) printf -v c '%%%02X' "'$c"; o+=$c;; esac; done; printf '%s' "$o"; }

# patsub_replacement (bash 5.2) would turn '&' in ${v//x/&} into the match. Off.
shopt -u patsub_replacement 2>/dev/null || true

# ---------------------------------------------------------------- src/modes/check.sh
# shellcheck shell=bash
# ============================================================================
# sdm-proxy-cluster-kit :: src/modes/check.sh   (mode_check - READ-ONLY)
#
# Never changes the system: no writes outside the kit's own transcript, no
# service restarts, no package installs. Every fix is printed, not applied.
#
# Sections:
#   1 Host and runtime      2 Install layout       3 Connectivity
#   4 Recent logs           5 Delinea secret store  6 Summary + likely problems
#
# ============================================================================
# @env KIT_CHECK_DELINEA  yes|no - run or skip the Delinea section without asking (default: run when any DELINEA_* setting is found)
# @env KIT_DELINEA_SERVER_URL  Trusted HTTPS server URL supplied by the operator for live checks
# @env KIT_DELINEA_USERNAME_PATH  the resource's username secret path, e.g. 1234?key=Username (empty = skip)
# @env KIT_DELINEA_PASSWORD_PATH  the resource's password secret path, e.g. 1234?key=Password (empty = skip)
# @env KIT_RDP_HOST  RDP target host[:port] to test TCP reachability from this worker (empty = skip)
# @env KIT_DELINEA_SVC_USERNAME  service-account username, used only when DELINEA_USERNAME is sealed (unreadable by design)
# @env KIT_DELINEA_SVC_PASSWORD  service-account password, used only when DELINEA_PASSWORD is sealed; never printed
# @env KIT_DELINEA_CA_FILE  Optional operator-approved CA bundle for live authentication
# @env KIT_DELINEA_LIVE  yes = enable live authentication to the explicitly supplied HTTPS server; default no
# @env KIT_DELINEA_VAULT_URL  Trusted HTTPS vault URL from the Admin UI for Platform checks
# @env HTTPS_PROXY  the operator shell's proxy (also https_proxy/HTTP_PROXY/http_proxy/NO_PROXY/no_proxy); replaced by the worker's own proxy settings so the checks see what the worker sees

# ---------------------------------------------------------------- state
chk_reset() {
  CHK_PID=""; CHK_PUSER=""; CHK_PEXE=""; CHK_PCWD=""; CHK_PSTART=""; CHK_PROCS=""
  CHK_ENVFILE=$SDM_SYSCONFIG; CHK_HOME=""; CHK_HOME_SRC=""
  CHK_SYSTEMD=0; CHK_CONTAINER=0; CHK_ROOT=0; CHK_UNIT=0; CHK_ENVREAD=0
  CHK_SECRETS_FILE=""; CHK_MOUNT_KEYS=""; CHK_MOUNT_FLAT=""; CHK_SEALED_KEYS=""; CHK_SEALED_OK=0
  CHK_STRAY_KEYS=""; CHK_APP_DOMAIN=""; CHK_APP_SRC=""; CHK_WPROXY=""; CHK_SHELL_PROXY=""
  CHK_VERSION=""
  CHK_PSEV=(); CHK_PROBS=(); CHK_FIXES=()
}

# chk_fail/chk_warn "message" "fix command(s), one per line" -> also recorded for the
# "most likely problems" list at the end.
chk_fail() { fail "$1"; CHK_PSEV+=(FAIL); CHK_PROBS+=("$1"); CHK_FIXES+=("${2:-}"); }
chk_warn() { warn "$1"; CHK_PSEV+=(WARN); CHK_PROBS+=("$1"); CHK_FIXES+=("${2:-}"); }

chk_penv() { [ -n "$CHK_PID" ] && kit_proc_env "$CHK_PID" "$1"; }
chk_unquote() { local v=$1
  if [[ $v == \'*\' && ${#v} -ge 2 ]]; then v=${v:1:${#v}-2}; elif [[ $v == \"*\" && ${#v} -ge 2 ]]; then v=${v:1:${#v}-2}; fi
  printf '%s' "$v"; }
# chk_cfg KEY -> the value the running worker sees (its environ when readable, else the env file).
chk_cfg() { local v
  if [ "$CHK_ENVREAD" = 1 ]; then kit_proc_env "$CHK_PID" "$1"; return; fi
  v=$(kit_envfile_get "$CHK_ENVFILE" "$1") || return 1
  chk_unquote "$v"; }
chk_mtime() { stat -c %Y "$1" 2>/dev/null || echo 0; }
chk_ts() { date -d "@$1" '+%F %T' 2>/dev/null || echo "$1"; }
chk_changed_after_start() { [ -n "$CHK_PSTART" ] && [ "$(chk_mtime "$1")" -gt $((CHK_PSTART + 2)) ]; }
chk_is_secret_key() {
  case $1 in *SECRET*|*PASSWORD*|*PASSWD*|*TOKEN*|*ACCESS_KEY*|*PRIVATE*|*CREDENTIAL*|*_KEY) return 0;; esac
  return 1; }
chk_realpath() { readlink -f "$1" 2>/dev/null || printf '%s' "$1"; }
chk_in_list() { [[ " $2 " == *" $1 "* ]]; }   # chk_in_list WORD "space separated list"

# ---------------------------------------------------------------- discovery (silent)
chk_discover() {
  local pid user role exe cwd st mp="" ef v
  kit_is_root && CHK_ROOT=1
  kit_in_container && CHK_CONTAINER=1
  kit_has_systemd && CHK_SYSTEMD=1
  if [ "$CHK_SYSTEMD" = 1 ] && kit_unit_exists "$SDM_UNIT"; then
    CHK_UNIT=1
    mp=$(kit_unit_main_pid "$SDM_UNIT")
    ef=$(kit_unit_prop "$SDM_UNIT" EnvironmentFiles); ef=${ef%% *}; ef=${ef#-}
    [ -n "$ef" ] && CHK_ENVFILE=$ef
  fi
  CHK_PROCS=$(kit_find_node_procs)
  while IFS='|' read -r pid user role exe cwd st; do
    [ "$role" = worker ] && [[ $pid =~ ^[0-9]+$ && $st =~ ^[0-9]{1,12}$ ]] || continue
    if [ -z "$CHK_PID" ] || [ "$pid" = "$mp" ]; then
      CHK_PID=$pid; CHK_PUSER=$user; CHK_PEXE=$exe; CHK_PCWD=$cwd; CHK_PSTART=$st
    fi
  done <<<"$CHK_PROCS"
  [ -n "$CHK_PID" ] && [ -r "/proc/$CHK_PID/environ" ] && CHK_ENVREAD=1
  # SDM_HOME as the worker resolves it: env, else its cwd (service).
  if v=$(chk_penv SDM_HOME) && [ -n "$v" ]; then CHK_HOME=$v; CHK_HOME_SRC="worker environment SDM_HOME"
  elif [ "$CHK_ENVREAD" = 1 ] && [ -n "$CHK_PCWD" ]; then CHK_HOME=$CHK_PCWD; CHK_HOME_SRC="worker working directory (SDM_HOME unset)"
  elif v=$(kit_envfile_get "$CHK_ENVFILE" SDM_HOME); then CHK_HOME=$(chk_unquote "$v"); CHK_HOME_SRC="$CHK_ENVFILE"
  elif [ -n "$CHK_PCWD" ]; then CHK_HOME=$CHK_PCWD; CHK_HOME_SRC="worker working directory"
  else CHK_HOME=$SDM_HOME_DIR; CHK_HOME_SRC="kit standard (no worker found)"; fi
  if v=$(chk_cfg SDM_APP_DOMAIN) && [ -n "$v" ]; then CHK_APP_DOMAIN=$v; CHK_APP_SRC="SDM_APP_DOMAIN"
  else CHK_APP_DOMAIN=${KIT_APP_DOMAINS[0]}; CHK_APP_SRC="default (SDM_APP_DOMAIN unset)"; fi
  # Make every network check below use the worker's proxy settings, not the operator's.
  CHK_SHELL_PROXY=${HTTPS_PROXY:-${https_proxy:-}}
  unset HTTPS_PROXY https_proxy HTTP_PROXY http_proxy NO_PROXY no_proxy
  for v in HTTPS_PROXY https_proxy HTTP_PROXY http_proxy NO_PROXY no_proxy; do
    ef=$(chk_cfg "$v") && [ -n "$ef" ] && export "$v=$ef"
  done
  CHK_WPROXY=${HTTPS_PROXY:-${https_proxy:-}}
}

# ---------------------------------------------------------------- 1 host
chk_host() {
  local m n out
  kit_section "1. Host and runtime"
  kit_detect_os
  info "OS $OS_PRETTY (family $OS_FAMILY), arch $(uname -m), kernel $(uname -r), bash $BASH_VERSION"
  [ "$OS_FAMILY" = unknown ] && chk_warn "OS family not recognised; the kit targets RHEL/Rocky/Alma 7-9, Amazon Linux 2/2023, Ubuntu/Debian" ""
  if [ "$CHK_ROOT" = 1 ]; then ok "running as root"
  else chk_warn "not running as root: the worker's environment, sealed secrets and journal may be unreadable, so some checks are incomplete" "sudo -i      # then re-run the kit and choose Check"; fi
  if [ "$CHK_CONTAINER" = 1 ]; then
    info "inside a container: settings are read from the worker's process environment and SDM_SECRETS_FILE"
  fi
  if [ "$CHK_SYSTEMD" = 1 ]; then ok "systemd present ($(systemctl --version 2>/dev/null </dev/null | head -1))"
  elif [ "$CHK_CONTAINER" = 1 ]; then info "no systemd (normal in a container); unit and journal checks are skipped"
  else chk_fail "systemd is not running; the worker is installed as a systemd unit" "use a systemd host (RHEL/Rocky/Alma 7-9, Amazon Linux 2/2023, Ubuntu/Debian)"; fi
  m=$(kit_selinux_mode)
  case $m in
    Enforcing) info "SELinux: Enforcing";;
    Permissive) info "SELinux: Permissive (denials are logged, not enforced)";;
    *) info "SELinux: ${m:-not installed}";;
  esac
  if [ "$m" != Disabled ] && [ -n "$m" ] && kit_have ausearch && [ "$CHK_ROOT" = 1 ]; then
    out=$(ausearch -m avc,user_avc -ts today -i 2>/dev/null </dev/null | grep -iE 'sdm|strongdm' | grep -i 'avc')
    n=$(printf '%s' "$out" | grep -c . )
    if [ "${n:-0}" -gt 0 ]; then
      chk_warn "$n SELinux AVC denial(s) today mention sdm/strongdm" "ausearch -m avc -ts today -i | grep -i sdm      # read them
Review the path labels and local policy with the host administrator."
    else ok "no SELinux AVC denials mentioning sdm today"; fi
  fi
  chk_clock
}

chk_clock() {
  local hdr e now d
  if ! kit_have curl; then info "curl is not installed: clock skew not checked"; return; fi
  hdr=$(curl -q --globoff --proto "=https" -sSI -m 15 "https://$CHK_APP_DOMAIN/" 2>/dev/null </dev/null | tr -d '\r' | awk 'tolower($1)=="date:"{sub(/^[^:]*:[ ]*/,""); print; exit}')
  if [ -z "$hdr" ]; then info "could not read the time from https://$CHK_APP_DOMAIN (see section 3); clock skew not checked"; return; fi
  e=$(date -d "$hdr" +%s 2>/dev/null) || { info "unparseable Date header '$hdr'"; return; }
  now=$(date +%s); d=$((now - e)); [ $d -lt 0 ] && d=$((-d))
  if [ $d -le 30 ]; then ok "clock is within ${d}s of $CHK_APP_DOMAIN"
  else
    local fixc="timedatectl set-ntp true          # systemd hosts
chronyc makestep                    # step the clock now (chrony)"
    if [ $d -le 120 ]; then chk_warn "clock is ${d}s off from $CHK_APP_DOMAIN" "$fixc"
    else chk_fail "clock is ${d}s off from $CHK_APP_DOMAIN; TLS and token validation can fail" "$fixc"; fi
  fi
}

# ---------------------------------------------------------------- 2 layout
chk_layout() {
  kit_section "2. Install layout (kit standard: unit $SDM_UNIT, user $SDM_USER, SDM_HOME=$SDM_HOME_DIR)"
  chk_user
  chk_unit
  chk_binary
  chk_procs
  chk_envfile
  chk_homes
  chk_secretsrc
  chk_stray
  chk_other_units
}

chk_user() {
  local pw home
  pw=$(getent passwd "$SDM_USER" 2>/dev/null || awk -F: -v u="$SDM_USER" '$1==u' /etc/passwd)
  if [ -z "$pw" ]; then
    if [ "$CHK_CONTAINER" = 1 ]; then info "no '$SDM_USER' user (normal in a container image)"
    else chk_fail "user '$SDM_USER' does not exist" "bash $KIT_DIR/$KIT_NAME.sh install      # creates it and installs the worker"; fi
    return
  fi
  home=$(printf '%s' "$pw" | cut -d: -f6)
  if [ "$home" = "$SDM_USER_HOME" ]; then ok "user '$SDM_USER' exists, home $home"
  else chk_fail "user '$SDM_USER' has home '$home', the kit standard is $SDM_USER_HOME" "usermod -d $SDM_USER_HOME -m $SDM_USER      # after stopping the worker: systemctl stop $SDM_UNIT"; fi
}

chk_unit() {
  local en act sub nr u wd es p since
  if [ "$CHK_SYSTEMD" = 0 ]; then info "no systemd: unit checks skipped"; return; fi
  if [ "$CHK_UNIT" = 0 ]; then
    chk_fail "systemd unit $SDM_UNIT is not installed" "bash $KIT_DIR/$KIT_NAME.sh install      # or choose 'New install' in the menu"; return; fi
  ok "unit $SDM_UNIT installed ($(kit_unit_prop "$SDM_UNIT" FragmentPath))"
  en=$(systemctl is-enabled "$SDM_UNIT" 2>/dev/null </dev/null)
  if [ "$en" = enabled ]; then ok "enabled (starts at boot)"
  else chk_fail "$SDM_UNIT is not enabled (state: ${en:-unknown}), so it will not start at boot" "systemctl enable $SDM_UNIT"; fi
  act=$(kit_unit_prop "$SDM_UNIT" ActiveState); sub=$(kit_unit_prop "$SDM_UNIT" SubState)
  since=$(kit_unit_prop "$SDM_UNIT" ActiveEnterTimestamp)
  if [ "$act" = active ]; then ok "active ($sub) since ${since:-?}"
  else chk_fail "$SDM_UNIT is $act ($sub)" "systemctl start $SDM_UNIT
journalctl -u $SDM_UNIT -n 50 --no-pager      # why it stopped"; fi
  nr=$(kit_unit_prop "$SDM_UNIT" NRestarts)
  if [[ $nr =~ ^[0-9]+$ ]] && [ "$nr" -gt 0 ]; then
    chk_warn "systemd has restarted $SDM_UNIT $nr time(s) since it was loaded (crash loop?)" "journalctl -u $SDM_UNIT -n 100 --no-pager"; fi
  u=$(kit_unit_prop "$SDM_UNIT" User)
  if [ "$u" = "$SDM_USER" ]; then ok "runs as User=$u"
  else chk_fail "unit runs as '${u:-root}', the kit standard is '$SDM_USER'" "bash $KIT_DIR/$KIT_NAME.sh install      # repairs the unit (asks before replacing)"; fi
  wd=$(kit_unit_prop "$SDM_UNIT" WorkingDirectory)
  if [ "$wd" = "$SDM_HOME_DIR" ]; then ok "WorkingDirectory=$wd"
  else chk_warn "WorkingDirectory is '${wd:-unset}', expected $SDM_HOME_DIR" "bash $KIT_DIR/$KIT_NAME.sh install      # repairs the unit"; fi
  es=$(kit_unit_prop "$SDM_UNIT" ExecStart); p=$(printf '%s' "$es" | sed -n 's/.*path=\([^ ;]*\).*/\1/p')
  if [ "$p" = "$SDM_BIN" ]; then ok "ExecStart uses $SDM_BIN"
  else chk_warn "ExecStart binary is '${p:-unknown}', expected $SDM_BIN" "bash $KIT_DIR/$KIT_NAME.sh install"; fi
  [ "$CHK_ENVFILE" = "$SDM_SYSCONFIG" ] || chk_warn "unit loads env file '$CHK_ENVFILE', expected $SDM_SYSCONFIG" ""
}

chk_binary() {
  if [ -x "$SDM_BIN" ]; then
    if CHK_VERSION=$(kit_as_worker "$SDM_HOME_DIR" timeout 15 "$SDM_BIN" --version </dev/null 2>/dev/null); then
      CHK_VERSION=$(printf '%s\n' "$CHK_VERSION" | awk '$1=="sdm" && $2=="version" && $3~/^[0-9][0-9A-Za-z._+-]*$/{print $3; exit}')
      ok "binary $SDM_BIN: ${CHK_VERSION:-version unknown}"
    else chk_warn "could not inspect the installed CLI with reduced privileges" "check the service account and CLI permissions"; fi
  elif [ -n "$CHK_PEXE" ]; then info "no $SDM_BIN; the running worker uses ${CHK_PEXE% (deleted)}"
  else chk_fail "binary $SDM_BIN not found" "bash $KIT_DIR/$KIT_NAME.sh install"; fi
  if [[ $CHK_PEXE == *" (deleted)" ]]; then
    chk_warn "the running worker's binary was replaced after it started (upgrade pending)" "systemctl restart $SDM_UNIT"
  elif [ -n "$CHK_PEXE" ] && [ "$CHK_PEXE" != "$SDM_BIN" ]; then info "running worker binary: $CHK_PEXE"; fi
}

chk_procs() {
  local pid user role exe cwd st nw=0 strays="" others=""
  if [ -z "$CHK_PROCS" ]; then
    if [ "$CHK_CONTAINER" = 1 ] && [ "$CHK_SYSTEMD" = 0 ]; then
      chk_fail "no sdm worker process is running in this container" "docker logs --tail 50 <container>      # why it exited (run this on the docker host)"
    else chk_fail "no sdm worker process is running" "systemctl start $SDM_UNIT
journalctl -u $SDM_UNIT -n 50 --no-pager"; fi
    return
  fi
  while IFS='|' read -r pid user role exe cwd st; do
    [ -n "$pid" ] || continue
    info "pid $pid: sdm $role, user $user, started $(chk_ts "$st"), cwd ${cwd:-?}"
    if [ "$role" = worker ]; then nw=$((nw+1)); [ "$pid" != "$CHK_PID" ] && strays+=" $pid"
    else others+=" $role(pid $pid)"; fi
  done <<<"$CHK_PROCS"
  [ -n "$CHK_PID" ] && ok "worker process pid $CHK_PID (user $CHK_PUSER)"
  if [ $nw -gt 1 ]; then
    chk_fail "$nw sdm worker processes are running; one per host is expected (they compete for the bind port and sealed secrets)" "systemctl show -p MainPID $SDM_UNIT      # the one to keep
kill$strays      # the stray one(s), after checking how they were started"
  fi
  [ -n "$others" ] && chk_warn "other StrongDM node processes on this host:$others" "only if this host should be a worker only: systemctl disable --now <their unit>"
  if [ -n "$CHK_PUSER" ] && [ "$CHK_PUSER" != "$SDM_USER" ] && [ "$CHK_CONTAINER" = 0 ]; then
    chk_warn "the worker runs as '$CHK_PUSER', the kit standard is '$SDM_USER'" "bash $KIT_DIR/$KIT_NAME.sh install      # repairs the unit"; fi
  if [ -n "$CHK_PID" ] && [ "$CHK_ENVREAD" = 0 ]; then
    if [ "$CHK_ROOT" = 1 ]; then
      chk_warn "cannot read the worker's /proc/$CHK_PID/environ even as root (container without CAP_SYS_PTRACE?); using $CHK_ENVFILE instead" \
          "docker exec -u $CHK_PUSER -it <container> bash      # run the check as the worker's user"
    else chk_warn "cannot read /proc/$CHK_PID/environ; using $CHK_ENVFILE instead" "sudo -i      # then re-run the check"; fi
  fi
}

chk_print_redacted() {
  local line k v
  while IFS= read -r line || [ -n "$line" ]; do
    case $line in ''|[[:space:]]*'#'*|'#'*) continue;; esac
    if [[ $line =~ ^[[:space:]]*(export[[:space:]]+)?([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]]; then
      k=${BASH_REMATCH[2]}; v=${BASH_REMATCH[3]}
      if chk_is_secret_key "$k"; then note "$k=<redacted, ${#v} bytes>"
      else note "$k=<set>"; fi
    else note "<line not in KEY=VALUE form, ${#line} bytes, not shown>"; fi
  done < "$1"
}

chk_envfile() {
  local f=$CHK_ENVFILE v lo plain="" k mode
  if [ ! -e "$f" ]; then
    if [ "$CHK_CONTAINER" = 1 ] && [ "$CHK_SYSTEMD" = 0 ]; then info "no $f (normal in a container: configuration comes from the process environment)"
    else chk_fail "env file $f is missing" "bash $KIT_DIR/$KIT_NAME.sh install      # rewrites it"; fi
  elif [ ! -r "$f" ]; then chk_warn "cannot read $f (need root)" "sudo -i      # then re-run the check"
  else
    mode=$(stat -c '%a' "$f" 2>/dev/null)
    info "$f (owner $(stat -c '%U:%G' "$f" 2>/dev/null), mode $mode, modified $(chk_ts "$(chk_mtime "$f")"); secret values redacted):"
    chk_print_redacted "$f"
    for k in SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY SDM_RELAY_TOKEN SDM_ADMIN_TOKEN DELINEA_PASSWORD; do
      kit_envfile_has "$f" "$k" && plain+=" $k"
    done
    if [ -n "$plain" ]; then
      chk_warn "plaintext credential(s) in $f:$plain" "runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set$plain      # seal them (hidden prompt)
sed -i -E '/^(export )?($(printf '%s' "${plain# }" | tr ' ' '|'))=/d' $f
systemctl restart $SDM_UNIT
# or: bash $KIT_DIR/$KIT_NAME.sh install   (seals and removes them)"
      note "sdm install writes the keys in plaintext only when the host cannot seal."
      [ "${mode: -2}" != 00 ] && \
        chk_warn "$f holds credentials and is readable by group/other (mode $mode)" "chmod 600 $f"
    fi
    if chk_changed_after_start "$f"; then
      chk_fail "$f was modified ($(chk_ts "$(chk_mtime "$f")")) AFTER the worker started ($(chk_ts "$CHK_PSTART")); the worker still runs with the old values" "systemctl restart $SDM_UNIT"
    fi
  fi
  lo=$(chk_cfg SDM_LOG_OUTPUT)
  case $lo in
    stdout|stderr) ok "SDM_LOG_OUTPUT=$lo: logs go to journald (journalctl -u $SDM_UNIT), not to a file under SDM_HOME";;
    *) if [ "$CHK_CONTAINER" = 1 ] && [ "$CHK_SYSTEMD" = 0 ]; then info "SDM_LOG_OUTPUT=${lo:-unset} (containers default to stdout when SDM_DOCKERIZED=true)"
       else chk_warn "SDM_LOG_OUTPUT is '${lo:-unset}': the worker writes a rotating log FILE under its SDM_HOME, so journalctl shows almost nothing" "echo 'SDM_LOG_OUTPUT=stdout' >> $f
systemctl restart $SDM_UNIT"; fi;;
  esac
  v=$(chk_cfg SDM_VERBOSE)
  if [ "$v" = true ]; then
    if kit_envfile_has "$f" SDM_VERBOSE; then
      chk_warn "SDM_VERBOSE=true is still on: debug-level logging is noisy and was meant to be temporary" "sed -i '/^SDM_VERBOSE=/d' $f
systemctl restart $SDM_UNIT      # drops this worker's active sessions"
    else
      chk_warn "SDM_VERBOSE=true is still on (set in the worker's environment, not in $f): debug-level logging is noisy" \
          "remove SDM_VERBOSE from the unit's Environment= lines or the container's env, then restart the worker"
    fi
  else ok "SDM_VERBOSE is ${v:-unset} (normal info-level logging)"; fi
}

chk_homes() {
  local ef wd pe
  ef=$(kit_envfile_get "$CHK_ENVFILE" SDM_HOME 2>/dev/null) && ef=$(chk_unquote "$ef")
  wd=""; [ "$CHK_UNIT" = 1 ] && wd=$(kit_unit_prop "$SDM_UNIT" WorkingDirectory)
  pe=$(chk_penv SDM_HOME)
  info "worker SDM_HOME: $CHK_HOME (from $CHK_HOME_SRC)"
  note "env file: ${ef:-unset}   unit WorkingDirectory: ${wd:-n/a}   process env: ${pe:-unset/unreadable}   process cwd: ${CHK_PCWD:-n/a}"
  if [ "$CHK_CONTAINER" = 1 ] && [ "$CHK_SYSTEMD" = 0 ]; then return; fi
  if [ "$CHK_HOME" = "$SDM_HOME_DIR" ] && { [ -z "$ef" ] || [ "$ef" = "$SDM_HOME_DIR" ]; } && { [ -z "$pe" ] || [ "$pe" = "$SDM_HOME_DIR" ]; }; then
    ok "SDM_HOME is consistently $SDM_HOME_DIR"
  else chk_warn "SDM_HOME is not consistently $SDM_HOME_DIR (the worker uses $CHK_HOME)" "bash $KIT_DIR/$KIT_NAME.sh install      # repairs the env file and unit"; fi
  if [ -d "$CHK_HOME" ]; then
    local o; o=$(stat -c %U "$CHK_HOME" 2>/dev/null)
    if [ -n "$CHK_PUSER" ] && [ "$CHK_PUSER" != root ] && [ "$o" != "$CHK_PUSER" ]; then
      chk_warn "$CHK_HOME is owned by '$o' but the worker runs as '$CHK_PUSER'" "inspect the directory ownership offline"; fi
  else chk_fail "SDM_HOME $CHK_HOME does not exist" "bash $KIT_DIR/$KIT_NAME.sh install"; fi
}

# chk_nodesecrets_list DIR -> sets CHK_NS_KEYS (space separated), CHK_NS_MSG; returns 0 listed, 1 no file, 2 error.
chk_nodesecrets_list() {
  local d=$1 bin=$SDM_BIN out
  CHK_NS_KEYS=""; CHK_NS_MSG=""
  [ -f "$d/secretenv.enc" ] || { CHK_NS_MSG="no sidecar"; return 1; }
  [ -x "$bin" ] || { CHK_NS_MSG="installed CLI unavailable"; return 2; }
  kit_as_worker "$d" test -r "$d/secretenv.enc" || { CHK_NS_MSG="unreadable as service user"; return 2; }
  out=$(kit_as_worker "$d" timeout 20 "$bin" nodesecrets list </dev/null 2>/dev/null) || { CHK_NS_MSG="unreadable as service user"; return 2; }
  CHK_NS_KEYS=$(printf '%s\n' "$out" | grep -E '^[A-Za-z_][A-Za-z0-9_]*$' | tr '\n' ' ')
  CHK_NS_KEYS=${CHK_NS_KEYS% }
  if [ -z "$CHK_NS_KEYS" ]; then
    if [[ $out == *"no sealed secrets file present"* ]]; then CHK_NS_MSG="no sealed secrets file present"; return 1; fi
    if [ -n "$out" ]; then CHK_NS_MSG="unrecognized CLI response"; return 2; fi
  fi
  return 0
}

chk_secretsrc() {
  local f k where sc o
  CHK_SECRETS_FILE=$(chk_cfg SDM_SECRETS_FILE)
  if [ -n "$CHK_SECRETS_FILE" ]; then
    f=$CHK_SECRETS_FILE
    info "SDM_SECRETS_FILE=$f: the worker reads secrets from this plaintext JSON file INSTEAD of the sealed sidecar"
    if [[ $f != /* ]]; then chk_fail "SDM_SECRETS_FILE must be an absolute path; the worker refuses to start" "use an absolute path, e.g. /run/secrets/sdm.json"
    elif [ ! -e "$f" ]; then chk_fail "$f does not exist; the worker fails closed at startup" "mount the secret file at $f (or unset SDM_SECRETS_FILE)"
    elif [ ! -f "$f" ]; then chk_fail "$f is not a regular file; the worker fails closed at startup" "mount a regular file at $f"
    elif [ ! -r "$f" ]; then chk_warn "cannot read $f (need root)" "sudo -i"
    else
      if kit_is_root && { [ -z "$CHK_PID" ] || [ "$(awk '/^Uid:/{print $2}' "/proc/$CHK_PID/status" 2>/dev/null)" != 0 ]; }; then
        CHK_MOUNT_FLAT=$(kit_as_worker "$CHK_HOME" cat -- "$f" 2>/dev/null | json_flat)
      else CHK_MOUNT_FLAT=$(json_flat < "$f"); fi
      CHK_MOUNT_KEYS=$(printf '%s\n' "$CHK_MOUNT_FLAT" | cut -f1 | grep -v '\.' | tr '\n' ' '); CHK_MOUNT_KEYS=${CHK_MOUNT_KEYS% }
      if [ -n "$CHK_MOUNT_KEYS" ]; then ok "$f keys: $CHK_MOUNT_KEYS"
      else chk_fail "$f has no top-level JSON keys (not a JSON object?)" "the file must be a JSON object: {\"DELINEA_USERNAME\":\"...\",\"DELINEA_PASSWORD\":\"...\"}"; fi
      chk_changed_after_start "$f" && chk_fail "$f changed AFTER the worker started; secrets are loaded once at startup" "systemctl restart $SDM_UNIT      # container: restart the container"
    fi
  else
    sc=$CHK_HOME/secretenv.enc
    if [ -f "$sc" ]; then
      o=$(stat -c %U "$sc" 2>/dev/null)
      ok "sealed sidecar $sc (owner $o, mode $(stat -c %a "$sc" 2>/dev/null), modified $(chk_ts "$(chk_mtime "$sc")"))"
      if [ -n "$CHK_PUSER" ] && [ "$CHK_PUSER" != root ] && [ "$o" != "$CHK_PUSER" ]; then
        chk_fail "$sc is owned by '$o' but the worker runs as '$CHK_PUSER', so it cannot read it" "Inspect the sidecar and its ownership offline before repairing the worker."; fi
      chk_changed_after_start "$sc" && chk_fail "sealed sidecar changed AFTER the worker started; it is loaded once at startup, so the worker still uses the old values" "systemctl restart $SDM_UNIT"
      chk_nodesecrets_list "$CHK_HOME"
      case $? in
        0) CHK_SEALED_OK=1; CHK_SEALED_KEYS=$CHK_NS_KEYS; info "sealed key names: ${CHK_SEALED_KEYS:-none}";;
        1) CHK_SEALED_OK=1; info "sealed key names: none";;
        *) chk_warn "could not list the sealed keys: $CHK_NS_MSG" "runuser -u sdm -- env SDM_HOME=$CHK_HOME SDM_LOG_OUTPUT=stderr $SDM_BIN nodesecrets list";;
      esac
    else
      CHK_SEALED_OK=1
      info "no sealed sidecar at $sc (then every credential must come from the environment)"
    fi
  fi
  for k in DELINEA_SERVER_URL DELINEA_API_TENANT; do
    if chk_in_list "$k" "$CHK_SEALED_KEYS $CHK_MOUNT_KEYS"; then
      chk_fail "$k is in the secret store, but the worker reads it ONLY from its environment, so that value is ignored" "runuser -u sdm -- env SDM_HOME=$CHK_HOME $SDM_BIN nodesecrets unset $k
echo '$k=<value>' >> $CHK_ENVFILE
systemctl restart $SDM_UNIT"; fi
  done
  for k in SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY; do
    where=""
    chk_in_list "$k" "$CHK_SEALED_KEYS" && where="sealed sidecar"
    chk_in_list "$k" "$CHK_MOUNT_KEYS" && where="SDM_SECRETS_FILE"
    [ -z "$where" ] && chk_penv "$k" >/dev/null && where="process environment"
    [ -z "$where" ] && kit_envfile_has "$CHK_ENVFILE" "$k" && where="$CHK_ENVFILE"
    if [ -n "$where" ]; then ok "$k provided by the $where"
    elif [ "$CHK_SEALED_OK" = 1 ] && [ "$CHK_ROOT" = 1 ]; then
      chk_fail "$k is not provided anywhere the worker reads it" "bash $KIT_DIR/$KIT_NAME.sh install      # asks for the keys and seals them"
    else info "$k: could not verify (sealed keys not listable or not root)"; fi
  done
}

chk_stray() {
  local d hp missing k any=0 msg fixc
  hp=$(chk_realpath "$CHK_HOME")
  for d in /root/.sdm /home/*/.sdm /sdm; do
    [ -d "$d" ] || continue
    [ "$(chk_realpath "$d")" = "$hp" ] && continue
    any=1
    if [ -f "$d/secretenv.enc" ]; then
      chk_nodesecrets_list "$d"
      missing=""
      for k in $CHK_NS_KEYS; do chk_in_list "$k" "$CHK_SEALED_KEYS $CHK_MOUNT_KEYS" || missing+=" $k"; done
      CHK_STRAY_KEYS+=" $CHK_NS_KEYS"
      msg="sealed secrets in $d/secretenv.enc (keys: ${CHK_NS_KEYS:-${CHK_NS_MSG:-unknown}}) are NOT read by the worker, which reads $CHK_HOME"
      fixc="runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set ${missing# }      # re-enter the values into the worker's sidecar
systemctl restart $SDM_UNIT
mv $d $d.unused-$(date +%Y%m%d)      # after the worker works"
      [ -n "$missing" ] || fixc="mv $d $d.unused-$(date +%Y%m%d)      # leftover; the worker already has these keys"
      if [ -n "$missing" ]; then chk_fail "$msg; missing from the worker:$missing" "$fixc"
      else chk_warn "$msg" "$fixc"; fi
      note "Cause: after 'sudo su -' (or sudo -i) USER is root, and an interactive 'sdm nodesecrets set'"
      note "without SDM_HOME writes ~root/.sdm. Always pass SDM_HOME=$SDM_HOME_DIR."
    else
      info "leftover directory $d (no sealed secrets; contents: $(ls -A "$d" 2>/dev/null | head -8 | tr '\n' ' ')) - not used by the worker"
    fi
  done
  [ $any = 0 ] && ok "no stray .sdm directories in /root or /home/*"
}

chk_other_units() {
  local u st
  [ "$CHK_SYSTEMD" = 1 ] || return 0
  for u in sdm "${KIT_FOREIGN_UNITS[@]}"; do
    [ "$u" = "$SDM_UNIT" ] && continue
    kit_unit_exists "$u" || continue
    st=$(kit_unit_prop "$u" ActiveState)
    chk_warn "another StrongDM unit '$u' is installed ($st)" "systemctl disable --now $u      # only if this host should be a worker only"
  done
}

# ---------------------------------------------------------------- 3 connectivity
chk_connect() {
  local d=$CHK_APP_DOMAIN ips a lv b port
  kit_section "3. Connectivity"
  info "control plane: $d (from $CHK_APP_SRC)"
  chk_in_list "$d" "${KIT_APP_DOMAINS[*]}" || info "not one of the standard regions (${KIT_APP_DOMAINS[*]}); fine for a private/vanity domain"
  if [ -n "$CHK_WPROXY" ]; then info "the worker uses an HTTPS proxy for its connectivity checks"
  elif [ -n "$CHK_SHELL_PROXY" ]; then
    info "your shell has a proxy set but the worker does not; the checks below go direct, as the worker does"
  fi
  if kit_have getent; then
    ips=$(getent hosts "$d" 2>/dev/null | awk '{print $1}' | sort -u | tr '\n' ' ')
    if [ -n "$ips" ]; then ok "DNS $d -> $ips"
    elif [ -n "$CHK_WPROXY" ]; then info "DNS for $d fails locally (fine when the proxy resolves it)"
    else chk_fail "DNS lookup for $d failed" "getent hosts $d; cat /etc/resolv.conf      # fix the resolver or egress DNS"; fi
  fi
  if [ -z "$CHK_WPROXY" ]; then
    if kit_tcp_ok "$d" 443; then ok "TCP $d:443 reachable"
    else chk_fail "TCP $d:443 is not reachable from this host" "allow outbound tcp/443 to $d (security group / firewall / proxy)"; fi
  fi
  if kit_have curl; then
    case $(uname -m) in aarch64|arm64) a=arm64;; *) a=amd64;; esac
    kit_http GET "https://$d/releases/upgrade?software=sdm-cli&os=linux&arch=$a"
    case $HE in
      0) if [ "${HC:0:1}" = 2 ]; then
           lv=$(jget "$(printf '%s' "$HB" | json_flat)" version)
           ok "HTTPS to $d works (HTTP $HC)"
           [ -n "$lv" ] && info "latest sdm for linux/$a: $lv; installed: ${CHK_VERSION:-unknown}"
         else chk_warn "HTTPS to $d answered HTTP $HC" "curl -sv https://$d/ -o /dev/null      # look for a proxy or captive portal"; fi;;
      77) chk_fail "curl cannot load the system CA bundle (curl exit 77)" "dnf install -y ca-certificates      # or: apt-get install -y ca-certificates";;
      35|51|53|58|60|83|90|91)
         chk_fail "TLS to $d failed (curl exit $HE): " "a TLS-inspecting proxy needs its CA in the system trust store:
cp proxy-ca.pem /etc/pki/ca-trust/source/anchors/ && update-ca-trust      # RHEL family
cp proxy-ca.crt /usr/local/share/ca-certificates/ && update-ca-certificates      # Debian family";;
      5|6|7|28|56|97) chk_fail "HTTPS to $d failed (curl exit $HE): " "curl -sv https://$d/ -o /dev/null      # see where it stops";;
      *) chk_warn "HTTPS to $d: curl exit $HE: " "curl -sv https://$d/ -o /dev/null";;
    esac
  else info "curl is not installed: HTTPS check skipped (dnf/apt-get install -y curl)"; fi
  b=$(chk_cfg SDM_BIND_ADDRESS); [ -n "$b" ] || b=$SDM_DEFAULT_BIND
  port=${b##*:}
  if [[ ! $port =~ ^[0-9]+$ ]]; then chk_warn "cannot parse SDM_BIND_ADDRESS '$b'" ""; return; fi
  if [ -z "$CHK_PID" ]; then info "worker not running: bind port $port not checked"
  elif chk_listening "$port"; then ok "something listens on tcp/$port (worker bind address $b)"
  else chk_fail "nothing listens on tcp/$port although the worker is running (bind address $b)" "journalctl -u $SDM_UNIT -n 100 --no-pager | grep -iE 'bind|listen|address'"; fi
  chk_firewall "$port"
}

chk_listening() { local p=$1 hx
  if kit_have ss; then ss -ltn 2>/dev/null | awk -v p=":$p" 'NR>1 && substr($4, length($4)-length(p)+1)==p {f=1} END{exit !f}'; return; fi
  printf -v hx '%04X' "$p"
  cat /proc/net/tcp /proc/net/tcp6 2>/dev/null | awk -v p="$hx" '$4=="0A" { split($2,a,":"); if (a[2]==p) f=1 } END{exit !f}'
}

chk_firewall() { local p=$1 lst
  if kit_have firewall-cmd && [ "$(firewall-cmd --state 2>/dev/null </dev/null)" = running ]; then
    lst=" $(firewall-cmd --list-ports 2>/dev/null </dev/null) "
    if [[ $lst == *" $p/tcp "* ]]; then ok "firewalld allows $p/tcp"
    else chk_warn "firewalld is running and does not list $p/tcp (fine if a zone/service rule covers it)" "firewall-cmd --permanent --add-port=$p/tcp && firewall-cmd --reload"; fi
  elif kit_have ufw && ufw status 2>/dev/null </dev/null | grep -q 'Status: active'; then
    if ufw status 2>/dev/null </dev/null | grep -qE "^$p(/tcp)?[[:space:]].*ALLOW"; then ok "ufw allows $p"
    else chk_warn "ufw is active and has no ALLOW rule for $p" "ufw allow $p/tcp"; fi
  else info "no active firewalld/ufw on this host (cloud security groups still apply: allow inbound tcp/$p from the load balancer/gateways)"; fi
}

# ---------------------------------------------------------------- 4 logs
chk_logs() {
  local s all lh errs wrns nerr nwrn nstart started_ago
  kit_section "4. Recent logs"
  if [ "$CHK_SYSTEMD" = 0 ] || ! kit_have journalctl; then
    info "no journald here. In a container the worker logs to stdout; on the docker host run:"
    note "docker logs --since 1h <container> 2>&1 | grep -E 'running proxy worker|initial authsync complete|level=error'"
    return
  fi
  [ "$CHK_UNIT" = 1 ] || { info "unit $SDM_UNIT not installed: no logs to read"; return; }
  [ "$CHK_ROOT" = 1 ] || info "not root: the journal may hide the worker's lines"
  if [ -n "$CHK_PSTART" ]; then
    s=$(chk_ts "$CHK_PSTART"); started_ago=$(( $(date +%s) - CHK_PSTART ))
    info "worker started $s ($((started_ago/60)) min ago)"
    all=$(journalctl -u "$SDM_UNIT" --since "$s" --no-pager -o cat 2>/dev/null </dev/null | head -20000)
    if printf '%s\n' "$all" | grep -q 'running proxy worker'; then ok "'running proxy worker' logged since the last start"
    elif [ $started_ago -gt 120 ]; then chk_fail "no 'running proxy worker' line since the last start: the worker did not get past startup" "journalctl -u $SDM_UNIT --since '$s' --no-pager | head -60"
    else info "'running proxy worker' not logged yet (started under 2 min ago)"; fi
    if printf '%s\n' "$all" | grep -q 'initial authsync complete'; then ok "'initial authsync complete' logged (talking to the control plane)"
    elif [ $started_ago -gt 120 ]; then chk_warn "no 'initial authsync complete' since the last start: it has not synced with the control plane" \
        "journalctl -u $SDM_UNIT --since '$s' --no-pager | grep -iE 'error|auth|token|connect' | tail -20"
    else info "'initial authsync complete' not logged yet"; fi
  else info "worker not running: startup lines not checked"; fi
  lh=$(journalctl -u "$SDM_UNIT" --since "-1h" --no-pager -o short-iso 2>/dev/null </dev/null | tail -20000)
  errs=$(printf '%s\n' "$lh" | grep -iE 'level=(error|fatal|panic|dpanic)|"level":"(error|fatal|panic|dpanic)"|Main process exited|Failed with result')
  wrns=$(printf '%s\n' "$lh" | grep -iE 'level=warn|"level":"warn')
  nerr=$(printf '%s' "$errs" | grep -c .); nwrn=$(printf '%s' "$wrns" | grep -c .)
  nstart=$(printf '%s\n' "$lh" | grep -cE 'Started StrongDM worker|Started sdm-worker')
  info "last hour: $(printf '%s' "$lh" | grep -c .) line(s), $nerr error(s), $nwrn warning(s), $nstart start(s)"
  [ "$nstart" -gt 2 ] && chk_warn "$SDM_UNIT started $nstart times in the last hour (restart loop)" "journalctl -u $SDM_UNIT --since -1h --no-pager | grep -iE 'error|exited' | tail -20"
  if [ "$nerr" -gt 0 ]; then
    chk_warn "$nerr error line(s) in the last hour" "journalctl -u $SDM_UNIT --since -1h --no-pager | grep -iE 'level=error|\"level\":\"error\"'"
  fi
}

# ---------------------------------------------------------------- 5 delinea
chk_delinea_wanted() {
  local found=""
  case ${KIT_CHECK_DELINEA:-} in
    yes|y|1|true) info "KIT_CHECK_DELINEA=yes"; return 0;;
    no|n|0|false) info "skipped (KIT_CHECK_DELINEA=no)"; return 1;;
  esac
  [ "$CHK_ENVREAD" = 1 ] && tr '\0' '\n' < "/proc/$CHK_PID/environ" 2>/dev/null | grep -q '^DELINEA_' && found+=" worker-env"
  [ -r "$CHK_ENVFILE" ] && grep -qE '^[[:space:]]*(export[[:space:]]+)?DELINEA_' "$CHK_ENVFILE" && found+=" env-file"
  [[ " $CHK_SEALED_KEYS $CHK_MOUNT_KEYS " == *" DELINEA_"* ]] && found+=" secret-store"
  [[ " $CHK_STRAY_KEYS " == *" DELINEA_"* ]] && found+=" stray-sidecar"
  if [ -n "$found" ]; then info "DELINEA_* settings found in:$found"; return 0; fi
  if kit_noninteractive; then info "no DELINEA_* settings found; skipped (export KIT_CHECK_DELINEA=yes to force)"; return 1; fi
  kit_confirm "No DELINEA_* settings found. Test a Delinea secret store anyway?" n || { info "skipped"; return 1; }
}

# chk_ask VAR "prompt": env value, else (interactive) a visible prompt where Enter = empty.
chk_ask() {
  if [ -n "${!1:-}" ]; then info "$2: using \$$1 from the environment"; return 0; fi
  kit_noninteractive && { printf -v "$1" '%s' ""; return 0; }
  kit_ask "$1" "$2 (Enter to skip)" ""
}

# secretkit.ParsePath + delinea.parsePath -> CHK_PK CHK_PR CHK_PID_ CHK_PENC CHK_PSTATIC, or return 1 with CHK_PERR
chk_parse_path() {
  local raw=$1 q path kv parts=() norm dg
  CHK_PK=""; CHK_PENC=""; CHK_PSTATIC=""; CHK_SID=""; CHK_PERR=""; CHK_PR=""
  path=${raw%%\?*}; if [ "$path" = "$raw" ]; then q=""; else q=${raw#*\?}; fi
  [ -n "$q" ] && IFS='&' read -ra parts <<<"$q"
  for kv in ${parts[@]+"${parts[@]}"}; do
    case $kv in key=*) [ -z "$CHK_PK" ] && CHK_PK=${kv#key=};; encoding=*) [ -z "$CHK_PENC" ] && CHK_PENC=${kv#encoding=};; static=*) [ -z "$CHK_PSTATIC" ] && CHK_PSTATIC=${kv#static=};; esac
  done
  CHK_PK=${CHK_PK//+/ }; printf -v CHK_PK '%b' "${CHK_PK//%/\\x}"; printf -v path '%b' "${path//%/\\x}"
  CHK_PR=$path
  case $CHK_PENC in ''|base64) ;; *) CHK_PERR="invalid secret encoding '$CHK_PENC' (only base64 or none)"; return 1;; esac
  [ "$CHK_PSTATIC" = true ] && return 0
  [ -n "$CHK_PK" ] || { CHK_PERR="delinea secrets require a key to query (add ?key=<FieldName>)"; return 1; }
  norm=${path#"${path%%[!/]*}"}
  [ -n "$norm" ] || { CHK_PERR="path must be a secret ID or a folder path like /Folder/Secret"; return 1; }
  if [[ $norm =~ ^[+-]?[0-9]+$ ]]; then dg=${norm#[+-]}; CHK_SID=$((10#$dg)); [[ $norm == -* ]] && CHK_SID=-$CHK_SID; return 0; fi
  [[ $path == */* ]] || { CHK_PERR="path must be a secret ID or a folder path like /Folder/Secret"; return 1; }
  return 0
}

chk_delinea() {
  kit_section "5. Delinea secret store"
  chk_delinea_wanted || return 0
  kit_secret_register CHK_SPW CHK_TOKEN CHK_VAL_PASS CHK_WANT KIT_DELINEA_SVC_PASSWORD
  CHK_SU=""; CHK_SPW=""; CHK_TOKEN=""; CHK_VAL_PASS=""; CHK_WANT=""; CHK_API=""; CHK_URL=""
  chk_dl_creds
  chk_dl_url
  chk_dl_paths
  if [ "${KIT_DELINEA_LIVE:-no}" = yes ] && [ -n "$CHK_URL" ]; then
    unset HTTP_PROXY http_proxy HTTPS_PROXY https_proxy ALL_PROXY all_proxy NO_PROXY no_proxy CURL_CA_BUNDLE SSL_CERT_FILE SSL_CERT_DIR
    if [ -n "${KIT_DELINEA_CA_FILE:-}" ]; then
      local ca=$KIT_DELINEA_CA_FILE
      if ! kit_trusted_file "$ca"; then
        chk_fail "Untrusted Delinea CA bundle" "use a root-owned regular file under a protected directory"; return
      fi
      export CURL_CA_BUNDLE=$ca
    fi
    CHK_WPROXY=""; chk_dl_live
  else info "live authentication skipped; set KIT_DELINEA_LIVE=yes and a trusted KIT_DELINEA_SERVER_URL to enable"; fi
  if [ -n "${KIT_RDP_HOST:-}" ]; then
    local rh rp
    rh=${KIT_RDP_HOST%%:*}; rp=${KIT_RDP_HOST##*:}; [ "$rp" = "$KIT_RDP_HOST" ] && rp=3389
    if kit_tcp_ok "$rh" "$rp"; then ok "RDP target $rh:$rp is reachable (TCP) from this worker"
    else chk_fail "RDP target $rh:$rp is NOT reachable (TCP) from this worker" "allow tcp/$rp from this worker to $rh (Windows firewall / security group)"; fi
  fi
  info "the worker caches fetched credentials for up to 12h per user login; saving the resource, or sdm logout + sdm login, clears it"
  CHK_SPW=""; CHK_TOKEN=""; CHK_VAL_PASS=""; CHK_WANT=""
}

# Effective DELINEA_USERNAME / DELINEA_PASSWORD and where they come from.
chk_dl_creds() {
  local k v src envv envhas a
  for k in DELINEA_USERNAME DELINEA_PASSWORD; do
    v=""; src=""; envhas=0
    envv=$(chk_penv "$k") && envhas=1
    if chk_in_list "$k" "$CHK_MOUNT_KEYS"; then v=$(jget "$CHK_MOUNT_FLAT" "$k"); src="SDM_SECRETS_FILE"
    elif chk_in_list "$k" "$CHK_SEALED_KEYS"; then src="sealed sidecar"
    elif [ $envhas = 1 ] && [ -n "$envv" ]; then v=$envv; src="worker environment"
    elif [ "$CHK_ENVREAD" = 0 ] && v=$(kit_envfile_get "$CHK_ENVFILE" "$k"); then v=$(chk_unquote "$v"); src="$CHK_ENVFILE (worker env unreadable)"; fi
    if [ -z "$src" ]; then
      if chk_in_list "$k" "$CHK_STRAY_KEYS"; then chk_fail "$k is only in a stray sidecar the worker does not read (see section 2)" "runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set $k
systemctl restart $SDM_UNIT"
      elif kit_envfile_has "$CHK_ENVFILE" "$k"; then chk_fail "$k is in $CHK_ENVFILE but NOT in the running worker" "systemctl restart $SDM_UNIT"
      else chk_fail "$k is not set anywhere the worker reads it" "runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set $k      # hidden prompt
systemctl restart $SDM_UNIT"; fi
      continue
    fi
    if [ "$src" = "sealed sidecar" ]; then ok "$k comes from the sealed sidecar (value unreadable by design)"
    elif [ $k = DELINEA_USERNAME ]; then ok "$k comes from the $src (value hidden)"
    else ok "$k comes from the $src: $(kit_shape "$v")"; fi
    if [ -n "$v" ]; then a=$(kit_anomalies "$v"); [ -n "$a" ] && chk_warn "$k value anomalies: $a" "re-enter it: runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set $k"; fi
    [ "$src" != "worker environment" ] && [ $envhas = 1 ] && [ -n "$envv" ] && chk_warn "$k is ALSO in the worker's environment, but the $src value wins; editing the environment value does nothing" \
        "sed -i '/^$k=/d' $CHK_ENVFILE      # remove the dead copy"
    if [ $k = DELINEA_USERNAME ]; then CHK_SU=$v; else CHK_SPW=$v; fi
  done
  envv=""
}

chk_dl_url() {
  local eurl eten
  eurl=$(chk_penv DELINEA_SERVER_URL || { [ "$CHK_ENVREAD" = 0 ] && kit_envfile_get "$CHK_ENVFILE" DELINEA_SERVER_URL; })
  eten=$(chk_penv DELINEA_API_TENANT || { [ "$CHK_ENVREAD" = 0 ] && kit_envfile_get "$CHK_ENVFILE" DELINEA_API_TENANT; })
  eurl=$(chk_unquote "$eurl"); eten=$(chk_unquote "$eten")
  CHK_URL=""
  if [ -n "$eurl" ] && ! kit_https_url "$eurl"; then chk_warn "worker Secret Server URL requires a valid HTTPS address" "check the URL in the Admin UI"; fi
  if [ -n "$eten" ] && [ -n "${KIT_DELINEA_SERVER_URL:-$eurl}" ]; then
    chk_fail "only one of serverURL and tenant may be set" "correct the worker configuration before testing"; return
  fi
  [ "${KIT_DELINEA_LIVE:-no}" = yes ] || return 0
  chk_ask KIT_DELINEA_SERVER_URL "Trusted HTTPS Server URL set on the secret store in the Admin UI"
  if ! kit_https_url "${KIT_DELINEA_SERVER_URL:-}"; then
    chk_fail "live authentication requires a trusted HTTPS Secret Server URL" "supply KIT_DELINEA_SERVER_URL from your Admin UI"; return
  fi
  CHK_URL=${KIT_DELINEA_SERVER_URL%/}
}

chk_dl_paths() {
  local label raw var
  CHK_L_LABEL=(); CHK_L_KEY=(); CHK_L_PATH=(); CHK_L_ID=(); CHK_L_ENC=(); CHK_L_STATIC=()
  chk_ask KIT_DELINEA_USERNAME_PATH "Username secret path exactly as on the resource (e.g. 1234?key=Username)"
  if [ -z "${KIT_DELINEA_PASSWORD_PATH:-}" ] && ! kit_noninteractive; then
    printf '  Password secret path (hidden, Enter to skip): ' >/dev/tty
    IFS= read -rs KIT_DELINEA_PASSWORD_PATH </dev/tty || KIT_DELINEA_PASSWORD_PATH=""; printf '\n' >/dev/tty
  fi
  chk_ask KIT_RDP_HOST "RDP target host[:port] to test from this worker"
  for label in username password; do
    var=KIT_DELINEA_USERNAME_PATH; [ $label = password ] && var=KIT_DELINEA_PASSWORD_PATH
    raw=${!var:-}
    [ -n "$raw" ] || { info "$label path not given; skipped"; continue; }
    if chk_parse_path "$raw"; then
      CHK_L_LABEL+=("$label"); CHK_L_KEY+=("$CHK_PK"); CHK_L_PATH+=("$CHK_PR"); CHK_L_ID+=("$CHK_SID"); CHK_L_ENC+=("$CHK_PENC"); CHK_L_STATIC+=("$CHK_PSTATIC")
      if [ "$CHK_PSTATIC" = true ]; then ok "$label is static (value hidden)"
      elif [ -n "$CHK_SID" ]; then ok "$label: secret ID $CHK_SID, key '$CHK_PK', encoding ${CHK_PENC:-plaintext}"
      else ok "$label: folder path '$CHK_PR', key '$CHK_PK'"
        chk_warn "$label uses a folder path; it resolves to whichever secret DELINEA_USERNAME sees there" "use the numeric secret ID on the resource, e.g. 1234?key=$CHK_PK"; fi
      [ "$CHK_PK" != "$(kit_trim "$CHK_PK")" ] && chk_fail "$label key '$CHK_PK' has leading/trailing spaces, so it never matches a field" "remove the spaces from the key on the resource"
    else chk_fail "$label path is invalid: $CHK_PERR" "fix the secret path on the resource: <ID or /Folder/Secret>?key=<FieldName>"; fi
  done
  if [ ${#CHK_L_LABEL[@]} = 2 ] && [ -z "${CHK_L_STATIC[0]}" ] && [ -z "${CHK_L_STATIC[1]}" ] && [ "${CHK_L_KEY[0]}" = "${CHK_L_KEY[1]}" ]; then
    chk_fail "the username and password paths use the SAME key '${CHK_L_KEY[0]}'" "set the username path to ?key=Username and the password path to ?key=Password (the fields' display names)"; fi
}

chk_dl_get_creds() {
  if [ -n "$CHK_SU" ] && [ -n "$CHK_SPW" ]; then return 0; fi
  if kit_noninteractive && { { [ -z "$CHK_SU" ] && [ -z "${KIT_DELINEA_SVC_USERNAME:-}" ]; } || { [ -z "$CHK_SPW" ] && [ -z "${KIT_DELINEA_SVC_PASSWORD:-}" ]; }; }; then
    chk_warn "the service-account credentials are sealed and no terminal is available to type them; live Secret Server checks skipped" \
        "export KIT_DELINEA_SVC_USERNAME=... KIT_DELINEA_SVC_PASSWORD=...   # then re-run (or run interactively)"
    return 1
  fi
  if [ -z "$CHK_SU" ]; then
    kit_noninteractive || note "DELINEA_USERNAME is sealed: type the SAME service-account username you sealed."
    kit_ask KIT_DELINEA_SVC_USERNAME "DELINEA_USERNAME (service account)"
    CHK_SU=$KIT_DELINEA_SVC_USERNAME
  fi
  if [ -z "$CHK_SPW" ]; then
    kit_noninteractive || note "DELINEA_PASSWORD is sealed: type the SAME password you sealed (hidden, nothing is logged)."
    kit_ask_secret KIT_DELINEA_SVC_PASSWORD "DELINEA_PASSWORD (service account)"
    CHK_SPW=$KIT_DELINEA_SVC_PASSWORD
  fi
  info "using typed/env service-account credentials; the kit cannot prove they equal the sealed ones"
}

chk_dl_live() {
  local host port ips healthy_re='"[Hh]ealthy"[[:space:]]*:[[:space:]]*true' t vf
  host=${CHK_URL#*://}; host=${host%%/*}; port=${host##*:}; [ "$port" = "$host" ] && { port=443; [[ $CHK_URL == http://* ]] && port=80; }; host=${host%:*}
  if kit_have getent; then
    ips=$(getent hosts "$host" 2>/dev/null | awk '{print $1}' | sort -u | tr '\n' ' ')
    if [ -n "$ips" ]; then ok "DNS $host -> $ips"
    elif [ -z "$CHK_WPROXY" ]; then chk_fail "DNS lookup for $host failed" "getent hosts $host; cat /etc/resolv.conf"; fi
  fi
  if [ -z "$CHK_WPROXY" ]; then
    if kit_tcp_ok "$host" "$port"; then ok "TCP $host:$port reachable"
    else chk_fail "TCP $host:$port is not reachable from this worker" "allow outbound tcp/$port from this worker to $host"; return; fi
  fi
  if ! kit_have curl; then chk_warn "curl is not installed, so the live Secret Server checks are skipped" "dnf install -y curl      # or: apt-get install -y curl"; return; fi
  chk_dl_get_creds || return
  CHK_API=$CHK_URL
  kit_http GET "$CHK_URL/api/v1/healthcheck"
  case $HE in 35|51|53|58|60|77|83|90|91)
    chk_fail "TLS to $CHK_URL failed (curl exit $HE): " "configure the approved CA in the host system trust store"
    return;; esac
  if [[ $HE = 0 && $HC = 200 ]] && [[ $HB =~ $healthy_re || ( $HB != *'{'* && $HB == *Healthy* ) ]]; then
    ok "Secret Server healthcheck $CHK_URL/api/v1/healthcheck: healthy"
    kit_http POST "$CHK_URL/oauth2/token" "username=$(kit_urlencode "$CHK_SU")&password=$(kit_urlencode "$CHK_SPW")&grant_type=password"
    if [ "$HE" = 0 ] && [ "${HC:0:1}" = 2 ] && CHK_TOKEN=$(jget "$(printf '%s' "$HB" | json_flat)" access_token) && [ -n "$CHK_TOKEN" ]; then ok "OAuth2 password grant succeeded"
    else chk_fail "POST /oauth2/token: HTTP $HC " "check the service account in Secret Server (locked? expired? wrong password?), then re-seal:
runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets set DELINEA_USERNAME DELINEA_PASSWORD && systemctl restart $SDM_UNIT"
      note "StrongDM never sends the token 'domain' parameter, so an AD account must be able to log in without it (local account, or AD user with domain login not required)"; fi
  else
    info "/api/v1/healthcheck not healthy (HTTP $HC); trying Delinea Platform /health"
    kit_http GET "$CHK_URL/health"
    if [[ $HE = 0 && $HC = 200 ]] && [[ $HB =~ $healthy_re || ( $HB != *'{'* && $HB == *Healthy* ) ]]; then
      ok "Delinea Platform /health: healthy"
      kit_http POST "$CHK_URL/identity/api/oauth2/token/xpmplatform" "grant_type=client_credentials&client_id=$(kit_urlencode "$CHK_SU")&client_secret=$(kit_urlencode "$CHK_SPW")&scope=xpmheadless"
      if [ "$HE" = 0 ] && [ "${HC:0:1}" = 2 ] && t=$(jget "$(printf '%s' "$HB" | json_flat)" access_token) && [ -n "$t" ]; then
        ok "Platform service-account token obtained"
        kit_http GET "$CHK_URL/vaultbroker/api/vaults" "" "$t"
        if [ "$HE" != 0 ] || [ "$HC" != 200 ]; then chk_fail "Platform vault lookup failed (HTTP $HC)" "check the Platform service account permissions"; return; fi
        vf=$(printf '%s' "$HB" | json_flat)
        CHK_API=$(printf '%s\n' "$vf" | awk -F'\t' '{p=$1; sub(/\.[^.]*(\.url)?$/,"",p)}
          tolower($1)~/\.isdefault$/{d[p]=$3} tolower($1)~/\.isactive$/{a[p]=$3}
          tolower($1)~/\.connection\.url$/{u[p]=$3}
          END{for(p in u) if(d[p]=="true"&&a[p]=="true"){print u[p]; exit}}')
        if kit_https_url "${KIT_DELINEA_VAULT_URL:-}" && [ "${CHK_API%/}" = "${KIT_DELINEA_VAULT_URL%/}" ]; then
          CHK_API=${KIT_DELINEA_VAULT_URL%/}; CHK_TOKEN=$t; ok "verified default vault"
        else chk_fail "default vault did not match KIT_DELINEA_VAULT_URL" "verify the default vault in Delinea and supply its HTTPS URL"; fi
        t=""
      else chk_fail "Platform token: HTTP $HC " "check the Platform service account (client id/secret) and re-seal DELINEA_USERNAME/DELINEA_PASSWORD"; fi
    else chk_fail "neither /api/v1/healthcheck nor /health is healthy at $CHK_URL (the worker reports tss-sdk 'invalid URL')" "check the URL includes the application path, e.g. https://<host>/SecretServer"; fi
  fi
  CHK_SPW=""; KIT_DELINEA_SVC_PASSWORD=""
  if [ -n "$CHK_TOKEN" ]; then chk_dl_fetch; fi
  CHK_TOKEN=""; HB=""
  chk_dl_compare
}

chk_dl_table() {
  local idx fn ip
  note "field names and password flags"
  printf '%s\n' "$CHK_SF" | awk -F'\t' 'tolower($1)~/^items\.[0-9]+\./{split($1,a,"."); print a[2]}' | sort -un | while read -r idx; do
    fn=$(jget "$CHK_SF" "items.$idx.fieldName"); ip=$(jget "$CHK_SF" "items.$idx.isPassword")
    note "field: $fn (isPassword=$ip)"
  done
}

chk_dl_fetch() {
  local j n label key ref lastref="" idxs idx v a near fl
  n=${#CHK_L_LABEL[@]}; CHK_SF=""
  [ "$n" -gt 0 ] || { info "no resource secret paths given: secret fetch skipped"; return; }
  for ((j=0; j<n; j++)); do
    label=${CHK_L_LABEL[j]}; key=${CHK_L_KEY[j]}
    if [ "${CHK_L_STATIC[j]}" = true ]; then continue; fi
    if [ -n "${CHK_L_ID[j]}" ]; then ref="secrets/${CHK_L_ID[j]}"; else ref="secrets/0?secretPath=$(kit_urlencode "${CHK_L_PATH[j]}")"; fi
    if [ "$ref" != "$lastref" ]; then
      lastref=$ref; CHK_SF=""
      kit_http GET "$CHK_API/api/v1/$ref" "" "$CHK_TOKEN"
      if [ "$HE" != 0 ] || [ "${HC:0:1}" != 2 ]; then
        chk_fail "GET /api/v1/${ref%%\?*} ($label): HTTP $HC " "in Secret Server give the service account View on the secret; turn off checkout/require-comment/approval for it (the API cannot satisfy them)"
        [[ $HB == *API_AccessDenied* || $HC = 403 ]] && note "the service account lacks View on this secret, or the secret requires checkout, a comment, or approval"
        continue
      fi
      CHK_SF=$(printf '%s' "$HB" | json_flat); HB=""
      ok "GET /api/v1/${ref%%\?*}: 200, secret id $(jget "$CHK_SF" id), name '$(jget "$CHK_SF" name)', template $(jget "$CHK_SF" secretTemplateId)"
      for fl in checkOutEnabled checkedOut requiresComment autoChangeEnabled checkOutChangePasswordEnabled; do
        if [ "$(jget "$CHK_SF" "$fl")" = true ]; then
          if [[ $fl == *Change* ]]; then chk_warn "secret has $fl=true: the password can rotate while the worker serves a cached copy for up to 12h" \
              "after a rotation: save the resource in the Admin UI (clears the cache)"
          else chk_warn "secret has $fl=true" "turn it off for secrets StrongDM reads"; fi
        fi
      done
      [ "$(jget "$CHK_SF" active)" = false ] && chk_fail "the secret is inactive (deleted)" "restore it, or point the resource at an active secret"
      chk_dl_table
    fi
    [ -n "$CHK_SF" ] || continue
    idxs=$(printf '%s\n' "$CHK_SF" | awk -F'\t' 'tolower($1)~/^items\.[0-9]+\.fieldname$/ {split($1,a,"."); print a[2] "\t" $3}' |
      while IFS=$'\t' read -r idx v; do v=$(printf '%b' "$v"); [ "$v" = "$key" ] && echo "$idx"; done)
    if [ -z "$idxs" ]; then
      near=$(printf '%s\n' "$CHK_SF" | awk -F'\t' -v k="$key" '(tolower($1)~/\.fieldname$/ && tolower($3)==tolower(k)) || (tolower($1)~/\.slug$/ && $3==k) {print $1 "=" $3; exit}')
      if [[ $near == *.slug=* ]]; then near=$(jget "$CHK_SF" "${near%%.slug=*}.fieldName"); else near=${near#*=}; fi
      chk_fail "$label key '$key' matches no field name (the worker reports 'failed to find field $key')" \
          "${near:+set the key to '$near' - }keys must equal the field's DISPLAY NAME exactly (case-sensitive), not its slug"
      continue
    fi
    [ "$(printf '%s\n' "$idxs" | wc -l)" -gt 1 ] && chk_warn "several fields are named '$key'; the worker uses the LAST one" "rename the duplicate field in the secret template"
    idx=$(printf '%s\n' "$idxs" | tail -1)
    v=$(jget "$CHK_SF" "items.$idx.itemValue")
    if [ -z "$v" ]; then chk_fail "$label field '$key' is empty (the worker reports 'failed to find field')" "fill in the '$key' field on the secret"; continue; fi
    [ "$label" = password ] && [ "$(jget "$CHK_SF" "items.$idx.isPassword")" != true ] && chk_warn "the password key '$key' is NOT the template's password field" \
        "point the password path at the template's password field (usually ?key=Password)"
    if [ "${CHK_L_ENC[j]}" = base64 ]; then
      v=$(printf '%s' "$v" | base64 -d 2>/dev/null) || { chk_fail "$label: encoding=base64 but the value does not decode" "remove &encoding=base64 from the path"; continue; }
    fi
    a=$(kit_anomalies "$v")
    if [ "$label" = username ]; then
      if [ "$(jget "$CHK_SF" "items.$idx.isPassword")" = true ]; then chk_fail "username path selects a password field" "correct the field mapping"
      else ok "username field is populated (value hidden)"; fi
    else
      CHK_VAL_PASS=$v
      if [ -n "$a" ]; then chk_warn "password $(kit_shape "$v"); anomalies: $a" "clean up the password in Secret Server (or compare below)"; else ok "password value: $(kit_shape "$v")"; fi
    fi
  done
  CHK_SF=""; v=""
}

chk_dl_compare() {
  local why="" ud k
  [ -n "$CHK_VAL_PASS" ] || return 0
  kit_noninteractive && { CHK_VAL_PASS=""; return 0; }
  printf '  %s?%s Paste the password that WORKS when typed manually (hidden; Enter alone skips): ' "$C_ACC" "$C_RST" >/dev/tty
  IFS= read -rs CHK_WANT </dev/tty || CHK_WANT=""; printf '\n' >/dev/tty
  if [ -z "$CHK_WANT" ]; then info "comparison skipped"
  elif [ "$CHK_VAL_PASS" = "$CHK_WANT" ]; then
    ok "the Secret Server value is byte-identical to the working password"
    note "so the worker gets the right password. Remaining suspects: the 12h credential cache (save the resource),"
    note "another worker serving the connection, or the username/domain shown above."
  else
    [ -z "$why" ] && [ "$(kit_trim "$CHK_VAL_PASS")" = "$CHK_WANT" ] && why="trimming whitespace"
    [ -z "$why" ] && [ "$(kit_html_unescape "$CHK_VAL_PASS")" = "$CHK_WANT" ] && why="HTML-unescaping (&amp; -> &)"
    [ -z "$why" ] && [ "$(kit_html_unescape "$(kit_trim "$CHK_VAL_PASS")")" = "$CHK_WANT" ] && why="trimming + HTML-unescaping"
    [ -z "$why" ] && [ "${CHK_VAL_PASS//[$'\r\n']/}" = "$CHK_WANT" ] && why="removing CR/LF"
    if [ -z "$why" ]; then printf -v ud '%b' "${CHK_VAL_PASS//%/\\x}"; [ "$ud" = "$CHK_WANT" ] && why="URL-decoding"; ud=""; fi
    if [ -n "$why" ]; then
      chk_fail "the Secret Server value DIFFERS from the working password; they match after $why" \
          "edit the password in Secret Server so it is stored exactly as typed, then save the resource in the Admin UI (clears the 12h cache)"
    else
      k=0; while [ $k -lt ${#CHK_VAL_PASS} ] && [ $k -lt ${#CHK_WANT} ] && [ "${CHK_VAL_PASS:k:1}" = "${CHK_WANT:k:1}" ]; do k=$((k+1)); done
      chk_fail "the Secret Server value DIFFERS from the working password (first difference at byte $k; ${#CHK_VAL_PASS} vs ${#CHK_WANT} bytes)" \
          "it is a genuinely different password: update the secret in Secret Server, then save the resource in the Admin UI"
    fi
  fi
  CHK_WANT=""; CHK_VAL_PASS=""
}

# ---------------------------------------------------------------- 6 report
chk_report() {
  local i n=0 sev shown=0 max=10 line
  [ ${#CHK_PROBS[@]} -gt 0 ] || { printf '\n'; ok "no problems found"; return 0; }
  kit_section "Most likely problems (failures first) and how to fix them"
  for sev in FAIL WARN; do
    for ((i=0; i<${#CHK_PROBS[@]}; i++)); do
      [ "${CHK_PSEV[i]}" = "$sev" ] || continue
      n=$((n+1))
      [ $shown -ge $max ] && continue
      shown=$((shown+1))
      if [ "$sev" = FAIL ]; then printf '  %s%d. [FAIL]%s %s\n' "$C_FAIL" "$shown" "$C_RST" "${CHK_PROBS[i]}"
      else printf '  %s%d. [WARN]%s %s\n' "$C_WARN" "$shown" "$C_RST" "${CHK_PROBS[i]}"; fi
      if [ -n "${CHK_FIXES[i]}" ]; then
        while IFS= read -r line; do note "fix: $line"; done <<<"${CHK_FIXES[i]}"
      fi
    done
  done
  [ $n -gt $max ] && note "... and $((n - max)) more above."
  return 0
}

# ---------------------------------------------------------------- entry
mode_check() {
  local rc=0
  kit_log_init check
  kit_banner "Check install - read-only health check (changes nothing)"
  chk_reset
  chk_discover
  chk_host
  chk_layout
  chk_connect
  chk_logs
  chk_delinea
  kit_summary || rc=$KIT_EXIT_FAIL
  chk_report
  return $rc
}

# ---------------------------------------------------------------- src/modes/debug.sh
# shellcheck shell=bash
# ============================================================================
# sdm-proxy-cluster-kit :: src/modes/debug.sh  -> mode_debug
# Turn on verbose logging for one worker, follow its journal, and switch it
# off on exit or through an independent systemd timer.
#
# @env KIT_DEBUG_UNIT  unit to debug when several sdm units exist (e.g. sdm-worker)
# @env KIT_DEBUG_FILTER  log filter: all | secrets | rdp | errors (non-interactive default: all)
# @env KIT_DEBUG_MINUTES  minutes to follow the journal before reverting (default 30, max 1440)
# @env KIT_DEBUG_KEEP  1 = leave SDM_VERBOSE=true in place when done (no revert)
# @env KIT_ASSUME_YES  1 = answer yes to the confirmations when non-interactive
# ============================================================================

# Mode state (globals so the EXIT handler can see them).
DBG_UNIT=""; DBG_ENVFILE=""; DBG_PRIOR_STATE=""; DBG_PRIOR_VALUE=""
DBG_CHANGED=0; DBG_FINISHED=0; DBG_ARMED=0; DBG_START=""; DBG_END=""; DBG_INTERRUPTED=0; DBG_FILTER=""
DBG_RUNTIME=/run/sdm-proxy-cluster-kit-debug
DBG_SESSION=""; DBG_PRIOR_PROCESS=""

# dbg_prop UNIT PROP -> value. Works on systemd 219 (RHEL 7 / Amazon Linux 2),
# which has no `systemctl show --value` (added in systemd 230).
dbg_prop() { local l; l=$(systemctl show -p "$2" -- "$1" 2>/dev/null </dev/null | head -1); printf '%s' "${l#*=}"; }
dbg_main_pid() { local p; p=$(dbg_prop "$1" MainPID); [ -n "$p" ] && [ "$p" != 0 ] && echo "$p"; }

# dbg_envfiles UNIT -> one path per line. systemd 219 prints EnvironmentFile=
# for each entry, while newer versions print EnvironmentFiles=.
dbg_envfiles() {
  systemctl show -p EnvironmentFiles -- "$1" 2>/dev/null </dev/null \
    | sed -e 's/^EnvironmentFiles=//' -e 's/^EnvironmentFile=//' \
    | tr ' ' '\n' | grep -E '^-?/' | sed -e 's/^-//'
}

# dbg_pick_envfile UNIT -> path of the env file this unit loads, or nothing.
# Prefers /etc/sysconfig/<unit> (what `sdm install` writes); otherwise the last
# listed file, because later EnvironmentFile= entries override earlier ones.
dbg_pick_envfile() {
  local u=$1 files fb="/etc/sysconfig/${1%.service}"
  files=$(dbg_envfiles "$u")
  if [ -n "$files" ]; then
    if printf '%s\n' "$files" | grep -qxF "$fb"; then echo "$fb"; else printf '%s\n' "$files" | tail -1; fi
    return 0
  fi
  # Older systemctl may not list it; accept the fallback only if the unit text references it.
  if systemctl cat -- "$u" 2>/dev/null </dev/null | grep -qE "^[[:space:]]*EnvironmentFile=-?${fb}[[:space:]]*$"; then echo "$fb"; fi
}

# dbg_unquote VALUE -> VALUE without one pair of surrounding quotes (systemd strips them).
dbg_unquote() { local v=$1; case $v in \"*\"|\'*\') v=${v:1:${#v}-2};; esac; printf '%s' "$v"; }

# dbg_save_prior FILE -> sets DBG_PRIOR_STATE (absent|present) and DBG_PRIOR_VALUE.
dbg_save_prior() {
  DBG_PRIOR_VALUE=""
  if kit_envfile_has "$1" SDM_VERBOSE; then
    DBG_PRIOR_STATE=present
    DBG_PRIOR_VALUE=$(kit_envfile_get "$1" SDM_VERBOSE) || DBG_PRIOR_VALUE=""
  else
    DBG_PRIOR_STATE=absent
  fi
}

# dbg_pid_verbose PID -> SDM_VERBOSE as the process sees it, or "<unset>".
dbg_pid_verbose() { local v; if v=$(kit_proc_env "$1" SDM_VERBOSE); then printf '%s' "$v"; else printf '<unset>'; fi; }

# dbg_wait_active UNIT SECONDS -> 0 once active (and still active 2s later), 1 otherwise.
dbg_wait_active() {
  local u=$1 n=$2 i st
  for ((i=0; i<n; i++)); do
    st=$(systemctl is-active -- "$u" 2>/dev/null </dev/null)
    if [ "$st" = active ]; then
      sleep 2
      [ "$(systemctl is-active -- "$u" 2>/dev/null </dev/null)" = active ] && return 0
    elif [ "$st" = failed ]; then
      return 1
    fi
    sleep 1
  done
  return 1
}

# The timer runs this same function in a separate systemd service. The lock on
# the private session directory serializes publication and both cleanup paths.
dbg_revert() (
  local session=$1 unit dropin expiry
  PATH=/usr/sbin:/usr/bin:/sbin:/bin
  [ -d "$session" ] || exit 0
  { exec 8<"$session"; } 2>/dev/null || { [ ! -d "$session" ]; exit; }
  flock -x 8 || exit 1
  [ -d "$session" ] || exit 0
  if [ -f "$session/state" ]; then
    { IFS= read -r unit && IFS= read -r dropin; } < "$session/state" || exit 1
    expiry="sdmkit-debug-${session##*.}"
    # Remove the optional env file first. Even a worker restart while systemd
    # still has the drop-in cached then reads only the original configuration.
    rm -f -- "$session/verbose" "$dropin" || exit 1
    rmdir -- "${dropin%/*}" 2>/dev/null || true
    timeout 15s systemctl daemon-reload </dev/null || exit 1
    if [ -f "$session/restart" ]; then
      timeout 70s systemctl restart -- "$unit" </dev/null || exit 1
      rm -f -- "$session/restart" || exit 1
    fi
    timeout 15s systemctl stop "$expiry.timer" >/dev/null 2>&1 || true
    rm -f -- "/run/systemd/system/$expiry.timer" "/run/systemd/system/$expiry.service" || exit 1
  fi
  rm -rf -- "$session" || exit 1
)

dbg_recover_sessions() {
  local session
  [ -e "$DBG_RUNTIME" ] || [ -L "$DBG_RUNTIME" ] || return 0
  kit_private_dir "$DBG_RUNTIME" || return 1
  for session in "$DBG_RUNTIME"/session.*; do
    [ -d "$session" ] || continue
    info "Cleaning up an interrupted debug session"
    dbg_revert "$session" || return 1
  done
}

# Load an optional environment file after the worker's existing files.
# Environment= would lose to any EnvironmentFile= already setting SDM_VERBOSE.
dbg_start_runtime() (
  local mins=$1 session=$DBG_SESSION dropdir dropin path name last='' expiry LC_ALL=C
  exec 8<"$session" && flock -x 8 || exit 1
  kit_trusted_dir /run/systemd/system || exit 1
  dropdir="/run/systemd/system/$DBG_UNIT.d"
  if [ ! -e "$dropdir" ]; then mkdir -m 0755 -- "$dropdir" || exit 1; fi
  kit_trusted_dir "$dropdir" || exit 1
  # systemd reads drop-ins in filename order across its search paths.
  while IFS= read -r path; do
    name=${path##*/}
    [[ $name > $last ]] && last=$name
  done < <(printf '%s\n' "$(dbg_prop "$DBG_UNIT" DropInPaths)" | sed 's| /|\n/|g')
  dropin="$dropdir/${last:+$last.}zz-sdmkit-${session##*.}.conf"
  expiry="/run/systemd/system/sdmkit-debug-${session##*.}"
  for path in "$dropin" "$expiry.timer" "$expiry.service"; do
    [ ! -e "$path" ] && [ ! -L "$path" ] || exit 1
  done
  printf '%s\n%s\n' "$DBG_UNIT" "$dropin" > "$session/state.tmp" &&
    mv -T -- "$session/state.tmp" "$session/state" || exit 1
  printf '[Service]\nEnvironmentFile=-%s/verbose\n' "$session" > "$session/worker.conf" || exit 1
  printf 'SDM_VERBOSE=true\n' > "$session/verbose.tmp" || exit 1

  # Use regular runtime units so Restart= works on systemd 219 as well.
  { declare -f dbg_revert && printf '\ndbg_revert "$1"\n'; } > "$session/revert" || exit 1
  cat > "$session/expiry.service" <<EOF || exit 1
[Unit]
Description=Expire temporary StrongDM debug logging
ConditionPathExists=$session/revert
[Service]
ExecStart=/bin/bash $session/revert $session
Restart=on-failure
RestartSec=5s
EOF
  cat > "$session/expiry.timer" <<EOF || exit 1
[Unit]
Description=StrongDM debug expiry timer
[Timer]
OnActiveSec=$((mins * 60 + 5))s
AccuracySec=1s
EOF
  # Create the unit files in their final directories for the local file labels.
  cp -T -- "$session/expiry.service" "$expiry.service" &&
    cp -T -- "$session/expiry.timer" "$expiry.timer" &&
    cp -T -- "$session/worker.conf" "$dropin" && timeout 15s systemctl daemon-reload </dev/null || exit 1
  [ "$(dbg_prop "${expiry##*/}.service" FragmentPath)" = "$expiry.service" ] &&
    [ "$(dbg_prop "${expiry##*/}.timer" FragmentPath)" = "$expiry.timer" ] || exit 1
  [ "$(dbg_envfiles "$DBG_UNIT" | tail -1)" = "$session/verbose" ] || exit 1
  timeout 15s systemctl start "${expiry##*/}.timer" </dev/null || exit 1
  [ "$(dbg_prop "${expiry##*/}.timer" SubState)" = waiting ] || exit 1
  : > "$session/restart" && mv -T -- "$session/verbose.tmp" "$session/verbose"
)

# dbg_filter_regex NAME -> extended regex for grep -Ei ("" = no filter). Returns 1 on an unknown name.
dbg_filter_regex() {
  case $1 in
    all) printf '';;
    secrets) printf '%s' 'credential field|FetchCredentials|tss-sdk-go|secretstore|secret store|delinea';;
    rdp) printf '%s' 'rdp|(^|[^a-z])nla([^a-z]|$)|credssp|kerberos|krb5|ntlm|spnego|tpkt|rdpdr|drdynvc|ephemeral user';;
    errors) printf '%s' 'level"?[=:] *"?(warn|warning|error|dpanic|panic|fatal)|panic:|goroutine [0-9]+ \[';;
    *) return 1;;
  esac
}

# dbg_harden_log: Ctrl-C reaches every process in the foreground group, including
# the `tee` that kit_log_init starts, and a dead tee would kill (SIGPIPE) the
# revert before it prints anything. Re-plumb the transcript through `tee -i`,
# writing to the original stdout saved in fd 7 by mode_debug.
# Safe to drop once kit_log_init itself uses `tee -i`.
dbg_harden_log() {
  [ -n "${KIT_LOG_FILE:-}" ] || return 0
  exec > >(exec tee -i -a "$KIT_LOG_FILE" >&7 2>&7) 2>&1
}

# dbg_capture_hint -> how to pull the captured window out of the journal later.
dbg_capture_hint() {
  local end=${DBG_END:-$(date '+%Y-%m-%d %H:%M:%S')}
  [ -n "$DBG_START" ] || return 0
  info "the verbose window is kept in the journal; to save it to a file later:"
  note "journalctl -u $DBG_UNIT --since '$DBG_START' --until '$end' --no-pager"
}

# dbg_finish: EXIT handler and normal end. Removes the runtime override and
# reports the restarted worker's effective environment.
# Runs once. Never exits (that would skip the remaining EXIT handlers).
dbg_finish() {
  local pid got
  [ "$DBG_FINISHED" = 1 ] && return 0
  DBG_FINISHED=1
  trap '' INT TERM HUP PIPE        # a second Ctrl-C or a hang-up must not cut the revert short
  [ "$DBG_ARMED" = 1 ] || return 0
  DBG_END=$(date '+%Y-%m-%d %H:%M:%S')
  kit_section "Switching verbose logging off"
  if [ -n "$DBG_SESSION" ]; then
    if dbg_revert "$DBG_SESSION"; then
      ok "removed the temporary SDM_VERBOSE override"
      if [ "$DBG_CHANGED" = 1 ]; then
        if dbg_wait_active "$DBG_UNIT" 60 && pid=$(dbg_main_pid "$DBG_UNIT"); then
          got=$(dbg_pid_verbose "$pid")
          ok "$DBG_UNIT MainPID $pid sees SDM_VERBOSE=$got after removing the override"
          if [ "$DBG_PRIOR_PROCESS" != '(no running process)' ] && [ "$got" != "$DBG_PRIOR_PROCESS" ]; then
            warn "the worker previously saw SDM_VERBOSE=$DBG_PRIOR_PROCESS; review its systemd environment"
          fi
        else
          fail "$DBG_UNIT has no stable MainPID after removing the override"
        fi
      fi
    else
      fail "could not complete cleanup for $DBG_UNIT"
      note "check: journalctl -u sdmkit-debug-${DBG_SESSION##*.}.service --no-pager"
    fi
  elif [ "$DBG_CHANGED" = 1 ]; then
    warn "KIT_DEBUG_KEEP=1: SDM_VERBOSE=true is LEFT ON in $DBG_ENVFILE"
    note "verbose logs are large and may contain request details; switch it off when done:"
    if [ "$DBG_PRIOR_STATE" = present ]; then
      note "sed -i 's/^SDM_VERBOSE=.*/SDM_VERBOSE=$DBG_PRIOR_VALUE/' $DBG_ENVFILE && systemctl restart $DBG_UNIT"
    else
      note "sed -i '/^SDM_VERBOSE=/d' $DBG_ENVFILE && systemctl restart $DBG_UNIT"
    fi
  else
    info "the kit did not change verbose logging for $DBG_UNIT"
  fi
  dbg_capture_hint
  [ -n "${KIT_LOG_FILE:-}" ] && info "kit transcript: $KIT_LOG_FILE"
  return 0
}

# dbg_find_unit -> sets DBG_UNIT, or exits.
dbg_find_unit() {
  local u found=()
  if [ -n "${KIT_DEBUG_UNIT:-}" ]; then
    systemctl cat -- "$KIT_DEBUG_UNIT" >/dev/null 2>&1 </dev/null || kit_die $KIT_EXIT_USAGE "KIT_DEBUG_UNIT=$KIT_DEBUG_UNIT is not a systemd unit on this host." \
      "systemctl cat $KIT_DEBUG_UNIT found nothing." \
      "systemctl list-units --all 'sdm*'     # see what exists
unset KIT_DEBUG_UNIT                   # or let the kit find it"
    DBG_UNIT=$KIT_DEBUG_UNIT; return 0
  fi
  if kit_unit_exists "$SDM_UNIT"; then DBG_UNIT=$SDM_UNIT; return 0; fi
  for u in "${KIT_FOREIGN_UNITS[@]}"; do kit_unit_exists "$u" && found+=("$u"); done
  case ${#found[@]} in
    0) kit_die $KIT_EXIT_PRECOND "No StrongDM worker service found on this host." \
         "Looked for systemd units: ${KIT_FOREIGN_UNITS[*]}. Debug mode works on an installed service." \
         "Run the kit again and choose 1 (New install), then come back to Debug.";;
    1) DBG_UNIT=${found[0]};;
    *) kit_pick KIT_DEBUG_UNIT "Several StrongDM services exist. Which one do you want to debug?" "${found[@]}"
       DBG_UNIT=$KIT_DEBUG_UNIT;;
  esac
  [ "$DBG_UNIT" = "$SDM_UNIT" ] || warn "$DBG_UNIT was not installed by this kit (it uses '$SDM_UNIT'); debugging it anyway"
}

# dbg_pick_filter -> sets DBG_FILTER (all|secrets|rdp|errors), or exits.
dbg_pick_filter() {
  local c=""
  if [ -n "${KIT_DEBUG_FILTER:-}" ]; then
    dbg_filter_regex "$KIT_DEBUG_FILTER" >/dev/null || kit_die $KIT_EXIT_USAGE "KIT_DEBUG_FILTER='$KIT_DEBUG_FILTER' is not a filter." \
      "Valid filters: all, secrets, rdp, errors." "export KIT_DEBUG_FILTER=all"
    DBG_FILTER=$KIT_DEBUG_FILTER; return 0
  fi
  if kit_noninteractive; then DBG_FILTER=all; return 0; fi
  kit_pick c "Which log lines do you want to see?" \
    "all       - every line from the worker" \
    "secrets   - secret store / Delinea credential lookups" \
    "rdp       - RDP, NLA, CredSSP, Kerberos and NTLM" \
    "errors    - warnings and errors only"
  DBG_FILTER=${c%% *}
}

mode_debug() {
  local total=6 pid act sub since user pverb fverb filt re mins rc follow_pid signal=0

  exec 7>&1                      # original stdout, for dbg_harden_log
  kit_log_init debug
  dbg_harden_log
  exec 7>&-
  trap 'exit 129' HUP            # ssh drop: still run the EXIT handlers (revert)
  kit_banner "Debug install - verbose logs, auto-revert when done"

  # ---- 1. preconditions
  kit_step 1 $total "Checking this host"
  if ! kit_has_systemd; then
    if kit_in_container; then
      kit_die $KIT_EXIT_PRECOND "This is a container without systemd, so there is no service to restart." \
        "SDM_VERBOSE is read once when the sdm process starts. In a container it comes from the container environment." \
        "Docker:      add  -e SDM_VERBOSE=true  (or SDM_VERBOSE: \"true\" under environment: in compose), recreate the container,
             then  docker logs -f <container>
Kubernetes:  kubectl set env deployment/<name> SDM_VERBOSE=true   # rolls the pods
             kubectl logs -f deployment/<name>
When done:   remove SDM_VERBOSE (kubectl set env deployment/<name> SDM_VERBOSE-) and recreate again."
    fi
    kit_die $KIT_EXIT_PRECOND "systemd is not running on this host." \
      "Debug mode restarts the worker through systemd and reads its journal." \
      "Run the kit on a systemd host (RHEL/Rocky/Alma 7-9, Amazon Linux, Ubuntu/Debian)."
  fi
  kit_require_root
  kit_lock_changes
  dbg_recover_sessions || kit_die $KIT_EXIT_PRECOND "Could not prepare the debug runtime directory or finish an interrupted debug session." \
    "Runtime state: $DBG_RUNTIME" "Check its ownership and the debug cleanup journal."
  kit_have journalctl || kit_die $KIT_EXIT_PRECOND "journalctl is not installed." \
    "Workers log to journald (SDM_LOG_OUTPUT=stdout); the kit follows them with journalctl." \
    "dnf install -y systemd      # RHEL family
apt-get install -y systemd  # Ubuntu / Debian"
  kit_have timeout || kit_ensure_cmds timeout
  mins=${KIT_DEBUG_MINUTES:-30}
  if ! [[ $mins =~ ^0*([1-9][0-9]{0,3})$ ]] || [ "${BASH_REMATCH[1]}" -gt 1440 ]; then
    kit_die $KIT_EXIT_USAGE "KIT_DEBUG_MINUTES='$mins' is not a number of minutes." "Use a whole number from 1 to 1440." "export KIT_DEBUG_MINUTES=30"
  fi
  mins=${BASH_REMATCH[1]}
  ok "systemd, journalctl and root are available"

  # ---- 2. which service
  kit_step 2 $total "Finding the worker service"
  dbg_find_unit
  DBG_UNIT=$(dbg_prop "$DBG_UNIT" Id)
  if ! [[ $DBG_UNIT =~ ^([a-zA-Z0-9_.:@-]|\\x[[:xdigit:]]{2})+\.service$ ]]; then
    kit_die $KIT_EXIT_PRECOND "The selected unit is not an installed systemd service." "" "Select a worker service with KIT_DEBUG_UNIT."
  fi
  DBG_ENVFILE=$(dbg_pick_envfile "$DBG_UNIT")
  if [ -z "$DBG_ENVFILE" ]; then
    kit_die $KIT_EXIT_PRECOND "$DBG_UNIT does not load an environment file, so SDM_VERBOSE cannot be set safely." \
      "'sdm install' creates the unit with EnvironmentFile=-/etc/sysconfig/${DBG_UNIT%.service}. This unit was set up some other way." \
      "Re-run the kit and choose 1 (New install) to install the service the supported way, or set it by hand:
systemctl edit $DBG_UNIT     # add:  [Service]  Environment=SDM_VERBOSE=true
systemctl restart $DBG_UNIT  # and remove the drop-in again when done"
  fi
  if [ -L "$DBG_ENVFILE" ] || ! kit_trusted_dir "$(dirname -- "$DBG_ENVFILE")"; then kit_die 3 "Unsafe environment file location." "" "Review the systemd unit configuration."; fi
  if [ ! -f "$DBG_ENVFILE" ]; then
    kit_die $KIT_EXIT_PRECOND "The env file $DBG_ENVFILE that $DBG_UNIT loads does not exist." \
      "'sdm install' always writes it (SDM_HOME, SDM_LOG_OUTPUT=stdout); without it this unit was not installed by 'sdm install', and creating one by guesswork could change how it runs." \
      "Re-run the kit and choose 1 (New install) - it repairs the env file without re-registering a healthy worker."
  fi
  kit_trusted_file "$DBG_ENVFILE" || kit_die 3 "Untrusted worker environment file." "" "Review ownership and write permissions before enabling debug."
  act=$(systemctl is-active -- "$DBG_UNIT" 2>/dev/null </dev/null); sub=$(dbg_prop "$DBG_UNIT" SubState)
  user=$(dbg_prop "$DBG_UNIT" User); pid=$(dbg_main_pid "$DBG_UNIT")
  since=$(dbg_prop "$DBG_UNIT" ActiveEnterTimestamp)
  if [ -n "$pid" ]; then pverb=$(dbg_pid_verbose "$pid"); else pverb="(no running process)"; fi
  DBG_PRIOR_PROCESS=$pverb
  if kit_envfile_has "$DBG_ENVFILE" SDM_VERBOSE; then fverb=$(kit_envfile_get "$DBG_ENVFILE" SDM_VERBOSE) || fverb='""'; else fverb="<not set>"; fi
  info "unit:         $DBG_UNIT  (${act:-unknown}/${sub:-?})"
  info "runs as:      ${user:-root}"
  info "MainPID:      ${pid:-none}   started: ${since:-n/a}"
  info "env file:     $DBG_ENVFILE"
  info "SDM_VERBOSE:  running process = $pverb   env file = $fverb"

  # ---- 3. confirm
  kit_step 3 $total "Confirm the restart"
  if [ "$act" != active ]; then
    warn "$DBG_UNIT is not running (state: ${act:-unknown}). That may be exactly what you are debugging."
    kit_confirm "Start it with verbose logging anyway?" y || kit_die $KIT_EXIT_ABORTED "Stopped at your request." "Nothing was changed." ""
  fi
  DBG_ARMED=1                    # from here on, the EXIT handler reports and reverts
  kit_on_exit dbg_finish
  if [ "$pverb" = true ] && [ "$(dbg_unquote "$fverb")" = true ]; then
    ok "verbose logging is already on for this process; no restart needed, nothing will be changed"
    DBG_START=$(date '+%Y-%m-%d %H:%M:%S')
  else
    warn "Restarting $DBG_UNIT DROPS every active session going through THIS worker"
    note "(other workers in the proxy cluster keep serving; users reconnect through them or this one)"
    if [ "${KIT_DEBUG_KEEP:-}" != 1 ]; then note "It is restarted again at the end to switch verbose logging off."; fi
    kit_confirm "Restart $DBG_UNIT with SDM_VERBOSE=true now?" n || kit_die $KIT_EXIT_ABORTED "Stopped at your request." "Nothing was changed." ""

    # ---- 4. set
    kit_step 4 $total "Turning on verbose logging"
    if [ "${KIT_DEBUG_KEEP:-}" != 1 ]; then
      kit_private_dir "$DBG_RUNTIME" && DBG_SESSION=$(mktemp -d "$DBG_RUNTIME/session.XXXXXXXX") &&
        dbg_start_runtime "$mins" ||
        kit_die $KIT_EXIT_FAIL "Could not enable the temporary debug override for $DBG_UNIT." \
          "Debug requires a systemd expiry timer and an environment file that loads last." "systemctl cat $DBG_UNIT"
      DBG_CHANGED=1
      ok "temporary SDM_VERBOSE=true override enabled with a systemd expiry timer"
    elif [ "$(dbg_unquote "$fverb")" = true ]; then
      info "$DBG_ENVFILE already has SDM_VERBOSE=true (the process just has not been restarted since); leaving the file alone"
    else
      dbg_save_prior "$DBG_ENVFILE"
      kit_envfile_set "$DBG_ENVFILE" SDM_VERBOSE true || kit_die $KIT_EXIT_FAIL "Could not write $DBG_ENVFILE." \
        "The file may be read-only or the disk full." "ls -l $DBG_ENVFILE; df -h /etc"
      DBG_CHANGED=1
      ok "SDM_VERBOSE=true written to $DBG_ENVFILE (previously: $([ "$DBG_PRIOR_STATE" = present ] && printf '%s' "$DBG_PRIOR_VALUE" || printf 'not set'))"
    fi

    # ---- 5. restart
    kit_step 5 $total "Restarting $DBG_UNIT"
    DBG_START=$(date '+%Y-%m-%d %H:%M:%S')
    systemctl restart -- "$DBG_UNIT" </dev/null && dbg_wait_active "$DBG_UNIT" 60 || kit_die $KIT_EXIT_FAIL "$DBG_UNIT did not become active within 60 seconds." \
      "Last journal lines:
$(journalctl -u "$DBG_UNIT" -n 20 --no-pager -o short-iso 2>&1)" \
      "systemctl status $DBG_UNIT
journalctl -u $DBG_UNIT --since '$DBG_START' --no-pager"
    pid=$(dbg_main_pid "$DBG_UNIT")
    pverb=$(dbg_pid_verbose "${pid:-0}")
    [ -n "$pid" ] && [ "$pverb" = true ] || kit_die $KIT_EXIT_FAIL "The restarted process (MainPID ${pid:-none}) does not see SDM_VERBOSE=true (it sees $pverb)." \
      "Something later in the unit overrides it (another EnvironmentFile=, or a wrapper script)." \
      "systemctl cat $DBG_UNIT
systemctl show -p EnvironmentFiles -p Environment $DBG_UNIT"
    ok "$DBG_UNIT is active, MainPID $pid has SDM_VERBOSE=true"
  fi

  # ---- 6. follow
  kit_step 6 $total "Following the logs"
  dbg_pick_filter
  filt=$DBG_FILTER
  re=$(dbg_filter_regex "$filt")
  info "filter: $filt   time limit: $mins minute(s)"
  warn "verbose logs can contain sensitive request details"
  printf '\n%s+----------------------------------------------------------------------+%s\n' "$C_ACC" "$C_RST"
  printf '%s|%s %s%-68s%s %s|%s\n' "$C_ACC" "$C_RST" "$C_HEAD" "Reproduce the problem now." "$C_RST" "$C_ACC" "$C_RST"
  printf '%s|%s %-68s %s|%s\n' "$C_ACC" "$C_RST" "Press Ctrl-C when done." "$C_ACC" "$C_RST"
  printf '%s+----------------------------------------------------------------------+%s\n\n' "$C_ACC" "$C_RST"
  # Waiting for a background job lets Bash handle disconnects immediately.
  trap 'signal=130' INT
  trap 'signal=143' TERM
  trap 'signal=129' HUP
  local journal_args=(journalctl -u "$DBG_UNIT" -f -o short-iso --no-pager --since "$DBG_START")
  # An orphaned journal reader must not keep the kit's changes lock alive.
  if [ -z "$re" ]; then
    timeout "${mins}m" "${journal_args[@]}" 9>&- </dev/null &
  else
    timeout "${mins}m" "${journal_args[@]}" 9>&- </dev/null > >(grep -E -i --line-buffered -e "$re" 9>&-) &
  fi
  follow_pid=$!
  if [ "$signal" = 0 ]; then wait "$follow_pid"; rc=$?; else rc=$signal; fi
  if [ "$signal" != 0 ]; then
    trap '' INT TERM HUP
    kill -TERM "$follow_pid" 2>/dev/null || true
    wait "$follow_pid" 2>/dev/null || true
    [ "$signal" = 130 ] || exit "$signal"
    DBG_INTERRUPTED=1
  fi
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP
  echo
  if [ "$DBG_INTERRUPTED" = 1 ]; then info "stopped with Ctrl-C"
  elif [ "$rc" = 124 ]; then info "time limit of $mins minute(s) reached"
  else warn "journalctl stopped unexpectedly (exit $rc)"; fi

  dbg_finish
  kit_summary
}

# ---------------------------------------------------------------- src/modes/install.sh
# shellcheck shell=bash
# ============================================================================
# sdm-proxy-cluster-kit :: src/modes/install.sh   (defines mode_install)
#
# Installs or repairs a StrongDM proxy cluster worker running as user `sdm`
# with SDM_HOME=/home/sdm/.sdm. Every input (including secrets) is collected
# before anything on the host changes. Private helpers are prefixed inst_.
#
# Environment variables read by this mode:
# @env SDM_APP_DOMAIN  Control plane region: app.strongdm.com, app.eu.strongdm.com or app.uk.strongdm.com (skips the region menu)
# @env SDM_PROXY_CLUSTER_ACCESS_KEY  Proxy cluster access key (skips the prompt)
# @env SDM_PROXY_CLUSTER_SECRET_KEY  Proxy cluster secret key (skips the hidden prompt; never printed)
# @env KIT_DELINEA  yes|no - will this cluster use Delinea Secret Server (default when unset and non-interactive: yes if DELINEA_USERNAME is set)
# @env KIT_ROTATE_DELINEA  yes = replace an existing sealed Delinea username and password. Ordinary repairs keep the existing pair.
# @env DELINEA_USERNAME  Delinea Secret Server username, sealed into the node secret store
# @env DELINEA_PASSWORD  Delinea Secret Server password, sealed into the node secret store (never printed)
# @env DELINEA_SERVER_URL  Optional Delinea server URL written to /etc/sysconfig/sdm-worker (blank = configured on the secret store in the Admin UI)
# @env SDM_BIND_ADDRESS  Worker listen address (default :8443; never prompted)
# @env KIT_ASSUME_YES  1 = accept the install summary and other yes/no confirmations when non-interactive
# @env KIT_BACKUP_CERT  Path to a root-protected PEM encryption certificate for foreign-install backups; keep the private key offline
# @env KIT_REPLACE  yes = allow replacing a foreign StrongDM install when non-interactive (instead of typing REPLACE)
# @env KIT_FORCE_REINSTALL  yes = reprovision the CLI, sealed keys and unit on an existing worker
# @env KIT_START_TIMEOUT  Seconds to wait for the worker to come up (default 90)
# ============================================================================

INST_TOTAL=13
INST_STATE_FILE="$KIT_DIR/install.state"       # root 0600: key fingerprint, domain, bind
INST_PENDING_FILE="$KIT_DIR/activation.pending" # root 0600: interrupted provisioning or activation
INST_REPLACED_LIST="$KIT_DIR/replaced.list"    # foreign items already backed up + stopped

# ---------------------------------------------------------------- small helpers
inst_abort() { printf '\n'; info "Aborted by the operator. Nothing further was changed."; exit "$KIT_EXIT_ABORTED"; }


inst_nologin() { local p; for p in /usr/sbin/nologin /sbin/nologin /usr/bin/nologin; do [ -x "$p" ] && { echo "$p"; return; }; done; echo /bin/false; }

inst_user_home() { getent passwd "$1" 2>/dev/null | awk -F: '{print $6; exit}'; }

inst_strip_quotes() { local v=$1; v=${v#[\"\']}; v=${v%[\"\']}; printf '%s' "$v"; }

inst_bind_port() { local b=${1:-$SDM_DEFAULT_BIND}; printf '%s' "${b##*:}"; }

# Fingerprint of the key pair (salted sha256), so a re-run can tell whether the
# keys changed without storing them. printf is a builtin: nothing on argv.
inst_key_fp() { printf 'sdm-proxy-cluster-kit:v1\n%s\n%s' "$SDM_PROXY_CLUSTER_ACCESS_KEY" "$SDM_PROXY_CLUSTER_SECRET_KEY" | sha256sum | awk '{print $1}'; }

inst_state_get() { kit_envfile_get "$INST_STATE_FILE" "$1" 2>/dev/null; }
inst_state_set() {
  kit_private_dir "$KIT_DIR" || return 1
  kit_envfile_set "$INST_STATE_FILE" "$1" "$2"
}

inst_read_pending() {
  INST_PENDING=""
  [ -e "$INST_PENDING_FILE" ] || [ -L "$INST_PENDING_FILE" ] || return 0
  kit_trusted_file "$INST_PENDING_FILE" && [ "$(stat -c %a "$INST_PENDING_FILE")" = 600 ] ||
    inst_failed "Unsafe pending worker activation record."
  INST_PENDING=$(kit_envfile_get "$INST_PENDING_FILE" PHASE)
  case "$INST_PENDING" in
    provision|activate) return 0;;
    *) inst_failed "Invalid pending worker activation record.";;
  esac
}

# Call before changing any settings or files that the worker loads at startup.
inst_mark_pending() {
  local phase
  kit_private_dir "$KIT_DIR" || inst_failed "Unsafe administrative directory for pending worker activation."
  inst_read_pending
  phase=${1:-${INST_PENDING:-activate}}
  if [ "$INST_PENDING" != "$phase" ]; then
    # Unit, state and environment files can live on different filesystems.
    if [ "$INST_PENDING" = provision ]; then sync || inst_failed "Cannot flush provisioned worker files."; fi
    kit_envfile_set "$INST_PENDING_FILE" PHASE "$phase" && sync || inst_failed "Cannot record pending worker activation."
    INST_PENDING=$phase
  fi
  INST_NEED_RESTART=1
}

inst_was_replaced() { [ -r "$INST_REPLACED_LIST" ] && grep -qxF -- "$1" "$INST_REPLACED_LIST"; }

# Which systemd service a PID belongs to (from its cgroup), or empty.
inst_pid_unit() { sed -n 's#.*/\([^/]*\)\.service.*#\1#p' "/proc/$1/cgroup" 2>/dev/null | head -1; }
inst_pid_start() { awk '{sub(/.*\) /,""); if ($1 !~ /^[XZ]$/ && $20 ~ /^[0-9]+$/) print $20}' "/proc/$1/stat" 2>/dev/null; }

# Names (never values) of KEY=VALUE lines in an env file.
inst_env_keys() { [ -r "$1" ] && kit_envfile_records names < "$1"; }

# Names in the sealed sidecar (as the worker, via the installed binary). Sets
# INST_SEALED_KEYS; returns 1 when the sidecar exists but cannot be read.
inst_sealed_keys() {
  local out rc
  INST_SEALED_KEYS=""
  [ -f "$SDM_SIDECAR" ] || return 0
  [ -x "$SDM_BIN" ] || return 0
  out=$(kit_as_worker "$SDM_HOME_DIR" "$SDM_BIN" nodesecrets list 2>/dev/null </dev/null); rc=$?
  if [ $rc -ne 0 ]; then INST_SEALED_ERR="service user could not read sealed keys"; return 1; fi
  INST_SEALED_KEYS=" $(printf '%s\n' "$out" | grep -E '^[A-Za-z_][A-Za-z0-9_]*$' | tr '\n' ' ')"
  return 0
}
inst_sealed_has() { [[ ${INST_SEALED_KEYS:-} == *" $1 "* ]]; }
inst_delinea_sealed() { inst_sealed_keys && inst_sealed_has DELINEA_USERNAME && inst_sealed_has DELINEA_PASSWORD; }

# Does a file contain a secret value? Pure bash: the value never hits argv.
inst_file_contains() { local f=$1 v=$2 c; [ -n "$v" ] && [ -r "$f" ] || return 1; c=$(cat "$f" 2>/dev/null); [[ $c == *"$v"* ]]; }

# ============================================================================
# STEP 1: preflight
# ============================================================================
inst_preflight() {
  kit_step 1 $INST_TOTAL "Preflight checks"
  kit_require_root; ok "running as root"
  if kit_in_container; then
    kit_die $KIT_EXIT_PRECOND "This looks like a container; the kit does not install workers inside containers." \
"sdm seals the proxy cluster keys to the host's machine-id and refuses to do that in a container
on this platform. Use host-based sealing on a full virtual machine or physical host." \
"Run the worker with the official image and pass secrets via the orchestrator instead:
  mount a secrets file and set SDM_SECRETS_FILE=/path/to/file in the container
  (plus SDM_PROXY_CLUSTER_ACCESS_KEY / SDM_PROXY_CLUSTER_SECRET_KEY or the same keys in that file)
Or run this kit on the VM / host itself."
  fi
  ok "not a container"
  kit_has_systemd || kit_die $KIT_EXIT_PRECOND "systemd is not running on this host." \
    "The worker is installed as the systemd unit $SDM_UNIT." \
    "Use a systemd-based distribution (RHEL/Rocky/Alma 7-9, Amazon Linux 2/2023, Ubuntu, Debian)."
  ok "systemd is running"
  kit_detect_os
  case "$OS_ID" in
    rhel|rocky|almalinux|centos|ol|amzn|ubuntu|debian) ok "OS: $OS_PRETTY";;
    *) warn "OS '$OS_PRETTY' is not one the kit is tested on; continuing";
       note "tested: RHEL/Rocky/Alma 7-9, Amazon Linux 2/2023, Ubuntu, Debian";;
  esac
  INST_ARCH=$(kit_arch) || exit $KIT_EXIT_PRECOND
  ok "architecture: $INST_ARCH"
  INST_SELINUX=$(kit_selinux_mode)
  info "SELinux: ${INST_SELINUX:-Disabled}"
}

# ============================================================================
# STEP 2: collect every input before changing anything
# ============================================================================
inst_collect() {
  kit_step 2 $INST_TOTAL "Collect settings and secrets (nothing has been changed yet)"
  local d okd=0 a

  # Region.
  kit_pick SDM_APP_DOMAIN "Which StrongDM region is your organization in?" "${KIT_APP_DOMAINS[@]}"
  SDM_APP_DOMAIN=$(kit_trim "$SDM_APP_DOMAIN"); SDM_APP_DOMAIN=${SDM_APP_DOMAIN#https://}; SDM_APP_DOMAIN=${SDM_APP_DOMAIN%/}
  for d in "${KIT_APP_DOMAINS[@]}"; do [ "$d" = "$SDM_APP_DOMAIN" ] && okd=1; done
  [ $okd = 1 ] || kit_die $KIT_EXIT_USAGE "Unknown region '$SDM_APP_DOMAIN'." \
    "Proxy cluster workers connect to one of: ${KIT_APP_DOMAINS[*]}" \
    "export SDM_APP_DOMAIN=app.strongdm.com   # or app.eu.strongdm.com / app.uk.strongdm.com"
  ok "region: $SDM_APP_DOMAIN"

  # Proxy cluster keys. Never exported to every child: only the install subshell gets them.
  note "Admin UI > Networking > Proxy Clusters > (your cluster) > add key gives you an access key + secret key."
  kit_ask_secret SDM_PROXY_CLUSTER_ACCESS_KEY "Proxy cluster access key"
  kit_ask_secret SDM_PROXY_CLUSTER_SECRET_KEY "Proxy cluster secret key"
  export -n SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY 2>/dev/null || true
  inst_clean_secret SDM_PROXY_CLUSTER_ACCESS_KEY "access key" trim
  inst_clean_secret SDM_PROXY_CLUSTER_SECRET_KEY "secret key" trim
  [ -n "$SDM_PROXY_CLUSTER_ACCESS_KEY" ] || kit_die $KIT_EXIT_USAGE "The access key is empty." "" "export SDM_PROXY_CLUSTER_ACCESS_KEY='...' and re-run"
  [ -n "$SDM_PROXY_CLUSTER_SECRET_KEY" ] || kit_die $KIT_EXIT_USAGE "The secret key is empty." "" "export SDM_PROXY_CLUSTER_SECRET_KEY='...' and re-run"
  [[ $SDM_PROXY_CLUSTER_ACCESS_KEY =~ [[:space:]] ]] && kit_die $KIT_EXIT_USAGE "The access key contains whitespace." \
    "Keys are a single token; a space usually means two values were pasted together." "Copy the access key again from the Admin UI and re-run."
  [[ $SDM_PROXY_CLUSTER_SECRET_KEY =~ [[:space:]] ]] && kit_die $KIT_EXIT_USAGE "The secret key contains whitespace." \
    "Keys are a single token; a space usually means two values were pasted together." "Copy the secret key again from the Admin UI and re-run."
  if [[ $SDM_PROXY_CLUSTER_ACCESS_KEY != pk-* ]]; then
    if [[ $SDM_PROXY_CLUSTER_SECRET_KEY == pk-* ]]; then
      kit_die $KIT_EXIT_USAGE "The access key and secret key look swapped." "The access key is the one that starts with 'pk-'." "Re-run and enter the pk-... value as the access key."
    fi
    kit_die $KIT_EXIT_USAGE "The access key does not start with 'pk-'." \
      "Proxy cluster access keys look like pk-XXXX ($(kit_shape "$SDM_PROXY_CLUSTER_ACCESS_KEY") was entered); sdm refuses anything else." \
      "Admin UI > Networking > Proxy Clusters > your cluster > add key, then re-run with that access key."
  fi
  [ "$SDM_PROXY_CLUSTER_ACCESS_KEY" = "$SDM_PROXY_CLUSTER_SECRET_KEY" ] && kit_die $KIT_EXIT_USAGE \
    "The access key and the secret key are identical." "The same value was probably pasted twice." "Re-run and paste the access key, then the secret key."

  # Delinea Secret Server.
  export -n DELINEA_USERNAME DELINEA_PASSWORD 2>/dev/null || true
  INST_DELINEA=no; INST_ROTATE_DELINEA=no; INST_KEEP_DELINEA=0
  case ${KIT_ROTATE_DELINEA:-no} in
    yes) INST_ROTATE_DELINEA=yes;;
    no) ;;
    *) kit_die $KIT_EXIT_USAGE "KIT_ROTATE_DELINEA must be yes or no." "" "Use yes to replace the sealed Delinea pair.";;
  esac
  a=$(printf '%s' "${KIT_DELINEA:-}" | tr '[:upper:]' '[:lower:]')
  case "$a" in
    yes|y|true|1) INST_DELINEA=yes;;
    no|n|false|0) INST_DELINEA=no;;
    "") if [ "$INST_ROTATE_DELINEA" = yes ]; then INST_DELINEA=yes
        elif kit_noninteractive; then [ -n "${DELINEA_USERNAME:-}" ] && INST_DELINEA=yes
        elif kit_confirm "Will this cluster use Delinea Secret Server as a secret store?" n; then INST_DELINEA=yes; fi;;
    *) kit_die $KIT_EXIT_USAGE "KIT_DELINEA must be yes or no (got '$KIT_DELINEA')." "" "export KIT_DELINEA=yes   # or no";;
  esac
  if [ "$INST_ROTATE_DELINEA" = yes ] && [ "$INST_DELINEA" != yes ]; then
    kit_die $KIT_EXIT_USAGE "Delinea rotation requires Delinea provisioning." "" "Set KIT_DELINEA=yes or unset KIT_ROTATE_DELINEA."
  fi
  if [ "$INST_DELINEA" = yes ]; then
    if [ "$INST_ROTATE_DELINEA" = no ] && inst_delinea_sealed; then
      if ! kit_noninteractive && [ -z "${KIT_ROTATE_DELINEA:-}" ] && kit_confirm "Rotate the existing sealed Delinea credentials?" n; then INST_ROTATE_DELINEA=yes
      else INST_KEEP_DELINEA=1; fi
    fi
    if [ "$INST_KEEP_DELINEA" = 0 ]; then
      kit_ask DELINEA_USERNAME "Delinea Secret Server username"
      kit_secret_register DELINEA_USERNAME
      kit_ask_secret DELINEA_PASSWORD "Delinea Secret Server password"
      export -n DELINEA_USERNAME DELINEA_PASSWORD 2>/dev/null || true
      inst_clean_secret DELINEA_USERNAME "Delinea username" trim
      inst_clean_secret DELINEA_PASSWORD "Delinea password" keep
      [ -n "$DELINEA_USERNAME" ] && [ -n "$DELINEA_PASSWORD" ] ||
        kit_die $KIT_EXIT_USAGE "Delinea provisioning requires both a username and a password." "" "Supply both values and re-run install."
    else
      unset DELINEA_USERNAME DELINEA_PASSWORD
    fi
    if [ -z "${DELINEA_SERVER_URL:-}" ] && ! kit_noninteractive; then
      kit_ask DELINEA_SERVER_URL "Delinea server URL (leave blank if it is set on the secret store in the Admin UI)" ""
    fi
    DELINEA_SERVER_URL=$(kit_trim "${DELINEA_SERVER_URL:-}")
  else
    unset DELINEA_USERNAME DELINEA_PASSWORD
  fi
  if [ -n "${DELINEA_SERVER_URL:-}" ] && ! kit_https_url "$DELINEA_SERVER_URL"; then
      kit_die $KIT_EXIT_USAGE "DELINEA_SERVER_URL must be an https:// URL." "" "export DELINEA_SERVER_URL=https://yourtenant.secretservercloud.com   # or leave it unset"
  fi

  # Bind address (env only).
  INST_BIND=$(kit_trim "${SDM_BIND_ADDRESS:-$SDM_DEFAULT_BIND}")
  [[ $INST_BIND =~ ^[^[:space:]]*:[0-9]+$ ]] || kit_die $KIT_EXIT_USAGE "SDM_BIND_ADDRESS '$INST_BIND' is not host:port or :port." "" "export SDM_BIND_ADDRESS=:8443"
  local port; port=$(inst_bind_port "$INST_BIND")
  { [ "$port" -ge 1 ] && [ "$port" -le 65535 ]; } 2>/dev/null || kit_die $KIT_EXIT_USAGE "Port $port is out of range." "" "export SDM_BIND_ADDRESS=:8443"

  # Summary (shapes only, never values).
  kit_section "Please confirm"
  printf '    %-26s %s\n' "service user" "$SDM_USER  (home $SDM_USER_HOME, SDM_HOME $SDM_HOME_DIR)"
  printf '    %-26s %s\n' "region" "$SDM_APP_DOMAIN"
  printf '    %-26s %s\n' "access key" "hidden  ($(kit_shape "$SDM_PROXY_CLUSTER_ACCESS_KEY"))"
  printf '    %-26s %s\n' "secret key" "hidden  ($(kit_shape "$SDM_PROXY_CLUSTER_SECRET_KEY"))"
  printf '    %-26s %s\n' "bind address" "$INST_BIND"
  if [ "$INST_DELINEA" = yes ]; then
    if [ "$INST_KEEP_DELINEA" = 1 ]; then
      info "Keeping existing sealed Delinea credentials. Use KIT_ROTATE_DELINEA=yes to apply new values."
    else
      printf '    %-26s %s\n' "Delinea username" "hidden  ($(kit_shape "$DELINEA_USERNAME"))"
      printf '    %-26s %s\n' "Delinea password" "hidden  ($(kit_shape "$DELINEA_PASSWORD"))"
    fi
    printf '    %-26s %s\n' "Delinea server URL" "${DELINEA_SERVER_URL:-(from the secret store in the Admin UI)}"
  else
    printf '    %-26s %s\n' "Delinea Secret Server" "not used"
  fi
  if kit_noninteractive && [ "${KIT_ASSUME_YES:-}" != 1 ]; then
    kit_die $KIT_EXIT_USAGE "Non-interactive install needs explicit consent." "There is no terminal to confirm the summary above on." "export KIT_ASSUME_YES=1 and re-run"
  fi
  kit_confirm "Proceed with these settings?" y || inst_abort
}

# inst_clean_secret VAR label trim|keep : reject CR/LF, optionally trim, warn on oddities (no values shown).
inst_clean_secret() {
  local __v=$1 label=$2 mode=$3 val an t
  val=${!__v:-}
  if [[ $val == *$'\r'* || $val == *$'\n'* ]]; then
    kit_die $KIT_EXIT_USAGE "The $label contains a line break." "Values must be a single line (they are sealed one line per key)." "Re-run and paste the value again without the trailing newline."
  fi
  if [ "$mode" = trim ]; then
    t=$(kit_trim "$val")
    if [ "$t" != "$val" ]; then warn "removed leading/trailing whitespace from the $label"; printf -v "$__v" '%s' "$t"; val=$t; fi
  fi
  an=$(kit_anomalies "$val")
  [ -n "$an" ] && { warn "the $label looks unusual: $an"; note "($(kit_shape "$val")) - check it if authentication fails later"; }
  t=""; val=""
  return 0
}

# ============================================================================
# STEP 3 / 4: dependencies and reachability
# ============================================================================
inst_deps() {
  kit_step 3 $INST_TOTAL "Required tools"
  kit_have runuser && kit_have setsid && kit_have flock || kit_die 3 "Required util-linux tools are missing." "" "Install util-linux."
  kit_ensure_cmds curl unzip sha256sum
  ok "curl, unzip and sha256sum are available"
}

inst_reach() {
  kit_step 4 $INST_TOTAL "Can this host reach $SDM_APP_DOMAIN:443?"
  if kit_tcp_ok "$SDM_APP_DOMAIN" 443; then ok "TCP 443 to $SDM_APP_DOMAIN is open"; return 0; fi
  if [ -n "${https_proxy:-${HTTPS_PROXY:-}}" ]; then
    kit_http GET "https://$SDM_APP_DOMAIN/"
    if [ "$HE" = 0 ] && [ "$HC" != 000 ]; then
      warn "direct TCP 443 is blocked, but $SDM_APP_DOMAIN answers through the HTTPS proxy (HTTP $HC)"
      note "the worker also needs the proxy: add HTTPS_PROXY=... to $SDM_SYSCONFIG after the install"
      return 0
    fi
  fi
  kit_die $KIT_EXIT_PRECOND "Cannot open TCP 443 to $SDM_APP_DOMAIN." \
"The worker must reach the StrongDM control plane outbound on 443. Usual causes:
an egress security group / NACL / firewall rule, a corporate proxy that is not configured,
or DNS that does not resolve $SDM_APP_DOMAIN." \
"getent hosts $SDM_APP_DOMAIN                       # does DNS resolve?
curl -sv https://$SDM_APP_DOMAIN/ -o /dev/null     # what blocks it?
allow outbound TCP 443 to $SDM_APP_DOMAIN in your security group / firewall, or
export HTTPS_PROXY=http://proxy:port and re-run"
}

# ============================================================================
# STEP 5: existing-install analysis
#   INST_CLASS = NONE | OURS-HEALTHY | OURS-NEEDS-REPAIR | FOREIGN
# ============================================================================
inst_analyze() {
  INST_FINDINGS=(); INST_REPAIRS=(); INST_REINSTALL=(); INST_FOREIGN_UNITS=(); INST_FOREIGN_DIRS=()
  INST_FOREIGN_ENVS=(); INST_FOREIGN_PIDS=(); INST_PID_START=(); INST_INFO=()
  INST_OURS=0; INST_NEED_BINARY=0; INST_KEYS_UNKNOWN=0; INST_SIDECAR_BAD=0
  INST_PLAINTEXT_KEYS=0; INST_PREV_ENV=()
  local u user envf exec wd envs f d line pid puser role exe h sdmhome n

  # User `sdm` must have home /home/sdm (hard rule; checked before any change).
 
  if getent passwd "$SDM_USER" >/dev/null 2>&1; then

    h=$(inst_user_home "$SDM_USER")
    if [ "$h" != "$SDM_USER_HOME" ]; then
      kit_die $KIT_EXIT_PRECOND "User '$SDM_USER' exists but its home is '$h', not $SDM_USER_HOME." \
"The kit always runs the worker as $SDM_USER with SDM_HOME=$SDM_HOME_DIR and will not change that." \
"usermod -m -d $SDM_USER_HOME $SDM_USER     # moves the home directory (stop anything running as $SDM_USER first)
then re-run this kit"
    fi
  fi

  # systemd units.
  for u in "${KIT_FOREIGN_UNITS[@]}"; do
    kit_unit_exists "$u" || continue
    user=$(kit_unit_prop "$u" User); exec=$(kit_unit_prop "$u" ExecStart); wd=$(kit_unit_prop "$u" WorkingDirectory)
    envf=$(kit_unit_prop "$u" EnvironmentFiles); envs=$(printf '%s\n' "$envf" | grep -oE '/[^ ]+' | tr '\n' ' ')
    local act en; act=$(kit_unit_prop "$u" ActiveState); en=$(systemctl is-enabled "$u" 2>/dev/null </dev/null)
    if [ "$u" = "$SDM_UNIT" ] && [ "$user" = "$SDM_USER" ] && [[ $exec == *"argv[]=$SDM_BIN worker"* ]]; then
      sdmhome=$(inst_strip_quotes "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_HOME)")
      if [ "$sdmhome" = "$SDM_HOME_DIR" ] || { [ -z "$sdmhome" ] && [ "$wd" = "$SDM_HOME_DIR" ]; }; then
        INST_OURS=1; INST_OURS_ACTIVE=$act; INST_OURS_ENABLED=$en
        INST_INFO+=("unit $u: ours (User=$SDM_USER, SDM_HOME=$SDM_HOME_DIR), $act, ${en:-unknown}")
        continue
      fi
    fi
    if inst_was_replaced "unit:$u" && [ "$act" = inactive ] && [[ $en != enabled* ]]; then
      INST_INFO+=("unit $u: replaced by an earlier run (stopped, disabled; backup in $KIT_BACKUP_DIR)")
      continue
    fi
    INST_FOREIGN_UNITS+=("$u")
    INST_FINDINGS+=("unit $u: User=${user:-root}, $act/${en:-unknown}")
    INST_FINDINGS+=("    WorkingDirectory=${wd:-none}  EnvironmentFile=${envs:-none}")
    [ -n "$wd" ] && [ -d "$wd" ] && INST_FOREIGN_DIRS+=("$wd")
    for f in $envs; do
      [ -f "$f" ] || continue
      INST_FOREIGN_ENVS+=("$f")
      sdmhome=$(inst_strip_quotes "$(kit_envfile_get "$f" SDM_HOME)")
      [ -n "$sdmhome" ] && [ -d "$sdmhome" ] && INST_FOREIGN_DIRS+=("$sdmhome")
    done
  done

  # Running sdm worker/relay/gateway/proxy processes.
  while IFS='|' read -r pid puser role exe _ _; do
    [[ $pid =~ ^[1-9][0-9]*$ ]] || continue
    u=$(inst_pid_unit "$pid")
    if [ "$INST_OURS" = 1 ] && [ "$u" = "$SDM_UNIT" ] && [ "$puser" = "$SDM_USER" ]; then continue; fi
    if [ -n "$u" ] && [[ " ${INST_FOREIGN_UNITS[*]} " == *" $u "* ]]; then
      INST_FINDINGS+=("process $pid: sdm $role as $puser (unit $u, stopped with it)"); continue
    fi
    INST_PID_START[pid]=$(inst_pid_start "$pid")
    [ -n "${INST_PID_START[pid]}" ] || continue
    INST_FOREIGN_PIDS+=("$pid")
    INST_FINDINGS+=("process $pid: sdm $role as $puser, exe $exe, ${u:+unit $u}${u:-not managed by a known unit}")
  done < <(kit_find_node_procs)

  # /etc/sysconfig/sdm* env files.
  for f in /etc/sysconfig/sdm*; do
    [ -f "$f" ] || continue
    case "$f" in "$SDM_SYSCONFIG".*) continue;; esac       # kit/sdm temp files
    [[ " ${INST_FOREIGN_ENVS[*]} " == *" $f "* ]] && continue
    if [ "$f" = "$SDM_SYSCONFIG" ]; then
      sdmhome=$(inst_strip_quotes "$(kit_envfile_get "$f" SDM_HOME)")
      if [ "$INST_OURS" = 1 ] || [ "$sdmhome" = "$SDM_HOME_DIR" ]; then
        [ "$INST_OURS" = 1 ] || INST_INFO+=("$f: left over from an earlier install of ours (sdm install rewrites it)")
        continue
      fi
    fi
    if inst_was_replaced "env:$f"; then INST_INFO+=("$f: replaced by an earlier run (backup in $KIT_BACKUP_DIR)"); continue; fi
    INST_FOREIGN_ENVS+=("$f")
    INST_FINDINGS+=("env file $f: keys $(inst_env_keys "$f")(values not shown)")
    sdmhome=$(inst_strip_quotes "$(kit_envfile_get "$f" SDM_HOME)")
    [ -n "$sdmhome" ] && [ -d "$sdmhome" ] && [ "$sdmhome" != "$SDM_HOME_DIR" ] && INST_FOREIGN_DIRS+=("$sdmhome")
  done

  # Sealed sidecars in /root and /home/*.
  for d in /root/.sdm /home/*/.sdm; do
    [ -f "$d/secretenv.enc" ] || continue
    [ "$d" = "$SDM_HOME_DIR" ] && continue
    [[ " ${INST_FOREIGN_DIRS[*]} " == *" $d "* ]] && continue
    if inst_was_replaced "dir:$d"; then INST_INFO+=("$d: replaced by an earlier run (left in place, backup in $KIT_BACKUP_DIR)"); continue; fi
    INST_FOREIGN_DIRS+=("$d")
    INST_FINDINGS+=("sealed secrets $d/secretenv.enc (owner $(stat -c %U "$d/secretenv.enc" 2>/dev/null))")
  done
  # Unit discovery and the sysconfig scan can both select the same file.
  if [ ${#INST_FOREIGN_ENVS[@]} -gt 0 ]; then mapfile -t INST_FOREIGN_ENVS < <(printf '%s\n' "${INST_FOREIGN_ENVS[@]}" | awk '!s[$0]++'); fi
  if [ ${#INST_FOREIGN_DIRS[@]} -gt 0 ]; then mapfile -t INST_FOREIGN_DIRS < <(printf '%s\n' "${INST_FOREIGN_DIRS[@]}" | awk '!s[$0]++'); fi
  for d in "${INST_FOREIGN_DIRS[@]}"; do
    [[ " ${INST_FINDINGS[*]} " == *"$d/secretenv.enc"* ]] || INST_FINDINGS+=("config dir $d (will be backed up, not deleted)")
  done

  # Only these settings migrate between different installations. Existing kit
  # workers keep their complete environment when the kit updates its own keys.
  for n in DELINEA_SERVER_URL DELINEA_API_TENANT HTTPS_PROXY HTTP_PROXY NO_PROXY https_proxy http_proxy no_proxy; do
    line=$(kit_envfile_get "$SDM_SYSCONFIG" "$n") && INST_PREV_ENV+=("$n=$line")
  done

  [ "$INST_OURS" = 1 ] && inst_health
  if [ ${#INST_FOREIGN_UNITS[@]} -gt 0 ] || [ ${#INST_FOREIGN_DIRS[@]} -gt 0 ] || [ ${#INST_FOREIGN_ENVS[@]} -gt 0 ] || [ ${#INST_FOREIGN_PIDS[@]} -gt 0 ]; then
    INST_CLASS=FOREIGN
  elif [ "$INST_OURS" = 1 ]; then
    if [ ${#INST_REPAIRS[@]} -eq 0 ] && [ ${#INST_REINSTALL[@]} -eq 0 ]; then INST_CLASS=OURS-HEALTHY; else INST_CLASS=OURS-NEEDS-REPAIR; fi
  else
    INST_CLASS=NONE
  fi
}

# Health of an install that is ours. Fills INST_REPAIRS (fixable in place) and
# INST_REINSTALL (reprovision the CLI, sealed credentials and service unit).
inst_health() {
  local v fp ad ab own
  [ -x "$SDM_BIN" ] || { INST_REPAIRS+=("binary $SDM_BIN is missing"); INST_NEED_BINARY=1; }

  ad=$(inst_strip_quotes "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_APP_DOMAIN)"); ad=${ad:-app.strongdm.com}
  [ "$ad" = "$SDM_APP_DOMAIN" ] || INST_REINSTALL+=("region changes from $ad to $SDM_APP_DOMAIN")
  ab=$(inst_strip_quotes "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_BIND_ADDRESS)"); ab=${ab:-$SDM_DEFAULT_BIND}
  [ "$ab" = "$INST_BIND" ] || INST_REINSTALL+=("bind address changes from $ab to $INST_BIND")
  [ "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_LOG_OUTPUT)" = stdout ] || INST_REPAIRS+=("SDM_LOG_OUTPUT=stdout missing from $SDM_SYSCONFIG")

  # Keys: sealed (names only) or plaintext fallback.
  if [ -x "$SDM_BIN" ] && ! inst_sealed_keys; then
    INST_SIDECAR_BAD=1
    INST_REINSTALL+=("sealed secrets file cannot be read (host cloned or machine-id changed?) - it will be set aside, not deleted")
  fi
  local sealed=0 plain=0
  inst_sealed_has SDM_PROXY_CLUSTER_ACCESS_KEY && inst_sealed_has SDM_PROXY_CLUSTER_SECRET_KEY && sealed=1
  kit_envfile_has "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_ACCESS_KEY && kit_envfile_has "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_SECRET_KEY && plain=1
  if [ $sealed = 0 ] && [ $plain = 0 ] && [ "$INST_SIDECAR_BAD" = 0 ]; then
    if [ -x "$SDM_BIN" ] || [ ! -f "$SDM_SIDECAR" ]; then INST_REINSTALL+=("no proxy cluster keys found (sealed or in $SDM_SYSCONFIG)"); fi
  fi
  if kit_envfile_has "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_ACCESS_KEY || kit_envfile_has "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_SECRET_KEY; then
    INST_PLAINTEXT_KEYS=1
    if [ $sealed = 1 ]; then INST_REPAIRS+=("plaintext keys left in $SDM_SYSCONFIG although they are sealed (will be removed)")
    else
      v=$(kit_envfile_get "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_ACCESS_KEY); fp=$(kit_envfile_get "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_SECRET_KEY)
      if [ "$v" != "$SDM_PROXY_CLUSTER_ACCESS_KEY" ] || [ "$fp" != "$SDM_PROXY_CLUSTER_SECRET_KEY" ]; then INST_REINSTALL+=("the keys you entered differ from the installed ones"); fi
      v=""; fp=""
    fi
  fi
  if [ $sealed = 1 ]; then
    fp=$(inst_state_get KEY_FP)
    if [ -z "$fp" ]; then INST_KEYS_UNKNOWN=1
    elif [ "$fp" != "$(inst_key_fp)" ]; then INST_REINSTALL+=("the keys you entered differ from the installed ones")
    fi
  fi

  # Ownership / permissions.
  for v in "$SDM_HOME_DIR" "$SDM_HOME_DIR/state.kv" "$SDM_SIDECAR"; do
    [ -e "$v" ] || continue
    own=$(stat -c %U "$v" 2>/dev/null)
    [ "$own" = "$SDM_USER" ] || INST_REPAIRS+=("$v is owned by $own, not $SDM_USER")
  done
  [ -d "$SDM_HOME_DIR" ] || INST_REPAIRS+=("$SDM_HOME_DIR is missing")
  [ -f "$SDM_HOME_DIR/state.kv" ] || [ ${#INST_REINSTALL[@]} -gt 0 ] || INST_REINSTALL+=("$SDM_HOME_DIR/state.kv is missing")

  [ "${INST_OURS_ENABLED:-}" = enabled ] || INST_REPAIRS+=("unit $SDM_UNIT is not enabled at boot")
  [ "${INST_OURS_ACTIVE:-}" = active ] || INST_REPAIRS+=("unit $SDM_UNIT is not running (${INST_OURS_ACTIVE:-unknown})")
  case "${INST_PENDING:-}" in
    provision) INST_REINSTALL+=("an earlier provisioning attempt was interrupted");;
    activate) INST_REPAIRS+=("worker settings from an earlier attempt still need activation");;
  esac
  # Port in use by something else is diagnosed at start (step 11).
  return 0
}

inst_report_and_decide() {
  kit_step 5 $INST_TOTAL "Look for existing StrongDM installs"
  inst_analyze
  local i
  for i in "${INST_INFO[@]}"; do info "$i"; done
  case "$INST_CLASS" in
    NONE) ok "no existing StrongDM worker, relay or gateway found: fresh install";;
    OURS-HEALTHY) ok "existing install is ours and healthy";;
    OURS-NEEDS-REPAIR) warn "existing install is ours but needs attention:"
      for i in "${INST_REPAIRS[@]}"; do note "repair: $i"; done
      for i in "${INST_REINSTALL[@]}"; do note "re-install: $i"; done;;
    FOREIGN) warn "found a StrongDM install that this kit did not create:"
      for i in "${INST_FINDINGS[@]}"; do note "$i"; done
      if [ "$INST_OURS" = 1 ]; then
        for i in "${INST_REPAIRS[@]}"; do note "repair (ours): $i"; done
        for i in "${INST_REINSTALL[@]}"; do note "re-install (ours): $i"; done
      fi;;
  esac

  # Port check (before changing anything) when nothing sdm-like will free it.
  local port; port=$(inst_bind_port "$INST_BIND")
  if kit_have ss && [ -n "$(ss -ltnH "sport = :$port" 2>/dev/null)" ] && [ -z "$(kit_find_node_procs)" ]; then
    kit_die $KIT_EXIT_PRECOND "Port $port is already in use by another program." \
      "The worker listens on $INST_BIND and would fail to start." \
"ss -ltnp 'sport = :$port'          # see who owns it
stop that program, or choose another port: export SDM_BIND_ADDRESS=:8444"
  fi

  # Decide what to do.
  INST_DO_INSTALL=0
  if [ "$INST_CLASS" = FOREIGN ]; then
    printf '\n'
    if [ "${#INST_FOREIGN_PIDS[@]}" -gt 0 ]; then
      kit_die "$KIT_EXIT_PRECOND" "A StrongDM process has no known restartable unit." \
        "The kit cannot restore processes ${INST_FOREIGN_PIDS[*]} after an unsuccessful replacement." \
        "Use the original service manager or launch mechanism to stop those processes, then re-run."
    fi
    note "REPLACE will back up the listed files with encryption and stop ${INST_FOREIGN_UNITS[*]:-no units}."
    note "The kit restores previously running units if the replacement fails."
    if kit_noninteractive && [ "${KIT_REPLACE:-}" != yes ]; then
      kit_die $KIT_EXIT_USAGE "A foreign StrongDM install is present." "Non-interactive runs only replace it when told to." "export KIT_REPLACE=yes and re-run (review the findings above first)"
    fi
    kit_confirm_typed REPLACE "Replace the install(s) listed above?" || inst_abort
    ok "operator confirmed REPLACE"
  fi
  if [ "$INST_OURS" != 1 ]; then INST_DO_INSTALL=1; return 0; fi

  if [ ${#INST_REINSTALL[@]} -gt 0 ]; then
    warn "a re-install is needed. The worker will restart and active sessions will drop."
    kit_confirm "Re-install the worker now?" y || inst_abort
    INST_DO_INSTALL=1; return 0
  fi
  if [ "$INST_KEYS_UNKNOWN" = 1 ]; then
    warn "the installed keys are sealed and cannot be read back, so the kit cannot tell whether you entered the same keys."
    note "If you rotated the keys, choose re-install (or KIT_FORCE_REINSTALL=yes). Otherwise the install is kept as is."
  fi
  if [ "${KIT_FORCE_REINSTALL:-}" = yes ]; then
    warn "KIT_FORCE_REINSTALL=yes: re-installing. This restarts the worker and drops active sessions."
    INST_DO_INSTALL=1; return 0
  fi
  if ! kit_noninteractive; then
    note "Re-installing is never needed for repairs; it restarts the worker and drops active sessions."
    if kit_confirm "Re-install anyway?" n; then INST_DO_INSTALL=1; warn "re-install chosen by the operator"; return 0; fi
  fi
  info "keeping the existing install; only repairs will be made"
}

# Back up the selected configuration before changing any services.
inst_backup_certificate() {
  kit_ask KIT_BACKUP_CERT "Path to the backup recipient PEM certificate"
  kit_trusted_file "$KIT_BACKUP_CERT" || inst_failed "Use a root-protected backup certificate."
  kit_ensure_cmds openssl
}
inst_encrypt_backup() {
  local out=$1
  [ ! -e "$out" ] && openssl cms -encrypt -binary -aes256 -stream -outform DER -in "$stage/plain" -out "$out" "$KIT_BACKUP_CERT" &&
    openssl cms -cmsout -inform DER -in "$out" -out /dev/null &&
    (cd "$dest" && sha256sum "${out#"$dest"/}" >> SHA256SUMS) && rm -f "$stage/plain"
}
inst_backup_foreign() {
  local dest u f d safe stage source_hash copy_hash
  local envfiles=("${INST_FOREIGN_ENVS[@]}")
  if [ "$INST_OURS" != 1 ] && [ -f "$SDM_SYSCONFIG" ] &&
      [[ " ${envfiles[*]} " != *" $SDM_SYSCONFIG "* ]]; then envfiles+=("$SDM_SYSCONFIG"); fi
  if (( ${#INST_FOREIGN_DIRS[@]} + ${#INST_FOREIGN_UNITS[@]} + ${#INST_FOREIGN_ENVS[@]} > 0 )); then inst_backup_certificate; fi
  if [ "${#INST_FOREIGN_DIRS[@]}" -gt 0 ] || [ -d "$SDM_HOME_DIR" ]; then kit_ensure_cmds tar; fi
  mkdir -p /var/backups && kit_private_dir "$KIT_BACKUP_DIR" && kit_private_dir "$KIT_DIR" || inst_failed "Unsafe backup or administrative directory."
  dest=$(mktemp -d "$KIT_BACKUP_DIR/$(date +%Y%m%d-%H%M%S).XXXXXX") || inst_failed "Cannot create backup."
  (umask 077; mkdir "$dest/units" "$dest/env" "$dest/dirs") || inst_failed "Cannot create backup directories."
  inst_backup_failed() { [ -z "${stage:-}" ] || rm -rf -- "$stage"; inst_failed "Backup incomplete in $dest. No replacement has started."; }
  [ "$(stat -f -c %T /dev/shm)" = tmpfs ] || inst_failed "Encrypted backups require tmpfs scratch space in /dev/shm."
  stage=$(mktemp -d /dev/shm/sdm-backup.XXXXXX) || inst_backup_failed
  local cleanup; printf -v cleanup 'rm -rf -- %q' "$stage"; kit_on_exit "$cleanup"
  for u in "${INST_FOREIGN_UNITS[@]}"; do
    systemctl cat "$u" </dev/null > "$stage/plain" && [ -s "$stage/plain" ] && inst_encrypt_backup "$dest/units/$u.service.cms" || inst_backup_failed
  done
  for f in "${envfiles[@]}"; do
    safe=${f#/}; safe=${safe//\//_}
    [ -f "$f" ] && [ ! -L "$f" ] && cp -- "$f" "$stage/plain" &&
      source_hash=$(sha256sum < "$f") && copy_hash=$(sha256sum < "$stage/plain") && [ "$source_hash" = "$copy_hash" ] &&
      inst_encrypt_backup "$dest/env/$safe.cms" || inst_backup_failed
  done
  for d in "${INST_FOREIGN_DIRS[@]}"; do
    case "$d" in /root/.sdm|/home/*/.sdm|/sdm|/var/lib/strongdm|/opt/strongdm/*) ;; *) inst_backup_failed;; esac
    [ "$(readlink -f -- "$d")" = "$d" ] && [ -d "$d" ] || inst_backup_failed
    safe=${d#/}; safe=${safe//\//_}
    (cd -P -- "$d" && [ "$PWD" = "$d" ] && tar -cf "$stage/plain" . && tar -df "$stage/plain") &&
      inst_encrypt_backup "$dest/dirs/$safe.tar.cms" || inst_backup_failed
  done
  if [ "$INST_OURS" != 1 ] && [ -d "$SDM_HOME_DIR" ] &&
      [[ " ${INST_FOREIGN_DIRS[*]} " != *" $SDM_HOME_DIR "* ]]; then
    safe=${SDM_HOME_DIR#/}; safe=${safe//\//_}
    (cd -P -- "$SDM_HOME_DIR" && [ "$PWD" = "$SDM_HOME_DIR" ] && tar -cf "$stage/plain" . && tar -df "$stage/plain") &&
      inst_encrypt_backup "$dest/dirs/$safe.tar.cms" || inst_backup_failed
  fi
  if [ "$INST_OURS" != 1 ] && [ -f "$SDM_BIN" ] && [ ! -L "$SDM_BIN" ]; then
    (cd -P -- "$(dirname -- "$SDM_BIN")" && [ "$PWD" = "$(dirname -- "$SDM_BIN")" ] &&
      [ ! -L "${SDM_BIN##*/}" ] && cp -P -- "${SDM_BIN##*/}" "$stage/plain" && [ ! -L "$stage/plain" ]) &&
      inst_encrypt_backup "$dest/worker-binary.cms" || inst_backup_failed
  fi
  printf '%s\n' 'Sensitive worker backup. Restrict access to the backup administrator.' > "$dest/README.txt" || inst_backup_failed
  if [ -e "$dest/SHA256SUMS" ]; then (cd "$dest" && sha256sum -c SHA256SUMS >/dev/null) || inst_backup_failed; fi
  : > "$dest/COMPLETE" || inst_backup_failed
  rm -rf -- "$stage"
  INST_BACKUP_PATH=$dest
  ok "encrypted backup verified in $dest"
}

# Paths on which provisioning can overwrite a foreign service's installation.
# Move the originals into root-only directories on their own filesystems.
# The journal uses no secret values and can be replayed after an interrupted run.
inst_replacement_paths() {
  printf '%s|%s\n' "$SDM_PREFIX" /opt "$SDM_HOME_DIR" /home \
    "$SDM_SYSCONFIG" /etc/sysconfig "$INST_STATE_FILE" "$KIT_DIR" \
    "${INST_PENDING_FILE:-$KIT_DIR/activation.pending}" "$KIT_DIR" "$INST_REPLACED_LIST" "$KIT_DIR"
  if kit_has_systemd; then
    printf '%s|%s\n' "/etc/systemd/system/$SDM_UNIT.service" /etc/systemd/system \
      "/etc/systemd/system/$SDM_UNIT.service.d" /etc/systemd/system
  fi
}

inst_replacement_move() (
  local path=$1 vault=$2 operation=$3 parent leaf
  parent=${path%/*}; leaf=${path##*/}
  cd -P -- "$parent" && [ "$PWD" = "$parent" ] || return 1
  case "$operation" in
    save)
      [ "$(stat -c %d .)" = "$(stat -c %d "$vault")" ] && mv -T -- "$leaf" "$vault/original"
      ;;
    copy)
      cp -aT -- "$vault/original" "$vault/working" && mv -fT -- "$vault/working" "$leaf"
      ;;
    restore)
      rm -rf -- "$leaf" && mv -T -- "$vault/original" "$leaf"
      ;;
    remove)
      rm -rf -- "$leaf"
      ;;
  esac
)

# Record the actual enablement links, including custom and runtime links,
# so rollback does not need to infer them from a unit's [Install] section.
inst_replacement_links() {
  local journal=$1 link target unit _state dir
  local names=() dirs=()
  while IFS='|' read -r unit _state; do names+=("$unit.service"); done < "$journal/units"
  for dir in /etc/systemd/system /run/systemd/system; do [ ! -d "$dir" ] || dirs+=("$dir"); done
  [ "${#dirs[@]}" -gt 0 ] || return 0
  find "${dirs[@]}" -type l -printf '%p\0%l\0' > "$journal/linkscan" || return 1
  while IFS= read -rd '' link && IFS= read -rd '' target; do
    # The worker fragment itself is saved with the other overwritten paths.
    [ "$link" != "/etc/systemd/system/$SDM_UNIT.service" ] || continue
    case "${link%/*}" in
      /etc/systemd/system|/run/systemd/system)
        if [[ " ${names[*]} " == *" ${link##*/} "* ]]; then
          printf '%s\0%s\0' "$link" "$target"
          continue
        fi
        ;;
    esac
    if [[ " ${names[*]} " == *" ${target##*/} "* ]]; then
      printf '%s\0%s\0' "$link" "$target"
    fi
  done < "$journal/linkscan"
}

inst_replacement_cleanup() {
  local journal=$1 _path vault _present
  if [ -f "$journal/paths" ]; then
    while IFS='|' read -r _path vault _present; do
      if [ -e "$vault" ] || [ -L "$vault" ]; then
        kit_private_dir "$vault" && rm -rf -- "$vault" || return 1
      fi
    done < "$journal/paths"
  fi
  rm -rf -- "$journal"
}

inst_replacement_recover() {
  local journal="$KIT_DIR/replacement" path vault present u state link target failed=0
  [ -e "$journal" ] || return 0
  kit_private_dir "$journal" || return 1
  if [ ! -f "$journal/pending" ] || [ -f "$journal/committed" ] || [ -f "$journal/restored" ]; then
    inst_replacement_cleanup "$journal" || return 1
    return 0
  fi
  warn "Restoring the previous StrongDM installation after an unsuccessful replacement."
  if [ -f "$journal/switched" ]; then
    if kit_unit_exists "$SDM_UNIT"; then systemctl stop "$SDM_UNIT" </dev/null >/dev/null 2>&1 || return 1; fi
    while IFS='|' read -r path vault present; do
      kit_private_dir "$vault" || { failed=1; continue; }
      if [ -e "$vault/original" ] || [ -L "$vault/original" ]; then
        inst_replacement_move "$path" "$vault" restore || failed=1
      elif [ "$present" = no ] && { [ -e "$path" ] || [ -L "$path" ]; }; then
        inst_replacement_move "$path" "$vault" remove || failed=1
      fi
    done < "$journal/paths"
    [ "$failed" = 0 ] || return 1
    inst_replacement_links "$journal" > "$journal/current-links" || return 1
    while IFS= read -rd '' link && IFS= read -rd '' target; do
      kit_trusted_dir "${link%/*}" && rm -f -- "$link" || failed=1
    done < "$journal/current-links"
    while IFS= read -rd '' link && IFS= read -rd '' target; do
      mkdir -p -- "${link%/*}" && kit_trusted_dir "${link%/*}" && ln -s -- "$target" "$link" || failed=1
    done < "$journal/links"
    [ "$failed" = 0 ] || return 1
    if kit_has_systemd; then systemctl daemon-reload </dev/null || return 1; fi
  fi
  while IFS='|' read -r u state; do
    if [ "$state" = active ]; then
      systemctl reset-failed "$u" </dev/null >/dev/null 2>&1 || true
      systemctl start "$u" </dev/null >/dev/null 2>&1 && systemctl is-active --quiet "$u" </dev/null || failed=1
    elif [ "$(kit_unit_prop "$u" ActiveState)" != inactive ]; then
      systemctl stop "$u" </dev/null >/dev/null 2>&1 || failed=1
    fi
  done < "$journal/units"
  [ "$failed" = 0 ] || return 1
  sync && : > "$journal/restored" && sync || return 1
  inst_replacement_cleanup "$journal" || return 1
  ok "Previous StrongDM installation restored."
}

inst_replacement_exit() {
  inst_replacement_recover || fail "Replacement recovery is incomplete. The rollback journal remains in $KIT_DIR/replacement. Re-run the installer to retry recovery."
}

inst_replacement_worker_processes() {
  local uid status field real effective saved filesystem
  uid=$(id -u "$SDM_USER" 2>/dev/null) || return 1
  [ -r /proc/1/status ] || return 0
  for status in /proc/[0-9]*/status; do
    while read -r field real effective saved filesystem; do
      [ "$field" = Uid: ] || continue
      if [[ $uid = "$real" || $uid = "$effective" || $uid = "$saved" || $uid = "$filesystem" ]]; then
        return 0
      fi
      break
    done 2>/dev/null < "$status" || { [ ! -e "$status" ] || return 0; }
  done
  return 1
}

inst_replacement_probe_sealing() {
  [ "${INST_DO_INSTALL:-0}" = 1 ] && [ "$INST_OURS" != 1 ] && [ -n "${INST_NEW_BIN:-}" ] || return 0
  if inst_replacement_worker_processes; then
    info "Credential sealing will be checked after the original service account stops."
    return 0
  fi
  local scratch cleanup
  scratch=$(mktemp -d /dev/shm/sdm-sealing.XXXXXX) || inst_failed "Cannot stage a credential sealing check."
  printf -v cleanup 'rm -rf -- %q' "$scratch"; kit_on_exit "$cleanup"
  local SDM_BIN=/proc/self/fd/8 SDM_USER_HOME="$scratch/home" SDM_HOME_DIR="$scratch/home" SDM_SIDECAR="$scratch/home/secretenv.enc"
  local INST_SEALED_KEYS INST_SEALED_ERR
  chmod 0711 "$scratch" && install -d -m 0700 -o "$SDM_USER" "$SDM_HOME_DIR" ||
    inst_failed "Cannot prepare the isolated sealing check."
  inst_seal_pair 8<"$INST_NEW_BIN"
  if [ "${INST_DELINEA:-no}" = yes ] && [ -n "${DELINEA_USERNAME:-}" ] && [ -n "${DELINEA_PASSWORD:-}" ]; then
    printf '%s\n%s\n' "$DELINEA_USERNAME" "$DELINEA_PASSWORD" |
      kit_as_worker "$SDM_HOME_DIR" "$SDM_BIN" nodesecrets set DELINEA_USERNAME DELINEA_PASSWORD 8<"$INST_NEW_BIN" >/dev/null 2>&1 &&
      inst_sealed_keys 8<"$INST_NEW_BIN" && inst_sealed_has DELINEA_USERNAME && inst_sealed_has DELINEA_PASSWORD ||
      inst_failed "The replacement CLI could not seal and verify the Delinea credentials."
  fi
  rm -rf -- "$scratch"
  ok "verified that the replacement CLI can seal credentials before stopping services"
}

inst_replace_foreign() {
  [ "$INST_CLASS" = FOREIGN ] || return 0
  [ "${#INST_FOREIGN_PIDS[@]}" = 0 ] || inst_failed "Stop the unmanaged StrongDM processes using their original launch mechanism."
  if [ "$INST_OURS" != 1 ] && [ "${INST_KEEP_DELINEA:-0}" = 1 ]; then
    inst_failed "Supply the Delinea credentials with KIT_ROTATE_DELINEA=yes to seal them for the replacement worker."
  fi
  local journal="$KIT_DIR/replacement" u state path anchor vault present p link target
  [ ! -L "$SDM_PREFIX" ] && [ ! -L "$SDM_PREFIX/bin" ] ||
    inst_failed "The worker prefix and binary directory must be physical paths for safe replacement."
  kit_section "Backing up the foreign installation"
  inst_backup_foreign
  inst_replacement_probe_sealing
  kit_private_dir "$journal" || inst_failed "Cannot create the replacement journal."
  kit_on_exit inst_replacement_exit
  (umask 077; : > "$journal/units"; : > "$journal/paths") || inst_failed "Cannot initialize the replacement journal."
  local units=("${INST_FOREIGN_UNITS[@]}")
  if [ "$INST_OURS" = 1 ]; then units+=("$SDM_UNIT"); fi
  for u in "${units[@]}"; do
    state=$(kit_unit_prop "$u" ActiveState)
    case "$state" in active|inactive) ;; *) inst_failed "Wait for $u to settle before replacing it (state: ${state:-unknown}).";; esac
    [ "$(kit_unit_prop "$u" Id)" = "$u.service" ] || inst_failed "Resolve the systemd unit alias $u before replacement."
    if [ "$state" = active ]; then
      case "$(kit_unit_prop "$u" KillMode)" in control-group|mixed) ;; *) inst_failed "Cannot safely stop all processes in $u."; esac
    fi
    printf '%s|%s\n' "$u" "$state" >> "$journal/units" || inst_failed "Cannot record the state of $u."
  done
  if [ "$INST_OURS" != 1 ]; then
    for p in $(kit_unit_prop "$SDM_UNIT" DropInPaths); do
      case "$p" in
        "/etc/systemd/system/$SDM_UNIT.service.d/"*|*/systemd/system/service.d/*) ;;
        *) inst_failed "Review the inherited worker unit override at $p before replacement.";;
      esac
    done
    [ ! -e "/run/systemd/system/$SDM_UNIT.service" ] && [ ! -L "/run/systemd/system/$SDM_UNIT.service" ] ||
      inst_failed "Remove the runtime worker unit override before replacement."
  fi
  inst_replacement_links "$journal" > "$journal/links" || inst_failed "Cannot record unit enablement."
  while IFS='|' read -r path anchor; do
    kit_trusted_dir "$anchor" || inst_failed "Unsafe parent for replacement path $path."
    vault=$(mktemp -d "$anchor/.sdm-kit-replacement.XXXXXX") || inst_failed "Cannot protect the original at $path."
    present=no
    if [ -e "$path" ] || [ -L "$path" ]; then present=yes; fi
    printf '%s|%s|%s\n' "$path" "$vault" "$present" >> "$journal/paths" || inst_failed "Cannot record the original at $path."
    if [ "$present" = yes ]; then
      [ "$(stat -c %d -- "${path%/*}")" = "$(stat -c %d -- "$vault")" ] ||
        inst_failed "The replacement path $path must be on its parent's filesystem."
      if kit_have mountpoint && mountpoint -q -- "$path"; then inst_failed "Cannot preserve the mount point $path during replacement."; fi
    fi
  done < <(inst_replacement_paths)
  : > "$journal/pending" && sync || inst_failed "Cannot prepare rollback."
  for u in "${units[@]}"; do
    systemctl stop "$u" </dev/null >/dev/null 2>&1 || inst_failed "Cannot stop $u."
    [ "$(kit_unit_prop "$u" ActiveState)" = inactive ] || inst_failed "$u remained active after stopping it."
  done
  if [ -n "$(kit_find_node_procs)" ]; then
    inst_failed "A StrongDM process is still running. Use its original launch mechanism to stop it."
  fi
  if [ "$INST_OURS" != 1 ] && inst_replacement_worker_processes; then
    inst_failed "Other processes still run as $SDM_USER. Stop them with their original launch mechanism before sealing credentials."
  fi
  : > "$journal/switched" && sync || inst_failed "Cannot record the replacement switch."
  if [ "$INST_OURS" != 1 ]; then
    while IFS= read -rd '' link && IFS= read -rd '' target; do
      [ "${target##*/}" = "$SDM_UNIT.service" ] || continue
      kit_trusted_dir "${link%/*}" && rm -f -- "$link" || inst_failed "Cannot remove previous worker enablement."
    done < "$journal/links"
  fi
  while IFS='|' read -r path vault present; do
    [ "$present" = yes ] || continue
    inst_replacement_move "$path" "$vault" save || inst_failed "Cannot preserve the original at $path."
    if [ "$INST_OURS" = 1 ] || [ "$path" = "$SDM_PREFIX" ] || [ "$path" = "$INST_REPLACED_LIST" ]; then
      inst_replacement_move "$path" "$vault" copy || inst_failed "Cannot stage the existing files at $path."
    fi
  done < "$journal/paths"
}

inst_replacement_validate_worker() {
  [ -f "$KIT_DIR/replacement/pending" ] && [ "$INST_OURS" != 1 ] || return 0
  local command extended
  systemctl daemon-reload </dev/null || inst_failed "Cannot load the replacement worker definition."
  command=$(kit_unit_prop "$SDM_UNIT" ExecStart)
  extended=$(kit_unit_prop "$SDM_UNIT" ExecStartEx)
  [ "$(kit_unit_prop "$SDM_UNIT" User)" = "$SDM_USER" ] &&
    [[ $command == "{ path=$SDM_BIN ; argv[]=$SDM_BIN worker ; "* && $command != *"} {"* ]] &&
    [[ -z $extended || $extended == *"flags= ;"* ]] ||
    inst_failed "The effective worker definition does not run the verified binary as $SDM_USER."
}

inst_replacement_commit() {
  local journal="$KIT_DIR/replacement" u f d list
  [ -f "$journal/pending" ] || return 0
  list="$journal/new-replaced.list"
  (umask 077; : > "$list") || inst_failed "Cannot stage replacement history."
  if [ -f "$INST_REPLACED_LIST" ]; then cat "$INST_REPLACED_LIST" > "$list" || inst_failed "Cannot copy replacement history."; fi
  for u in "${INST_FOREIGN_UNITS[@]}"; do
    [ "$u" = "$SDM_UNIT" ] && continue
    [ "$(kit_unit_prop "$u" ActiveState)" = inactive ] || inst_failed "$u returned to service during replacement."
    systemctl disable "$u" </dev/null >/dev/null 2>&1 || inst_failed "Cannot disable $u."
    if [ "$(systemctl is-enabled "$u" 2>/dev/null </dev/null)" = enabled-runtime ]; then
      systemctl disable --runtime "$u" </dev/null >/dev/null 2>&1 || inst_failed "Cannot disable runtime enablement for $u."
    fi
    printf 'unit:%s\n' "$u" >> "$list" || inst_failed "Cannot record replacement of $u."
  done
  for f in "${INST_FOREIGN_ENVS[@]}"; do
    [ "$f" = "$SDM_SYSCONFIG" ] || printf 'env:%s\n' "$f" >> "$list" || inst_failed "Cannot record the replacement."
  done
  for d in "${INST_FOREIGN_DIRS[@]}"; do printf 'dir:%s\n' "$d" >> "$list" || inst_failed "Cannot record the replacement."; done
  mv -fT -- "$list" "$INST_REPLACED_LIST" && sync && : > "$journal/committed" && sync ||
    inst_failed "Cannot finalize the replacement."
  inst_replacement_cleanup "$journal" || warn "Committed replacement. Cleanup will retry on the next install."
}

# ============================================================================
# STEP 6: service user + SDM_HOME
# ============================================================================
inst_ensure_user() {
  local nl h grp=()
  if getent passwd "$SDM_USER" >/dev/null 2>&1; then
    h=$(inst_user_home "$SDM_USER")
    [ "$h" = "$SDM_USER_HOME" ] || kit_die $KIT_EXIT_PRECOND "User '$SDM_USER' exists but its home is '$h', not $SDM_USER_HOME." \
      "The kit always runs the worker as $SDM_USER with SDM_HOME=$SDM_HOME_DIR." "usermod -m -d $SDM_USER_HOME $SDM_USER
then re-run this kit"
    ok "user $SDM_USER exists (home $SDM_USER_HOME)"
  else
    [ ! -e "$SDM_USER_HOME" ] && [ ! -L "$SDM_USER_HOME" ] || inst_failed "Review the existing service home before creating the account."
    nl=$(inst_nologin)
    getent group "$SDM_USER" >/dev/null 2>&1 && grp=(-g "$SDM_USER")
    useradd -m -d "$SDM_USER_HOME" -s "$nl" -c "StrongDM proxy cluster worker" "${grp[@]}" "$SDM_USER" </dev/null \
      || kit_die $KIT_EXIT_FAIL "Could not create user $SDM_USER." "useradd failed (see above)." \
           "useradd -m -d $SDM_USER_HOME -s $nl -c 'StrongDM proxy cluster worker' $SDM_USER"
    if kit_have passwd; then passwd -l "$SDM_USER" >/dev/null 2>&1; else usermod -L "$SDM_USER" >/dev/null 2>&1; fi
    ok "created user $SDM_USER (home $SDM_USER_HOME, shell $nl, password locked)"
  fi
  [ ! -L "$SDM_USER_HOME" ] && [ -d "$SDM_USER_HOME" ] && [ "$(id -u "$SDM_USER")" != 0 ] || kit_die 3 "Unsafe service account or home directory." "" "Review $SDM_USER_HOME and the sdm account."
  [ "${1:-}" = account-only ] || inst_prepare_worker_home
}

inst_prepare_worker_home() {
  kit_as_worker "$SDM_HOME_DIR" mkdir -p -m 0700 "$SDM_HOME_DIR" && kit_as_worker "$SDM_HOME_DIR" chmod 0700 "$SDM_HOME_DIR" ||
    kit_die 3 "Worker cannot manage its state directory." "" "Inspect $SDM_HOME_DIR and its ownership offline."
  ok "$SDM_HOME_DIR is 0700 $SDM_USER:$(id -gn "$SDM_USER" 2>/dev/null)"
}

# ============================================================================
# STEP 7: binary (release JSON -> zip -> sha256 -> unzip -> --version)
# ============================================================================
# inst_fetch_release DOMAIN -> sets INST_REL_URL INST_REL_VERSION INST_REL_SHA; returns 1 on failure (INST_REL_ERR).
inst_fetch_release() {
  local jurl=$1 flat
  INST_REL_URL=""; INST_REL_VERSION=""; INST_REL_SHA=""; INST_REL_ERR=""
  [[ $jurl == https://* ]] || { INST_REL_ERR="release metadata requires HTTPS"; return 1; }
  kit_http GET "$jurl"
  if [ "$HE" != 0 ]; then INST_REL_ERR="curl exit $HE: $(printf '%s' "$HB" | head -1)"; return 1; fi
  [ "$HC" = 200 ] || { INST_REL_ERR="HTTP $HC"; return 1; }
  flat=$(printf '%s' "$HB" | json_flat)
  INST_REL_URL=$(jget "$flat" url); INST_REL_VERSION=$(jget "$flat" version); INST_REL_SHA=$(jget "$flat" sha256)
  INST_REL_SHA=$(printf '%s' "$INST_REL_SHA" | tr '[:upper:]' '[:lower:]')
  [ -n "$INST_REL_URL" ] || { INST_REL_ERR="no url in the release JSON"; return 1; }
  [[ $INST_REL_SHA =~ ^[0-9a-f]{64}$ ]] || { INST_REL_ERR="no valid sha256 in the release JSON"; return 1; }
  if [[ $INST_REL_URL != https://* || $INST_REL_URL == *[[:cntrl:]]* ]]; then INST_REL_ERR="release URL is not https"; return 1; fi
  return 0
}

inst_installed_version() { [ -x "$SDM_BIN" ] && kit_as_worker "$SDM_HOME_DIR" "$SDM_BIN" --version 2>/dev/null </dev/null | awk '$1=="sdm" && $2=="version" && $3~/^[0-9][0-9A-Za-z._+-]*$/{print $3; exit}'; }

# inst_download_verify -> sets INST_NEW_BIN (unzipped sdm in a root-only temp dir).
inst_download_verify() {
  local zip got out rc
  kit_private_dir "$KIT_DIR" && kit_private_dir "$KIT_DIR/tmp" \
    || kit_die $KIT_EXIT_FAIL "Cannot create $KIT_DIR/tmp." "" "mkdir -p $KIT_DIR/tmp; df -h $SDM_PREFIX"
  if [ -z "${INST_TMP:-}" ]; then
    INST_TMP=$(mktemp -d "$KIT_DIR/tmp/install.XXXXXX") || kit_die $KIT_EXIT_FAIL "mktemp failed in $KIT_DIR/tmp." "" "df -h $SDM_PREFIX"
    local q; printf -v q 'rm -rf -- %q' "$INST_TMP"; kit_on_exit "$q"
  fi
  zip="$INST_TMP/sdm.zip"
  info "downloading sdm $INST_REL_VERSION"
  curl -q -fsSL --proto "=https" --proto-redir "=https" --globoff --max-time 900 -o "$zip" --url "$INST_REL_URL" </dev/null 2>"$INST_TMP/curl.err"; rc=$?
  if [ $rc -ne 0 ]; then INST_DL_ERR="curl exit $rc: $(head -1 "$INST_TMP/curl.err")"; return 1; fi
  got=$(sha256sum "$zip" | awk '{print $1}')
  if [ "$got" != "$INST_REL_SHA" ]; then
    kit_die $KIT_EXIT_FAIL "Checksum mismatch for the downloaded sdm zip." \
"expected sha256 $INST_REL_SHA
got      sha256 $got
The download was corrupted or altered in transit (often a TLS-inspecting proxy serving an error page)." \
"curl -sI '$INST_REL_URL'          # check what is being served
re-run the kit; if it repeats, allow downloads.strongdm.com through your proxy without rewriting"
  fi
  ok "sha256 verified ($got)"
  [ "$(unzip -Z1 "$zip" | grep -cx sdm)" = 1 ] || inst_failed "The verified archive must contain one sdm executable."
  rm -rf "$INST_TMP/x"; mkdir -p "$INST_TMP/x"
  unzip -p "$zip" sdm > "$INST_TMP/x/sdm" </dev/null || kit_die $KIT_EXIT_FAIL "Could not unzip the sdm binary." "The zip passed its checksum but has no 'sdm' entry." "unzip -l $zip"
  rm -f "$zip"
  chmod 0755 "$INST_TMP/x/sdm"
  # Pass only a read-only descriptor into private staging to the unprivileged version probe.
  out=$(kit_run_unprivileged nobody env -i PATH=/usr/bin:/bin HOME=/nonexistent SDM_LOG_OUTPUT=stderr \
    timeout 20 /proc/self/fd/8 --version 8<"$INST_TMP/x/sdm" </dev/null 2>&1); rc=$?
  if [ $rc -ne 0 ]; then
    kit_die $KIT_EXIT_FAIL "The downloaded sdm binary will not run (exit $rc)." \
"$(printf '%s' "$out" | head -3)
Exit 126 usually means $SDM_PREFIX is on a noexec mount; 'Exec format error' means the wrong architecture." \
"findmnt -T $KIT_DIR/tmp -o TARGET,OPTIONS     # look for noexec
uname -m                                      # expect x86_64 or aarch64"
  fi
  [[ $out == *"$INST_REL_VERSION"* ]] || warn "binary reports '$out', expected version $INST_REL_VERSION"
  ok "binary runs: $out"
  INST_NEW_BIN="$INST_TMP/x/sdm"
}

inst_binary() {
  kit_step 6 $INST_TOTAL "StrongDM binary"
  local cur cands=() j fetched=0
  if [ "$INST_OURS" = 1 ]; then cur=$(inst_installed_version); fi
  [ -n "$cur" ] && info "installed: $SDM_BIN version $cur"
  cands=("https://$SDM_APP_DOMAIN/releases/upgrade?software=sdm-cli&os=linux&arch=$INST_ARCH")
  [ "$SDM_APP_DOMAIN" != app.strongdm.com ] && cands+=("https://app.strongdm.com/releases/upgrade?software=sdm-cli&os=linux&arch=$INST_ARCH")

  if [ "$INST_DO_INSTALL" = 0 ] && [ "$INST_NEED_BINARY" = 0 ]; then
    if inst_fetch_release "${cands[0]}" && [ -n "$INST_REL_VERSION" ]; then
      if [ "$INST_REL_VERSION" = "$cur" ]; then ok "installed version $cur is the latest; no download needed"
      else info "latest is $INST_REL_VERSION; keeping $cur (the kit does not swap the binary under a healthy worker)"; fi
    else
      info "could not look up the latest version (${INST_REL_ERR:-unknown}); keeping $cur"
    fi
    return 0
  fi

  for j in "${cands[@]}"; do
    if ! inst_fetch_release "$j"; then warn "release lookup failed at ${j%%\?*}: $INST_REL_ERR"; continue; fi
    fetched=1
    ok "latest sdm-cli for linux/$INST_ARCH: $INST_REL_VERSION"
    inst_download_verify && return 0
    warn "download failed: $INST_DL_ERR"
  done
  if [ $fetched = 0 ]; then
    kit_die $KIT_EXIT_FAIL "Could not look up the latest sdm release." "Last error: ${INST_REL_ERR:-unknown}" \
"curl -s '${cands[0]}'
check outbound HTTPS to $SDM_APP_DOMAIN (and any proxy settings), then re-run"
  fi
  kit_die $KIT_EXIT_FAIL "Could not download the sdm binary." "Last error: ${INST_DL_ERR:-unknown}" \
"curl -sSI '$INST_REL_URL'
allow outbound HTTPS to downloads.strongdm.com (or the regional downloads host), then re-run"
}

# ============================================================================
# STEP 8: sdm install (or in-place repair)
# ============================================================================
inst_failed() { kit_die $KIT_EXIT_FAIL "$1" "" "Correct the reported problem and re-run the kit."; }

# The service owns its self-updating CLI. Root never follows a path inside that tree.
inst_place_binary() {
  kit_trusted_dir /opt || inst_failed "Unsafe /opt directory."
  if [ ! -e "$SDM_PREFIX" ] && [ ! -L "$SDM_PREFIX" ]; then
    install -d -m 0755 -o "$SDM_USER" "$SDM_PREFIX" || inst_failed "Cannot create worker prefix."
  fi
  if kit_trusted_dir "$SDM_PREFIX" && { [ ! -e "$SDM_PREFIX/bin" ] || kit_trusted_dir "$SDM_PREFIX/bin"; }; then
    local tmp
    mkdir -p "$SDM_PREFIX/bin" || inst_failed "Cannot create binary directory."
    chmod 0755 "$SDM_PREFIX/bin" || inst_failed "Cannot set permissions on protected binary directory."
    tmp=$(mktemp "$SDM_PREFIX/bin/.sdm.XXXXXX") && install -m 0755 "$INST_NEW_BIN" "$tmp" &&
      mv -fT "$tmp" "$SDM_BIN" || inst_failed "Cannot install the verified binary."
  else
    kit_as_worker "$SDM_HOME_DIR" bash -c '
      set -eu
      mkdir -p -m 0755 "$1/bin"
      t=$(mktemp "$1/bin/.sdm.XXXXXX")
      trap '\''rm -f "$t"'\'' EXIT
      cat > "$t"; chmod 0755 "$t"; mv -fT "$t" "$1/bin/sdm"
    ' bash "$SDM_PREFIX" < "$INST_NEW_BIN" || inst_failed "Worker cannot update its binary."
  fi
}

inst_write_unit() {
  local unitdir=/etc/systemd/system tmp
  kit_trusted_dir "$unitdir" || inst_failed "Unsafe systemd unit directory."
  tmp=$(mktemp "$unitdir/.sdm-worker.XXXXXX") || inst_failed "Cannot stage unit."
  {
    printf '%s\n' '[Unit]' 'Description=StrongDM worker' 'After=network-online.target' 'Wants=network-online.target' '[Service]' \
      "User=$SDM_USER" "WorkingDirectory=$SDM_HOME_DIR" "ExecStart=$SDM_BIN worker" "EnvironmentFile=$SDM_SYSCONFIG" 'Restart=always' 'RestartSec=3'
    if [ "$(inst_bind_port "$INST_BIND")" -lt 1024 ]; then echo 'AmbientCapabilities=CAP_NET_BIND_SERVICE'; fi
    printf '%s\n' '[Install]' 'WantedBy=multi-user.target'
  } > "$tmp" && chmod 0644 "$tmp" && mv -fT "$tmp" "$unitdir/$SDM_UNIT.service" || inst_failed "Cannot install worker unit."
}

inst_seal_pair() {
  printf '%s\n%s\n' "$SDM_PROXY_CLUSTER_ACCESS_KEY" "$SDM_PROXY_CLUSTER_SECRET_KEY" |
    kit_as_worker "$SDM_HOME_DIR" "$SDM_BIN" nodesecrets set SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY >/dev/null 2>&1 ||
    inst_failed "Could not seal cluster credentials as the worker. Check machine identity and state-directory permissions."
  inst_sealed_keys && inst_sealed_has SDM_PROXY_CLUSTER_ACCESS_KEY && inst_sealed_has SDM_PROXY_CLUSTER_SECRET_KEY || inst_failed "Sealed cluster credentials could not be verified."
}

inst_write_environment() {
  local core managed tmp
  core=$(printf '%s\n' "SDM_HOME=$SDM_HOME_DIR" "SDM_APP_DOMAIN=$SDM_APP_DOMAIN" "SDM_BIND_ADDRESS=$INST_BIND" 'SDM_LOG_OUTPUT=stdout')
  managed='SDM_HOME SDM_APP_DOMAIN SDM_BIND_ADDRESS SDM_LOG_OUTPUT SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY'
  if [ "${INST_OURS:-0}" = 1 ] || [ "${INST_CLASS:-}" = NONE ]; then
    kit_envfile_update "$SDM_SYSCONFIG" "$managed" <<<"$core" || inst_failed "Cannot update worker environment."
  else
    tmp=$(mktemp "$SDM_SYSCONFIG.XXXXXX") || inst_failed "Cannot stage worker environment."
    if ! {
      printf '%s\n' "$core" &&
      { [ ${#INST_PREV_ENV[@]} -eq 0 ] || printf '%s\n' "${INST_PREV_ENV[@]}"; }
    } > "$tmp" || ! mv -fT "$tmp" "$SDM_SYSCONFIG"; then
      rm -f -- "$tmp"; inst_failed "Cannot install worker environment."
    fi
  fi
}

inst_run_install() {
  inst_place_binary
  if [ "${INST_SIDECAR_BAD:-0}" = 1 ]; then
    kit_as_worker "$SDM_HOME_DIR" mv -T "$SDM_SIDECAR" "$SDM_SIDECAR.unreadable-$(date +%s)" || inst_failed "Cannot preserve unreadable sidecar."
  fi
  inst_seal_pair
  kit_as_worker "$SDM_HOME_DIR" bash -c 'umask 077; touch "$1/state.kv" "$1/sdm.log"' bash "$SDM_HOME_DIR" || inst_failed "Worker state is inaccessible."
  inst_write_environment
  inst_write_unit
  inst_state_set KEY_FP "$(inst_key_fp)" || inst_failed "Cannot save installation state."
  inst_state_set APP_DOMAIN "$SDM_APP_DOMAIN" && inst_state_set BIND "$INST_BIND" || inst_failed "Cannot save worker settings."
  INST_NEED_RESTART=1
}

inst_repair() {
  local f
  if [ "$INST_NEED_BINARY" = 1 ]; then inst_mark_pending; inst_place_binary; fi
  for f in "$SDM_HOME_DIR" "$SDM_HOME_DIR/state.kv" "$SDM_SIDECAR"; do
    [ -e "$f" ] || continue
    [ "$(stat -c %U "$f")" = "$SDM_USER" ] || inst_failed "Unexpected ownership of $f. Review the file offline before repairing its ownership."
  done
  if [ "${INST_PLAINTEXT_KEYS:-0}" = 1 ] && ! { inst_sealed_has SDM_PROXY_CLUSTER_ACCESS_KEY && inst_sealed_has SDM_PROXY_CLUSTER_SECRET_KEY; }; then
    inst_mark_pending
    inst_seal_pair
  fi
  if [ "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_LOG_OUTPUT)" != stdout ]; then
    inst_mark_pending
    kit_envfile_set "$SDM_SYSCONFIG" SDM_LOG_OUTPUT stdout || inst_failed "Cannot set SDM_LOG_OUTPUT."
    ok "set SDM_LOG_OUTPUT=stdout"
  fi
  if [ -z "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_HOME)" ]; then
    inst_mark_pending
    kit_envfile_set "$SDM_SYSCONFIG" SDM_HOME "$SDM_HOME_DIR" || inst_failed "Cannot set SDM_HOME."
    ok "set SDM_HOME=$SDM_HOME_DIR"
  fi
  if [ "${INST_PLAINTEXT_KEYS:-0}" = 1 ] && inst_sealed_has SDM_PROXY_CLUSTER_ACCESS_KEY && inst_sealed_has SDM_PROXY_CLUSTER_SECRET_KEY; then
    inst_mark_pending
    kit_envfile_unset "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_ACCESS_KEY && kit_envfile_unset "$SDM_SYSCONFIG" SDM_PROXY_CLUSTER_SECRET_KEY || inst_failed "Cannot remove plaintext cluster keys."
    ok "removed plaintext proxy cluster keys from $SDM_SYSCONFIG (the sealed copies are used)"
  fi
  [ ${#INST_REPAIRS[@]} -eq 0 ] && ok "nothing to repair"
  [ -z "$(inst_state_get KEY_FP)" ] && [ "$INST_KEYS_UNKNOWN" = 0 ] && [ "${INST_PLAINTEXT_KEYS:-0}" = 1 ] && inst_state_set KEY_FP "$(inst_key_fp)"
  return 0
}

# ============================================================================
# STEP 9: env file
# ============================================================================
inst_envfile() {
  kit_step 9 $INST_TOTAL "Worker environment file $SDM_SYSCONFIG"
  local cur
  [ -f "$SDM_SYSCONFIG" ] || kit_die $KIT_EXIT_FAIL "$SDM_SYSCONFIG is missing after install." "" "re-run this kit"
  if [ -n "${DELINEA_SERVER_URL:-}" ]; then
    cur=$(kit_envfile_get "$SDM_SYSCONFIG" DELINEA_SERVER_URL)
    if [ "$cur" != "$DELINEA_SERVER_URL" ]; then
      inst_mark_pending
      kit_envfile_set "$SDM_SYSCONFIG" DELINEA_SERVER_URL "$DELINEA_SERVER_URL" || inst_failed "Cannot write Delinea URL."
    fi
    ok "DELINEA_SERVER_URL=$DELINEA_SERVER_URL"
  fi
  if [ "$(stat -c %u:%a "$SDM_SYSCONFIG")" != 0:600 ]; then
    kit_envfile_set "$SDM_SYSCONFIG" SDM_LOG_OUTPUT stdout || inst_failed "Cannot secure the worker environment."
  fi
  ok "env file keys: $(inst_env_keys "$SDM_SYSCONFIG")(values not shown)"
}

# ============================================================================
# STEP 10: seal Delinea credentials
# ============================================================================
inst_seal() {
  kit_step 10 $INST_TOTAL "Seal Delinea Secret Server credentials"
  if [ "$INST_DELINEA" != yes ]; then
    if kit_envfile_has "$SDM_SYSCONFIG" DELINEA_PASSWORD; then inst_failed "Plaintext Delinea credentials remain. Enable Delinea provisioning to seal them."; fi
    info "Delinea Secret Server not used; skipped"; return 0
  fi
  if [ "${INST_ROTATE_DELINEA:-no}" = no ] && inst_delinea_sealed; then
    ok "existing sealed Delinea credentials retained"
  else
    [ "${INST_KEEP_DELINEA:-0}" = 0 ] || inst_failed "The previously sealed Delinea pair is unavailable. Re-run with credentials to provision it."
    inst_mark_pending
    if ! printf '%s\n%s\n' "$DELINEA_USERNAME" "$DELINEA_PASSWORD" |
      kit_as_worker "$SDM_HOME_DIR" "$SDM_BIN" nodesecrets set DELINEA_USERNAME DELINEA_PASSWORD >/dev/null 2>&1; then
      inst_failed "Could not seal the supplied Delinea credentials as the service user."
    fi
    inst_delinea_sealed || inst_failed "The new Delinea pair could not be verified in sealed storage."
    ok "sealed: DELINEA_USERNAME, DELINEA_PASSWORD"
  fi
  [ "$(stat -c %U "$SDM_SIDECAR")" = "$SDM_USER" ] || inst_failed "Unexpected sealed file owner."
  if kit_envfile_has "$SDM_SYSCONFIG" DELINEA_USERNAME || kit_envfile_has "$SDM_SYSCONFIG" DELINEA_PASSWORD; then
    inst_mark_pending
    kit_envfile_update "$SDM_SYSCONFIG" "DELINEA_USERNAME DELINEA_PASSWORD" </dev/null || inst_failed "Cannot remove plaintext Delinea credentials."
    ok "removed plaintext DELINEA_USERNAME/DELINEA_PASSWORD from $SDM_SYSCONFIG"
  fi
}

# ============================================================================
# STEP 11: start and wait for the worker
# ============================================================================
inst_live_invocation() {
  local props key value state substate pid started invocation ticks
  local fields=(-p ActiveState -p SubState -p MainPID -p ExecMainStartTimestampMonotonic)
  # systemd 219 returns an error when any requested property is unknown.
  props=$(systemctl show "$SDM_UNIT" "${fields[@]}" -p InvocationID 2>/dev/null </dev/null) ||
    props=$(systemctl show "$SDM_UNIT" "${fields[@]}" 2>/dev/null </dev/null) || return 1
  while IFS='=' read -r key value; do
    case "$key" in
      ActiveState) state=$value;;
      SubState) substate=$value;;
      MainPID) pid=$value;;
      InvocationID) invocation=$value;;
      ExecMainStartTimestampMonotonic) started=$value;;
    esac
  done <<<"$props"
  [ "${state:-}" = active ] && [ "${substate:-}" = running ] && [[ ${pid:-} =~ ^[1-9][0-9]*$ ]] || return 1
  ticks=$(inst_pid_start "$pid"); [ -n "$ticks" ] || return 1
  if ! [[ ${invocation:-} =~ ^[0-9a-f]{32}$ && $invocation != 00000000000000000000000000000000 ]]; then
    invocation=""
    [[ ${started:-} =~ ^[1-9][0-9]*$ ]] || return 1
  fi
  printf '%s|%s|%s|%s\n' "$pid" "$ticks" "${started:-}" "$invocation"
}

inst_invocation_messages() {
  local pid _ started invocation
  IFS='|' read -r pid _ started invocation <<<"$1"
  local args=(-b --no-pager "_SYSTEMD_UNIT=$SDM_UNIT.service")
  if [ -n "$invocation" ]; then
    journalctl "${args[@]}" -o cat "_SYSTEMD_INVOCATION_ID=$invocation" 2>/dev/null </dev/null
  else
    # systemd 219 lacks invocation IDs. The current boot, main PID and
    # microsecond start boundary keep entries from earlier uses of the PID out.
    LC_ALL=C journalctl "${args[@]}" -o short-monotonic "_PID=$pid" 2>/dev/null </dev/null |
      LC_ALL=C awk -v started="$started" 'match($0, /^\[[[:space:]]*[0-9]+\.[0-9]+\]/) {
        stamp = substr($0, 2, RLENGTH - 2)
        sub(/^[[:space:]]+/, "", stamp)
        sub(/\./, "", stamp)
        if (stamp + 0 >= started) print
      }'
  fi
}

inst_start() {
  kit_step 11 $INST_TOTAL "Start $SDM_UNIT and wait for it to connect"
  local since="" timeout=${KIT_START_TIMEOUT:-90} t=0 st invocation ready nres nres0
  [ "$timeout" -ge 0 ] 2>/dev/null || inst_failed "KIT_START_TIMEOUT must be a nonnegative number of seconds."
  inst_read_pending
  [ "$INST_PENDING" != provision ] || inst_failed "Worker provisioning is incomplete."
  systemctl daemon-reload </dev/null || inst_failed "Cannot reload systemd worker configuration."
  systemctl enable "$SDM_UNIT" </dev/null >/dev/null 2>&1 || kit_die $KIT_EXIT_FAIL "systemctl enable $SDM_UNIT failed." "" "systemctl enable $SDM_UNIT; systemctl status $SDM_UNIT"
  ok "$SDM_UNIT enabled at boot"
  st=$(kit_unit_prop "$SDM_UNIT" ActiveState)
  if [[ $st != active && $st != activating && $st != reloading ]] || [ -n "$INST_PENDING" ] || [ "${INST_NEED_RESTART:-0}" = 1 ]; then
    since=$(date '+%Y-%m-%d %H:%M:%S')
    systemctl reset-failed "$SDM_UNIT" </dev/null >/dev/null 2>&1 || true
    if [ "$st" = active ]; then
      warn "restarting $SDM_UNIT to apply changes (this worker's active sessions drop; clients reconnect via other workers)"
    fi
    systemctl restart "$SDM_UNIT" </dev/null || inst_start_failed "$since" ""
  else
    info "checking readiness of the active $SDM_UNIT without restarting it"
  fi
  nres0=$(kit_unit_prop "$SDM_UNIT" NRestarts)
  info "waiting up to ${timeout}s for 'running proxy worker' and 'initial authsync complete' in the current invocation"
  while :; do
    if invocation=$(inst_live_invocation); then
      ready=$(inst_invocation_messages "$invocation" | awk '
        /running proxy worker/ { running = 1 }
        /initial authsync complete/ { auth = 1 }
        running && auth { print "ready"; exit }
      ') || true
      # Recheck after reading the journal in case systemd replaced the worker.
      if [ "$ready" = ready ] && [ "$(inst_live_invocation)" = "$invocation" ]; then
        if [ -n "$INST_PENDING" ]; then
          sync && rm -f -- "$INST_PENDING_FILE" || inst_failed "Cannot clear pending worker activation."
          INST_PENDING=""
        fi
        INST_NEED_RESTART=0
        ok "$SDM_UNIT is active: running proxy worker, initial authsync complete (${t}s)"
        [ -n "$since" ] || ok "$SDM_UNIT kept running"
        return 0
      fi
    fi
    [ "$t" -lt "$timeout" ] || break
    if [ -n "$since" ] && [ "$(kit_unit_prop "$SDM_UNIT" ExecMainStatus)" = 203 ]; then break; fi
    nres=$(kit_unit_prop "$SDM_UNIT" NRestarts)
    if [[ $nres =~ ^[0-9]+$ && $nres0 =~ ^[0-9]+$ ]] && [ $((nres - nres0)) -ge 3 ]; then break; fi
    sleep 1; t=$((t+1))
  done
  inst_start_failed "$since" "$invocation"
}

inst_start_failed() {
  local since=$1 invocation=${2:-} j port why fix what="$SDM_UNIT did not come up."
  port=$(inst_bind_port "$INST_BIND")
  info "Use journalctl locally to inspect detailed worker errors."
  if [ -n "$since" ]; then
    j=$(journalctl -b -u "$SDM_UNIT" --since "$since" --no-pager -o cat 2>/dev/null </dev/null; systemctl status "$SDM_UNIT" --no-pager 2>/dev/null </dev/null)
  else
    what="Readiness of $SDM_UNIT could not be verified."
    j=""
    if [ -n "$invocation" ]; then j=$(inst_invocation_messages "$invocation"); fi
  fi
  j=$(printf '%s' "$j" | tr '[:upper:]' '[:lower:]')
  if [[ $j == *"203/exec"* ]]; then
    why="systemd could not execute $SDM_BIN (203/EXEC): SELinux label or a noexec mount."
    fix="ls -Z $SDM_BIN; inspect the host SELinux policy and mount options
findmnt -T $SDM_BIN -o TARGET,OPTIONS     # must not be noexec"
  elif [[ $j == *"address already in use"* || $j == *"cannot bind"* ]]; then
    why="Port $port is already in use, so the worker cannot listen on $INST_BIND."
    fix="ss -ltnp 'sport = :$port'      # find the other program
stop it, or re-run with export SDM_BIND_ADDRESS=:8444"
  elif [[ $j == *"invalid proxy cluster key"* || $j == *"proxy cluster key authentication"* ||
          $j == *"proxyclusterkey"* || $j == *"unauthenticated"* || $j == *"unauthorized"* ||
          $j == *"invalid credentials"* || $j == *"invalid access key"* || $j == *"authentication failed"* ]]; then
    why="The control plane rejected the proxy cluster keys (wrong key, deleted key, or another region)."
    fix="Admin UI > Networking > Proxy Clusters > your cluster: create a new key pair
re-run this kit with the new keys (it re-installs when the keys change)"
  elif [[ $j == *"no such host"* || $j == *"i/o timeout"* || $j == *"connection refused"* || $j == *"dial tcp"* || $j == *"x509"* || $j == *"tls:"* || $j == *"deadline exceeded"* ]]; then
    why="The worker cannot reach the control plane at $SDM_APP_DOMAIN (DNS, firewall, proxy or TLS inspection)."
    fix="curl -sv https://$SDM_APP_DOMAIN/ -o /dev/null
allow outbound 443 to $SDM_APP_DOMAIN; for a proxy add HTTPS_PROXY=... to $SDM_SYSCONFIG and systemctl restart $SDM_UNIT"
  elif [[ $j == *"secretenv: read source"* || $j == *"secretenv: decrypt"* || $j == *"secretenv: parse"* ]]; then
    why="The worker could not read its sealed secrets file."
    fix="runuser -u sdm -- env SDM_HOME=$SDM_HOME_DIR $SDM_BIN nodesecrets list
ls -l $SDM_SIDECAR      # must be owned by $SDM_USER"
  else
    why="The current worker invocation did not provide both startup messages within ${KIT_START_TIMEOUT:-90}s. Inspect the local journal."
    fix="journalctl -u $SDM_UNIT -f
run this kit again and choose 2 (debug) for verbose logs"
  fi
  kit_die $KIT_EXIT_FAIL "$what" "$why" "$fix"
}

# ============================================================================
# STEP 12: no secret left behind
# ============================================================================
inst_verify_scrub() {
  kit_step 12 $INST_TOTAL "Check that no secret was left in plaintext"
  local v leaked=0
  for v in SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY DELINEA_PASSWORD; do
    [ -n "${!v:-}" ] || continue
    if inst_file_contains "$SDM_SYSCONFIG" "${!v}"; then
      fail "$v is present in plaintext in the worker environment file"; leaked=1
    fi
    if [ -n "${KIT_LOG_FILE:-}" ] && inst_file_contains "$KIT_LOG_FILE" "${!v}"; then fail "$v value found in the transcript $KIT_LOG_FILE"; leaked=1; fi
  done
  [ $leaked = 0 ] && ok "no secret values in $SDM_SYSCONFIG${KIT_LOG_FILE:+ or the transcript}"
  info "secret variables are wiped from this shell when the kit exits"
  [ "$leaked" = 0 ]
}

# ============================================================================
# STEP 13: summary
# ============================================================================
inst_final() {
  kit_step 13 $INST_TOTAL "Summary"
  local port ver st en sealed fw=""
  port=$(inst_bind_port "$INST_BIND")
  ver=$(inst_installed_version); st=$(kit_unit_prop "$SDM_UNIT" ActiveState); en=$(systemctl is-enabled "$SDM_UNIT" 2>/dev/null </dev/null)
  inst_sealed_keys >/dev/null 2>&1; sealed=$(kit_trim "${INST_SEALED_KEYS:-}")
  if kit_have firewall-cmd && [ "$(firewall-cmd --state 2>/dev/null)" = running ]; then
    firewall-cmd --query-port="$port/tcp" >/dev/null 2>&1 || fw="firewall-cmd --permanent --add-port=$port/tcp && firewall-cmd --reload"
  elif kit_have ufw && ufw status 2>/dev/null | grep -q '^Status: active'; then
    ufw status 2>/dev/null | grep -qE "^$port(/tcp)?[[:space:]]" || fw="ufw allow $port/tcp"
  fi
  printf '\n%s+----------------------------------------------------------------------+%s\n' "$C_ACC" "$C_RST"
  printf '%s|%s %s%-68s%s\n' "$C_ACC" "$C_RST" "$C_HEAD" "Proxy cluster worker installed" "$C_RST"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "result" "$INST_CLASS -> $([ "$INST_DO_INSTALL" = 1 ] && echo installed || echo kept/repaired)"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "user" "$SDM_USER (home $SDM_USER_HOME)"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "SDM_HOME" "$SDM_HOME_DIR"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "binary" "$SDM_BIN ${ver:-?}"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "unit" "$SDM_UNIT: $st, ${en:-?}"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "region / bind" "$SDM_APP_DOMAIN / $INST_BIND"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "sealed keys" "${sealed:-none}"
  [ -n "${INST_BACKUP_PATH:-}" ] && printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "backup" "$INST_BACKUP_PATH"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "logs" "journalctl -u $SDM_UNIT -f"
  printf '%s|%s %-20s %s\n' "$C_ACC" "$C_RST" "verify" "run this kit again and choose 3 to verify"
  printf '%s+----------------------------------------------------------------------+%s\n' "$C_ACC" "$C_RST"
  if [ -n "$fw" ]; then
    warn "the host firewall is active and port $port/tcp is not open; clients cannot reach this worker"
    note "$fw"
  fi
  kit_summary
}

# ============================================================================
# mode_install
# ============================================================================
mode_install() {
  INST_DO_INSTALL=0; INST_NEED_RESTART=0; INST_TMP=""; INST_NEW_BIN=""; INST_BACKUP_PATH=""
  kit_log_init install
  kit_banner "New install - install or repair a proxy cluster worker"
  inst_preflight
  kit_lock_changes
  # A killed debug shell releases the kit lock while its expiry timer stays armed.
  if declare -F dbg_recover_sessions >/dev/null; then
    dbg_recover_sessions || inst_failed "Cannot finish the interrupted debug session before changing the worker."
  fi
  inst_replacement_recover || inst_failed "The previous replacement could not be restored. Inspect the rollback journal in $KIT_DIR/replacement before retrying."
  inst_read_pending
  if [ -e "$SDM_SYSCONFIG" ] || [ -L "$SDM_SYSCONFIG" ]; then
    kit_trusted_file "$SDM_SYSCONFIG" || inst_failed "Review ownership and permissions on the existing worker environment before installation."
  fi
  inst_collect
  inst_deps
  inst_reach
  inst_report_and_decide
  if { [ "${INST_OURS:-0}" = 1 ] || [ "$INST_CLASS" = NONE ]; } &&
     { [ "$INST_DO_INSTALL" = 1 ] || [ "${INST_ROTATE_DELINEA:-no}" = yes ] || { [ "$INST_DELINEA" = yes ] && [ "$INST_KEEP_DELINEA" = 0 ]; }; } &&
     [ -n "$(inst_strip_quotes "$(kit_envfile_get "$SDM_SYSCONFIG" SDM_SECRETS_FILE)")" ]; then
    inst_failed "SDM_SECRETS_FILE selects an external credential source. Update credentials there, or remove the setting to provision sealed credentials with the kit."
  fi
  inst_binary
  kit_step 7 $INST_TOTAL "Prepare account and replace approved foreign installs"
  mkdir -p /etc/sysconfig && kit_trusted_dir /etc/sysconfig || inst_failed "Unsafe worker environment directory."
  [ ! -L "$SDM_SYSCONFIG" ] || inst_failed "Worker environment file is a symbolic link."
  if [ "$INST_DELINEA" != yes ] && kit_envfile_has "$SDM_SYSCONFIG" DELINEA_PASSWORD; then inst_failed "Enable Delinea provisioning to migrate existing plaintext credentials."; fi
  inst_ensure_user account-only
  inst_replace_foreign
  inst_prepare_worker_home
  if [ "$INST_DO_INSTALL" = 1 ]; then
    kit_step 8 $INST_TOTAL "Provision the worker and seal cluster credentials"
    inst_mark_pending provision
    inst_run_install
    inst_mark_pending activate
  else
    kit_step 8 $INST_TOTAL "Repair the existing worker in place"
    inst_repair
  fi
  inst_envfile
  inst_seal
  local k
  for k in SDM_PROXY_CLUSTER_ACCESS_KEY SDM_PROXY_CLUSTER_SECRET_KEY DELINEA_PASSWORD; do
    kit_envfile_has "$SDM_SYSCONFIG" "$k" && inst_failed "Plaintext $k remains in the worker environment file."
  done
  inst_replacement_validate_worker
  inst_start
  inst_verify_scrub || inst_failed "A plaintext credential remains after installation."
  inst_replacement_commit
  inst_final
}

# ---------------------------------------------------------------- src/main.sh
# shellcheck shell=bash
# ============================================================================
# sdm-proxy-cluster-kit :: src/main.sh  (entry point; last file in the build)
# Picks a mode from KIT_MODE or the 1/2/3 menu and dispatches to
#   mode_install  (src/modes/install.sh)
#   mode_debug    (src/modes/debug.sh)
#   mode_check    (src/modes/check.sh)
# Each mode function owns its own kit_log_init/kit_banner and returns an exit code.
# ============================================================================
# @env KIT_MODE  install | debug | check - skip the menu (required when there is no terminal)
# @env KIT_NONINTERACTIVE  1 = never prompt even if a terminal exists; every input must come from env vars
# @env NO_COLOR  any value disables colour output
kit_main() {
  local choice=""
  case "${1:-}" in
    -h|--help) kit_usage; return 0;;
    --version) echo "$KIT_NAME $KIT_VERSION"; return 0;;
    install|debug|check) KIT_MODE=$1;;
    "") ;;
    *) kit_usage; return $KIT_EXIT_USAGE;;
  esac
  if [ -z "${KIT_MODE:-}" ]; then
    kit_noninteractive && kit_die $KIT_EXIT_USAGE "No mode selected." "There is no terminal to show the menu on." "export KIT_MODE=install   # or debug / check"
    kit_banner "Choose what to do"
    kit_pick choice "What do you want to do on $(kit_hostname)?" \
      "New install   - install or repair a proxy cluster worker (user '$SDM_USER')" \
      "Debug install - verbose logging, follow the logs, auto-revert when done" \
      "Check install - read-only health check, incl. Delinea credential test"
    case $choice in New*) KIT_MODE=install;; Debug*) KIT_MODE=debug;; Check*) KIT_MODE=check;; esac
  fi
  case $KIT_MODE in
    install) mode_install;;
    debug)   mode_debug;;
    check)   mode_check;;
    *) kit_die $KIT_EXIT_USAGE "Unknown KIT_MODE '$KIT_MODE'." "" "export KIT_MODE=install   # or debug / check";;
  esac
}
kit_usage() {
  cat <<EOF
$KIT_NAME $KIT_VERSION - install, debug and check StrongDM proxy cluster workers.
usage: bash $KIT_NAME.sh [install|debug|check]     (no argument = interactive menu)
Non-interactive (cloud-init etc.): set KIT_MODE and the variables listed in README.md.
EOF
}
kit_main "$@"
